/* retired duplicate ownerVitalCaps */

function syncOwnerVitalCaps(onGrowth=false){
  const oldHp=Number(state.maxHp)||1,oldMind=Number(state.maxMind)||1;
  const caps=ownerVitalCaps(state.owner);
  if(onGrowth){
    state.hp=clamp(Number(state.hp||0)+Math.max(0,caps.maxHp-oldHp),1,caps.maxHp);
    state.mind=clamp(Number(state.mind||0)+Math.max(0,caps.maxMind-oldMind),0,caps.maxMind);
  }else{
    state.hp=clamp(Number(state.hp||0),1,caps.maxHp);
    state.mind=clamp(Number(state.mind||0),0,caps.maxMind);
  }
  state.maxHp=caps.maxHp;state.maxMind=caps.maxMind;
}

