function partRarity(id){const slot=findPartSlot(id);const key=slot?PART_CATALOG[slot][id]?.rarity:"common";return RARITY_DEF[key]||RARITY_DEF.common;}
function rarityBadge(id){return '';}
function rarityFrameClass(id){const slot=findPartSlot(id),key=slot?PART_CATALOG[slot][id]?.rarity:"common";return `part-rarity-${key}`;}
function rarityText(id){return "";}
function partItem(slot){return PART_CATALOG[slot]?.[state.weapon.parts[slot]];}
function spareCount(id){return state.weapon.spareParts[id]||0;}
function discoverPart(id){if(!id)return;state.discoveredParts=Array.isArray(state.discoveredParts)?state.discoveredParts:[];if(!state.discoveredParts.includes(id))state.discoveredParts.push(id);}
function addSpare(id,n=1){discoverPart(id);state.weapon.spareParts[id]=(state.weapon.spareParts[id]||0)+n;if(state.weapon.spareParts[id]<=0)delete state.weapon.spareParts[id];}
function findPartSlot(id){return Object.keys(PART_CATALOG).find(slot=>PART_CATALOG[slot]?.[id])||null;}
function equippedPartIds(){return Object.values(state.weapon.parts||{});}
function hasPartTag(tag){return equippedPartIds().some(id=>{const slot=findPartSlot(id);return !!PART_CATALOG[slot]?.[id]?.tags?.includes(tag);});}
function partTagNames(id){const slot=findPartSlot(id);return PART_CATALOG[slot]?.[id]?.tags||[];}
const PART_STAT_META={power:"위력",precision:"정밀",toughness:"견고",handling:"조작성",maxResonance:"최대공명",resonanceRecovery:"공명회복",firstHandling:"첫턴 조작성",length:"길이",weight:"중량",carryWeight:"휴대중량"};
function fmtDeltaNum(key,v){if(key==='weight'||key==='carryWeight')return `${v>0?'+':''}${v.toFixed(2)}kg`;if(key==='length')return `${v>0?'+':''}${Math.round(v)}cm`;return `${v>0?'+':''}${Math.round(v*10)/10}`;}
function previewWeaponSwap(slot,id){
  const w={...state.weapon},cur=PART_CATALOG[slot]?.[state.weapon.parts[slot]]?.mods||{},m=PART_CATALOG[slot]?.[id]?.mods||{};
  ["power","precision","toughness","handling","maxResonance","resonanceRecovery","firstHandling","length","weight","carryWeight"].forEach(k=>{w[k]=(state.weapon[k]||0)+(m[k]||0)-(cur[k]||0);});
  return w;
}
function partDeltaHtml(slot,id){
  const cur=PART_CATALOG[slot]?.[state.weapon.parts[slot]]?.mods||{},m=PART_CATALOG[slot]?.[id]?.mods||{};
  const keys=["power","precision","toughness","handling","maxResonance","resonanceRecovery","firstHandling","length","weight","carryWeight"];
  const bits=[];
  for(const k of keys){const d=(m[k]||0)-(cur[k]||0);if(Math.abs(d)<.001)continue;let cls='partNeutral';if(!['length','weight','carryWeight'].includes(k))cls=d>0?'partBuff':'partDebuff';bits.push(`<span class="${cls}">${PART_STAT_META[k]} ${fmtDeltaNum(k,d)}</span>`);}
  const before=new Set(activeBuilds(state.weapon).map(x=>x.id)),after=activeBuilds(previewWeaponSwap(slot,id));
  const gained=after.filter(x=>!before.has(x.id)),lost=[...before].filter(x=>!after.some(y=>y.id===x)).map(x=>BUILD_RULES.find(y=>y.id===x));
  if(gained.length)bits.push(...gained.map(x=>`<span class="partBuff">빌드 활성 · ${x.name}</span>`));
  if(lost.length)bits.push(...lost.filter(Boolean).map(x=>`<span class="partDebuff">빌드 해제 · ${x.name}</span>`));
  return bits.length?`<div class="partDelta">${bits.join('')}</div>`:`<div class="partDelta"><span class="partNeutral">현재 장착품과 수치 동일</span></div>`;
}
const BUILD_RULES=[
 {id:"breaker",name:"파쇄형",check:w=>w.power>=18&&w.weight>=1.42,desc:"강공 피해 +18% · 강공 명중 -4%p · 도적 방패 반격 자세를 더 쉽게 무너뜨림"},
 {id:"duelist",name:"결투형",check:w=>w.precision>=17&&w.handling>=15&&w.weight<=1.36,desc:"명중 +5%p · 치명 +4%p · 반격 +8%p · 기본 피해 -6% · 거미줄/후퇴 페널티 완화"},
 {id:"bulwark",name:"철벽형",check:w=>w.toughness>=17&&w.weight>=1.36,desc:"방어 자세 피해 -12% · 회피 -6%p"},
 {id:"deep_core",name:"심층공명형",check:w=>w.maxResonance>=100&&w.resonanceRecovery<=8,desc:"전투 시작 공명 +15 · 턴 공명 회복 -1 · Core 개입 중 점액 응집 흡수 일부 관통"},
 {id:"cycle_core",name:"순환공명형",check:w=>w.maxResonance<=75&&w.resonanceRecovery>=13,desc:"공명 비용 16 이하 카드 비용 -2 · Core 개입 중 점액 응집 흡수 일부 관통"}
];
function activeBuilds(w=state.weapon){return BUILD_RULES.filter(x=>x.check(w));}
function buildHtml(w=state.weapon){const arr=activeBuilds(w);return `<div class="buildBox"><b>현재 빌드 효과</b><div>${arr.length?arr.map(x=>`<span class="buildChip">${x.name}</span>`).join(''):'<span class="buildChip">균형형</span>'}</div><span class="partNote">${arr.length?arr.map(x=>`${x.name}: ${x.desc}`).join('<br>'):'특정 임계치를 넘으면 스탯 조합 자체가 전투 규칙을 바꾼다.'}</span></div>`;}

