function costText(cost={}){
  const names={gold:"G",iron:"철광석",shell:"갑각",bronze:"청동",leather:"가죽",wood:"목재",steel:"강철",silverWire:"은사",wax:"밀랍",cloth:"직물",horn:"뿔"};
  return Object.entries(cost).map(([k,v])=>k==='gold'?`${v}G`:`${names[k]||k} ${v}`).join(' · ')||'보유';
}
function canPay(cost={}){return Object.entries(cost).every(([k,v])=>k==='gold'?state.gold>=v:(state.weapon.materials[k]||0)>=v);}
function payCost(cost={}){Object.entries(cost).forEach(([k,v])=>{if(k==='gold')state.gold-=v;else state.weapon.materials[k]=(state.weapon.materials[k]||0)-v;});}
function fmtPct(v){return String(Math.round(Number(v)||0))+"%";}
function marketPartPrice(id){const slot=findPartSlot(id),it=slot&&PART_CATALOG[slot][id],r=partRarity(id);return it?.shopPrice||Math.max(8,Math.round(((it?.cost?.gold)||10)*1.35+r.rank*4));}
function marketEligibleParts(){return Object.entries(PART_CATALOG).flatMap(([slot,items])=>Object.entries(items).filter(([id,it])=>!it.requiresSkill&&it.market!==false).map(([id,it])=>({id,slot,it,rarity:it.rarity||'common'})));}
function weightedMarketPart(exclude=new Set()){
  const pool=marketEligibleParts().filter(x=>!exclude.has(x.id));if(!pool.length)return null;
  const weighted=[];for(const x of pool){const r=RARITY_DEF[x.rarity]||RARITY_DEF.common;const copies=Math.max(1,Math.round(r.weight));for(let i=0;i<copies;i++)weighted.push(x);}return choice(weighted);
}
function generateMarketPartStock(){const out=[],used=new Set();const count=state.mainStory?.flags?.ismaros_network?5:4;for(let i=0;i<count;i++){const x=weightedMarketPart(used);if(!x)break;used.add(x.id);discoverPart(x.id);out.push({id:x.id,slot:x.slot,sold:false,price:marketPartPrice(x.id)});}return out;}

