function currentMainMeta(){ensureMainStory();if(state.mainStory.prototypeEnd)return {title:"제2장 완료",desc:"제3장 「잃어버린 바람」은 다음 MAIN 구현 패스에서 열린다."};return MAIN_STORY_META[state.mainStory.node]||{title:"MAIN",desc:"항해가 이어진다."};}
function mainStoryLabel(){ensureMainStory();if(state.mainStory.prototypeEnd)return "2장 완료";const g=mainGateStatus();if(g.pending&&!g.available)return "출항 대기";if(g.forced)return "강제 출항";return mainChapterMeta().short;}
function markCallback(id,text){ensureMainStory();if(!state.firstYear.callbacks.includes(id)){state.firstYear.callbacks.push(id);if(text)addWorldFact(text,`callback:${id}`);addLog(`Callback 회수 — ${text||id}`);}}
function markConnection(id,text){ensureMainStory();if(!state.firstYear.connections.includes(id)){state.firstYear.connections.push(id);if(text)addWorldFact(text,`connection:${id}`);}}
function mainAdjust(delta={}){
  ensureMainStory();const e=state.mainStory.expedition,changes=[];
  const apply=(k,label,min,max)=>{if(!Number(delta[k]))return;const before=e[k];e[k]=clamp(e[k]+Number(delta[k]),min,max);const d=e[k]-before;if(d)changes.push(`${label} ${d>0?'+':''}${d}${k==='ship'?'%':''}`);};
  apply('supplies','보급',0,99);apply('ship','함선',0,100);apply('crew','선원',0,99);
  for(const [k,label,max] of [['gold','GOLD',999],['hp','HP',state.maxHp],['mind','정신',state.maxMind],['dur','내구',state.weapon.maxDur],['resonance','공명',state.weapon.maxResonance]]){
    if(!Number(delta[k]))continue;const obj=k==='dur'||k==='resonance'?state.weapon:state;const prop=k;const before=obj[prop];obj[prop]=clamp(before+Number(delta[k]),0,max);const d=obj[prop]-before;if(d)changes.push(`${label} ${d>0?'+':''}${d}`);
  }
  return changes;
}
function mainCommit(choiceId,nextNode,flagPatch={},fact="",callbackId=""){
  ensureMainStory();Object.assign(state.mainStory.flags,flagPatch);state.mainStory.history.push({node:state.mainStory.node,choice:choiceId,year:state.year,month:state.month});
  if(fact)addWorldFact(fact,`main:${state.mainStory.node}:${choiceId}`);if(callbackId)markCallback(callbackId,fact||callbackId);
  state.mainStory.node=nextNode;state.mainStory.chapter=chapterFromNode(nextNode);
  saveGame();
}
function addChapterResult(chapter,result,reward){ensureMainStory();if(!state.mainStory.chapterResults.some(x=>x.chapter===chapter))state.mainStory.chapterResults.push({chapter,result,year:state.year,month:state.month});if(reward&&!state.mainStory.chapterRewards.some(x=>x.chapter===chapter&&x.reward===reward))state.mainStory.chapterRewards.push({chapter,reward});clearMainGate();}

