function allActionDefs(policy){return [...(ACTION_OPTIONS[policy]||[]),...(FOLLOWUP_ACTION_OPTIONS[policy]||[])];}
function actionDefByKey(key){for(const p of ['contract','explore','investigate','rest']){const x=allActionDefs(p).find(v=>v.key===key);if(x)return x;}return null;}
function incidentDef(key){return WORLD_INCIDENTS[key]||null;}
function ensureWorldEngine(){
  state.worldIncidents=state.worldIncidents&&typeof state.worldIncidents==='object'?state.worldIncidents:{};
  const fresh=Object.keys(state.worldIncidents).length===0;
  state.worldCallbacks=Array.isArray(state.worldCallbacks)?state.worldCallbacks:[];
  state.worldRegions=state.worldRegions&&typeof state.worldRegions==='object'?state.worldRegions:{};
  state.monthCandidateCache=state.monthCandidateCache&&typeof state.monthCandidateCache==='object'?state.monthCandidateCache:{};
  state.partOrigins=state.partOrigins&&typeof state.partOrigins==='object'?state.partOrigins:{};
  const now=absMonth();
  for(const [k,m] of Object.entries(WORLD_INCIDENTS)){
    if(!state.worldIncidents[k])state.worldIncidents[k]={status:m.kind==='followup'?'hidden':'active',openedAt:now,completedAt:null,outcome:''};
  }
  for(const [k,v] of Object.entries(WORLD_REGION_DEFAULTS))if(!state.worldRegions[k])state.worldRegions[k]={...v};
  if(fresh&&Array.isArray(state.eventHistory)){
    for(const h of state.eventHistory){
      if(h?.result!=='chosen'||typeof h.event!=='string')continue;
      const [policy,route]=h.event.split(':');const a=(ACTION_OPTIONS[policy]||[]).find(x=>x.route===route&&!x.variant)||(ACTION_OPTIONS[policy]||[]).find(x=>x.route===route);if(!a)continue;
      const m=WORLD_INCIDENTS[a.key],r=state.worldIncidents[a.key];if(!m||!r||r.status!=='active')continue;
      const doneAt=absMonth(Number(h.year)||state.year,Number(h.month)||state.month);r.completedAt=doneAt;r.outcome='이전 버전 기록';r.status=m.followup?'resolved':'closed';
      if(m.followup){const fr=state.worldIncidents[m.followup];if(fr?.status==='hidden'&&!state.worldCallbacks.some(x=>x.followKey===m.followup)){state.worldCallbacks.push({id:`cb:migrate:${a.key}:${m.followup}`,sourceKey:a.key,followKey:m.followup,due:doneAt+Math.max(1,m.delay||1),text:m.callback||'이전 사건의 여파가 다시 모습을 드러냈다.',applied:false});}}
    }
  }
}
function incidentState(key){ensureWorldEngine();return state.worldIncidents[key];}
function stableIncidentRoll(seed){let h=2166136261;for(const ch of String(seed)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619);}return ((h>>>0)%10000)/10000;}
function scheduleWorldCallback(sourceKey,followKey){
  const m=incidentDef(sourceKey),rec=incidentState(followKey);if(!m||!followKey||!rec||rec.status!=='hidden')return;
  if(state.worldCallbacks.some(x=>x.followKey===followKey&&!x.applied))return;
  state.worldCallbacks.push({id:`cb:${sourceKey}:${followKey}`,sourceKey,followKey,due:absMonth()+Math.max(1,m.delay||1),text:m.callback||'이전 사건의 여파가 다시 모습을 드러냈다.',applied:false});
}
function processWorldCallbacks(){
  ensureWorldEngine();const now=absMonth();
  for(const cb of state.worldCallbacks){
    if(cb.applied||cb.due>now)continue;
    const rec=incidentState(cb.followKey);if(rec&&rec.status==='hidden'){rec.status='followup';rec.openedAt=now;addWorldFact(cb.text,cb.id);addLog(`후속 사건 — ${cb.text}`);}cb.applied=true;
  }
}
function incidentExpiryText(key){return {
  escort:'카론의 상단은 다른 호위대를 구해 서쪽 고개를 떠났다.',guard:'7번 창고 계약은 항만 경비대 직할로 넘어갔다.',hunt:'구조가 늦어 북부 광산의 안쪽 갱도가 완전히 봉쇄됐다.',ruins:'조수가 바뀌며 해안 폐허의 입구가 장기간 물 아래로 잠겼다.',black_sail:'검은 돛 목격 이후 관련 장부가 통째로 교체됐다.'
 }[key]||'시간이 흐르며 사건의 기회가 다른 모습으로 넘어갔다.';}
function processIncidentExpiries(){
  ensureWorldEngine();const now=absMonth();
  for(const [key,m] of Object.entries(WORLD_INCIDENTS)){
    if(m.kind==='followup'||!m.expiry)continue;const rec=incidentState(key);if(rec.status!=='active')continue;
    if(now-rec.openedAt<m.expiry)continue;
    rec.status='closed';rec.outcome='시간 경과';addWorldFact(incidentExpiryText(key),`expired:${key}`);
    const reg=state.worldRegions[m.region];if(reg)reg.danger=Math.min(4,(reg.danger||0)+1);
  }
}
function candidateWorldDifficulty(a){
  ensureWorldEngine();let d=Number(a.difficulty)||1;const m=incidentDef(a.key),reg=m&&state.worldRegions[m.region];
  if(reg?.danger>=3)d++;if(reg?.danger<=0)d--;
  if(state.hp/state.maxHp<.45)d++;if(state.mind/state.maxMind<.35)d++;
  if(['hunt','mine','mine_reopen','mine_below'].includes(a.key)&&hasPartTag('spider'))d--;
  if(['ruins','ruins_deep','ruins_second'].includes(a.key)&&(hasPartTag('tide')||hasPartTag('waterproof')))d--;
  return clamp(d,1,4);
}

/* retired duplicate actionCandidatesForPolicy */

function refreshMonthlyCandidateCache(){state.monthCandidateCache={stamp:`${state.year}-${state.month}`};for(const p of ['contract','explore','investigate','rest'])actionCandidatesForPolicy(p,true);}
function applyRegionOutcome(meta,failed,policy){
  if(!meta)return;const r=state.worldRegions[meta.region];if(!r)return;
  if(failed){r.danger=clamp((r.danger||0)+1,0,4);return;}
  if(policy==='contract'){r.danger=clamp((r.danger||0)-1,0,4);r.prosperity=clamp((r.prosperity||0)+1,0,4);}
  else if(policy==='investigate'){r.intel=clamp((r.intel||0)+1,0,4);if(r.intel>=2)r.danger=clamp((r.danger||0)-1,0,4);}
  else if(policy==='explore'){r.intel=clamp((r.intel||0)+1,0,4);}
  else if(policy==='rest'){r.prosperity=clamp((r.prosperity||0)+1,0,4);}
}
function maybeGrantIncidentPart(candidateKey,tier,failed,ctx){
  if(failed||state.policy==='rest')return null;const pool=INCIDENT_PART_POOLS[candidateKey];if(!pool?.length)return null;
  const chance={1:.08,2:.20,3:.38,4:.62}[clamp(Number(tier)||1,1,4)];if(stableIncidentRoll(`${state.year}-${state.month}:${candidateKey}:part`)>chance)return null;
  const idx=Math.floor(stableIncidentRoll(`${candidateKey}:${state.year}:${state.month}:pick`)*pool.length)%pool.length,id=pool[idx],slot=findPartSlot(id);if(!slot)return null;
  addSpare(id,1);state.partOrigins[id]=`${state.year}년차 ${state.month}월 · ${actionDefByKey(candidateKey)?.title||candidateKey}`;ctx?.notes?.push(`파츠 획득 · ${PART_CATALOG[slot][id].name}`);return id;
}
function settleWorldIncident(ev,outcome,failed,ctx){
  if(!ev||ev.main||!ev.candidateKey)return;ensureWorldEngine();const key=ev.candidateKey,meta=incidentDef(key),rec=incidentState(key);if(!meta||!rec)return;
  rec.completedAt=absMonth();rec.outcome=String(outcome||'');rec.status=meta.kind==='followup'?'closed':(meta.followup?'resolved':'closed');
  applyRegionOutcome(meta,failed,ev.policy);if(meta.followup)scheduleWorldCallback(key,meta.followup);
  maybeGrantIncidentPart(key,ev.rewardTier||1,failed,ctx);
  const reg=state.worldRegions[meta.region];if(reg)ctx?.notes?.push(`${reg.name} 변화 · 위험 ${reg.danger}/4 · 정보 ${reg.intel}/4`);
  state.monthCandidateCache={};
}

