let activeActionCategory=null;
function actionStars(n){return '★'.repeat(clamp(Number(n)||1,1,4))+'☆'.repeat(4-clamp(Number(n)||1,1,4));}
function actionCandidate(policy,key){return allActionDefs(policy).find(x=>x.key===key)||null;}
function chooseActionCandidate(policy,key){
  const a=actionCandidate(policy,key);if(!a)return;
  state.monthEvents=(state.monthEvents||[]).filter(e=>e.main);
  const ev={id:a.route,candidateKey:a.key,variant:a.variant||'',policy,title:a.title,desc:a.desc,difficulty:candidateWorldDifficulty(a),baseDifficulty:a.difficulty,rewardTier:a.reward,rewardText:a.rewardText,phase:a.phase||'base',chosen:true};
  state.monthEvents.forEach(e=>e.chosen=false);state.monthEvents.push(ev);
  state.policy=policy;state.subChoice=a.route;activeActionCategory=policy;render();
}
function selectActionCategory(policy){activeActionCategory=policy;renderEventBoard();renderSelection();}

function addWorldFact(text,key=''){
  if(key&&state.worldFacts.some(x=>x.key===key))return;
  state.worldFacts.unshift({key:key||`fact_${Date.now()}_${Math.random()}`,text,year:state.year,month:state.month});
  if(state.worldFacts.length>30)state.worldFacts.length=30;
}
function resolveIgnoredEvents(){
  (state.monthEvents||[]).filter(e=>!e.chosen&&!e.main).forEach(e=>{
    const k=`ignored:${state.year}:${state.month}:${e.policy}:${e.id}`;
    const map={
      'contract:escort':'카론의 상단은 다른 호위대를 고용해 서쪽 고개로 떠났다.',
      'contract:hunt':'구조가 늦어져 북부 광산이 며칠간 폐쇄됐다.',
      'contract:guard':'7번 창고에서 다시 상자가 사라졌고 경비가 두 배로 늘었다.',
      'explore:ruins':'썰물이 지나 해안 폐허 입구가 다시 물에 잠겼다.',
      'explore:mine':'다른 탐험자들이 미등록 갱도 안으로 먼저 들어갔다.',
      'explore:grove':'붉은 천이 묶인 숲의 흔적 일부가 누군가에 의해 치워졌다.',
      'investigate:merc':'귀환한 용병 중 한 명이 도시를 떠났다는 소문이 돌았다.',
      'investigate:black_sail':'검은 돛 목격 이후 항만 장부 몇 장이 새로 교체됐다.',
      'investigate:priest':'신전이 납골당 출입을 잠시 막았다.',
      'rest:inn':'여관방은 다른 용병에게 넘어갔다.',
      'rest:quiet':'외곽 집의 임대가 끝났다.',
      'rest:friends':`미라는 ${state.owner.name}이 오지 않은 일을 굳이 묻지 않았다.`
    };
    const t=map[`${e.policy}:${e.id}`];if(t)addWorldFact(t,k);
    state.eventHistory.push({year:state.year,month:state.month,event:`${e.policy}:${e.id}`,result:'ignored'});
  });
}
function generateMonthEvents(){
  const ev=[];
  const gate=mainGateStatus();
  if(mainAvailable()){
    const m=currentMainMeta(),ch=mainChapterMeta();
    const desc=gate.forced?`${m.desc} 기다릴 시간이 끝났다. 확보하지 못한 조건은 이야기 속 불리함으로 남는다.`:m.desc;
    ev.push({id:'main',policy:'sail',title:`MAIN · ${ch.short} ${ch.title}`,desc,main:true,forced:!!gate.forced,chosen:false});
  }
  return ev;
}
function genMonth(){
  if(state.monthEvents?.length)resolveIgnoredEvents();
  ensureWorldEngine();processWorldCallbacks();processIncidentExpiries();
  if(ensureAilmentsV34().poison){const old=state.hp;state.hp=Math.max(1,state.hp-4);addWorldFact(`${state.owner.name}은 중독으로 체력 ${old-state.hp}을 잃었다.`, `ailment:${state.year}:${state.month}`);}
  state.resonanceTopics=new Set();state.resonanceVisits=0;state.templeMeditation=false;state.templeUsed=false;state.enhanceUsed=false;state.visitIntel=null;state.contactTopics={mira:[],karon:[]};state.marketRefreshFree=true;state.marketPaidRefreshes=0;resetMarketStock();ensureMainStory();
  recalcWeapon();state.weapon.resonance=Math.min(state.weapon.maxResonance,state.weapon.resonance+state.weapon.resonanceRecovery*3);
  state.policy=null;state.subChoice=null;activeActionCategory=null;
  const weighted=[];if(state.gold<35)weighted.push('money','money');if(state.hp<55||state.mind<45)weighted.push('rest','rest');weighted.push('investigate','explore','money','rest');if(mainAvailable())weighted.push('main');
  state.monthlyIntent=intents[choice(weighted)];state.monthlyWorry=choice(worries);
  const cond=choice(MONTH_CONDITIONS);state.monthFacts=[cond];
  state.monthEvents=generateMonthEvents().map((e,i)=>({...e,eventKey:`${state.year}-${state.month}-${i}-${e.policy}-${e.id}`,chosen:false}));
  refreshMonthlyCandidateCache();
  const forcedMain=state.monthEvents.find(e=>e.main&&e.forced);if(forcedMain){forcedMain.chosen=true;state.policy='sail';state.subChoice='main';}
  const gateNow=mainGateStatus();
  if(gateNow.pending&&!gateNow.available)state.monthFacts.push({id:'main_gate',text:`${gateNow.rule.title}: ${gateNow.rule.objective} 기한까지 ${gateNow.remaining}개월.`});
  if(gateNow.forced)state.monthFacts.push({id:'main_forced',text:gateNow.rule.forcedText});
  state.log=[];applyMonthlyStorySkills();addLog(`${state.year}년차 ${state.month}월이 시작됐다.`);addLog(cond.text);if(forcedMain)addLog('세계의 기한이 지나 메인스트림이 강제로 진행된다.');
  render();saveGame();
}
function mainAvailable(){ensureMainStory();if(state.mainStory.complete||state.mainStory.prototypeEnd)return false;const g=mainGateStatus();return !g.pending||g.available;}
function addLog(t){state.log.unshift(ownerText(t));if(state.log.length>8)state.log.pop();}
function ownerText(t){if(typeof t!=='string')return t;return state.owner?.name&&state.owner.name!=='소유자'?t.replaceAll('소유자',state.owner.name):t;}


function hashCode39(str=''){let h=0;for(let i=0;i<str.length;i++)h=(h*31+str.charCodeAt(i))>>>0;return h>>>0;}
function rarityColor39(r){return ({common:'#b2a18c',rare:'#8fb5c8',unique:'#b193d0',legendary:'#d3b46e',beyond:'#d79a87'})[r]||'#b2a18c';}
function normalizeSlotItem39(slot){const it=partItem(slot)||{name:'',rarity:'common'};const id=state.weapon.parts?.[slot]||'';return {id,name:it.name||slot,rarity:it.rarity||'common',color:rarityColor39(it.rarity||'common'),hash:hashCode39(id)};}

