function actionArt39(policy){return ({contract:'data:image/webp;base64,',explore:'data:image/webp;base64,',investigate:'data:image/webp;base64,',rest:'data:image/webp;base64,'})[policy]||'data:image/webp;base64,';}
function policyTitle39(p){return ({contract:'의뢰',explore:'탐험',investigate:'조사',rest:'휴식'})[p]||'행동';}
function missionCardHtml39(a,selected,policy){const diff=candidateWorldDifficulty(a),meta=incidentDef(a.key),reg=meta&&state.worldRegions?.[meta.region];const phase=a.phase==='followup'?'<span class="incidentPhase followup">후속</span>':a.phase==='mainResearch'?'<span class="incidentPhase">MAIN 필수</span>':'';return `<button class="actionMissionCard ${selected?'selected':''}" type="button" data-mission-pick="${a.key}" style="--mission-art:url('${actionArt39(policy)}')"><b>${a.title}${phase}</b><p>${a.desc}</p><div class="actionMissionMeta"><span>난이도 ${diff}/4</span><span>보상 ${actionStars(a.reward)}</span></div><div class="actionMissionMeta"><span>${a.rewardText}</span><span>${reg?reg.name:''}</span></div><div class="actionMissionPick">이 임무 선택</div></button>`;}
function openActionMissionPicker(policy){const opts=actionCandidatesForPolicy(policy);const selected=(state.monthEvents||[]).find(e=>e.chosen&&!e.main);const desc='이번 달 수행 가능한 '+policyTitle39(policy)+' 후보. 능력과 상황에 따라 결과가 달라진다.';const cards=opts.length?`<div class="actionMissionGrid">${opts.map(a=>missionCardHtml39(a,selected?.candidateKey===a.key,policy)).join('')}</div>`:`<div class="invEmpty">지금 이 분야에서 수행 가능한 사건이 없다.</div>`;openModal(modalHead(policyTitle39(policy)+' 후보',desc)+cards);bindClose();document.querySelectorAll('[data-mission-pick]').forEach(b=>b.onclick=()=>{chooseActionCandidate(policy,b.dataset.missionPick);closeModal();render();});}
function gearArtUrl39(id){const it=OWNER_GEAR_CATALOG[id]||{};const slot=it.slot||'';return slot==='helmet'?'data:image/webp;base64,':slot==='armor'?'data:image/webp;base64,':slot==='gloves'?'data:image/webp;base64,':'data:image/webp;base64,';}
function render(){
  if(state.owner.portrait==='odyssey'){$("heroImg").src=HERO_IMG;$("heroImg").style.display="block";$("portraitFallback").style.display="none";}else{$("heroImg").style.display="none";$("portraitFallback").style.display="block";}
  $("ownerName").textContent=state.owner.name;$("ownerSub").textContent=`제${state.generation}대 소유자 · ${state.owner.role} · ${state.owner.age}세${state.ailmentsV34?.injury?' · 부상':''}${state.ailmentsV34?.poison?' · 중독':''}`;
  $("dateText").textContent=`${state.year}년차 · ${state.month}월`;
  $("goldText").textContent=state.gold+"G";
  $("storyCountText").textContent=`${state.hp}/${state.maxHp}`;
  $("clueText").textContent=`${state.mind}/${state.maxMind}`;
  $("mainText").textContent=mainStoryLabel();
  ensureMainStory();
  const mainDone=state.mainStory.history.filter(h=>MAIN_STORY_ORDER.includes(h.node)).length;const chapterDone=state.mainStory.chapterResults.length;
  const buildNow=weaponProfile().name;
  if($("sliceMain"))$("sliceMain").textContent=`${chapterDone}/8장`;
  if($("sliceCallback"))$("sliceCallback").textContent=state.firstYear.callbacks.length;
  if($("sliceBuild"))$("sliceBuild").textContent=buildNow.length>12?buildNow.split(" + ")[0]:buildNow;
  if($("sliceProgress"))$("sliceProgress").style.width=`${Math.min(100,chapterDone/8*100)}%`;
  const gateStatus=mainGateStatus();
  if($("sliceStatus"))$("sliceStatus").textContent=state.mainStory.prototypeEnd?"2장 완성":gateStatus.pending&&!gateStatus.available?`제${state.mainStory.chapter}장 출항 대기`:gateStatus.forced?`제${state.mainStory.chapter}장 강제 출항`:`제${state.mainStory.chapter}장 진행`;
  if($("sliceHook")){
    let hook="";
    if(gateStatus.pending&&!gateStatus.available){const known=(gateStatus.facts||[]).map(x=>x.text).slice(-2).join(' / ')||'아직 확보한 항해 정보가 없다';hook=`${gateStatus.rule.title} · ${gateStatus.rule.objective} · ${known} · 기한 ${gateStatus.remaining}개월`;
    }else if(gateStatus.forced){hook=`${gateStatus.rule.forcedText}`;
    }else hook=state.firstYear.callbacks.length?`최근 Callback · ${state.firstYear.callbacks[state.firstYear.callbacks.length-1]}`:state.firstYear.connections.length?`장비 연결 · ${state.firstYear.connections[state.firstYear.connections.length-1]}`:"과거 선택이나 장비가 이후 장면에서 실제 해결법으로 되돌아오면 이곳에 기록된다.";
    $("sliceHook").textContent=hook;
  }
  $("hpBar").style.width=(state.hp/state.maxHp*100)+"%";
  $("mindBar").style.width=(state.mind/state.maxMind*100)+"%";
  $("durBar").style.width=(state.weapon.dur/state.weapon.maxDur*100)+"%";
  $("hpText").textContent=`${state.hp}/${state.maxHp}`;
  $("mindText").textContent=`${state.mind}/${state.maxMind}`;
  $("durText").textContent=`${state.weapon.dur}/${state.weapon.maxDur}`;
  const statNow=effectiveOwnerStats(),statRaw=rawOwnerStats();
  $("martialText").innerHTML=Math.round(statNow.martial)+(statNow.mult<1?`<span class="statArrow">←${Math.round(statRaw.martial)}</span>`:'');
  $("survivalText").innerHTML=Math.round(statNow.survival)+(statNow.mult<1?`<span class="statArrow">←${Math.round(statRaw.survival)}</span>`:'');
  $("socialText").innerHTML=Math.round(statNow.social)+(statNow.mult<1?`<span class="statArrow">←${Math.round(statRaw.social)}</span>`:'');
  if($("ownerTalk")){
    const talkText=state.lastResonanceLine||(state.monthlyIntent?state.monthlyIntent.quote:(state.visitIntel||`초상화를 눌러 공명하면 ${state.owner.name}의 속마음을 들을 수 있다.`));
    $("ownerTalk").textContent=talkText;
  }
  $("weaponSpecText").textContent=`${partItem("blade").name} · ${state.weapon.length}cm · ${state.weapon.weight.toFixed(2)}kg`;
  $("wpPower").textContent=state.weapon.power;$("wpPrecision").textContent=state.weapon.precision;$("wpToughness").textContent=state.weapon.toughness;$("wpHandling").textContent=state.weapon.handling;
  $("wpMaxRes").textContent=state.weapon.maxResonance;$("wpResRec").textContent=`+${state.weapon.resonanceRecovery}`;
  $("lifeResFill").style.width=(state.weapon.resonance/state.weapon.maxResonance*100)+"%";
  $("lifeResText").textContent=`${Math.round(state.weapon.resonance)} / ${state.weapon.maxResonance}`;

  $("maintPips").innerHTML="";
  $("resonanceBtn").disabled=false;
  $("marketBtn").disabled=false;
  $("templeBtn").disabled=state.templeUsed;
  $("smithBtn").disabled=false;

  const intentKnown=state.resonanceTopics.has("intent");
  const worryKnown=state.resonanceTopics.has("worry");
  if($("intentNote")){$("intentNote").className="note"+(intentKnown?"":" unknown");$("intentNote").innerHTML=`<b>소유자의 의중</b><p>${intentKnown?state.monthlyIntent.name:"공명을 통해 확인할 수 있다."}</p>`;}
  if($("worryNote")){$("worryNote").className="note"+(worryKnown?"":" unknown");$("worryNote").innerHTML=`<b>숨은 걱정</b><p>${worryKnown?state.monthlyWorry.text:"깊은 대화가 필요하다."}</p>`;}
  if($("weaponNote")){$("weaponNote").innerHTML=`<b>검 상태</b><p>내구 ${state.weapon.dur} · 공명 ${Math.round(state.weapon.resonance)}/${state.weapon.maxResonance}<br>${partItem("blade").name}</p>`;}
  const recentWorld=state.worldFacts.slice(0,2).map(x=>x.text).join(" ");
  const worldText=[state.monthFacts.map(x=>x.text).join(" "),state.visitIntel,recentWorld].filter(Boolean).join("<br>");
  if($("worldNote")) $("worldNote").innerHTML=`<b>세계 상황</b><p>${worldText}</p>`;
  if($("intelCount")) $("intelCount").textContent=`${[intentKnown,worryKnown,true,true].filter(Boolean).length}/4 확보`;

  renderEventBoard();
  renderSelection();
  renderWeaponVisual39();

  if($("storyLog")) $("storyLog").innerHTML=state.log.map(x=>`<div class="logLine">${x}</div>`).join("");
  const btn=$("executeBtn");
  if(!state.policy||!state.subChoice){btn.disabled=true;btn.textContent="이번 달 행동을 선택하세요";}else{btn.disabled=false;btn.textContent=`「${state.monthEvents.find(e=>e.chosen)?.title||policyNames[state.policy]}」 진행`;}
}

function compatibility(policy){return {txt:'',cls:''};}
function renderEventBoard(){
  const banner=$('mainBanner');
  const mainEv=(state.monthEvents||[]).find(e=>e.main);
  if(banner){
    if(mainEv){
      banner.className='mainEventBanner show';
      const forced=mainEv.forced?' · 기한 초과':'';
      banner.innerHTML=`<div class="mainText"><small>MAIN STREAM${forced}</small><b>${mainEv.title.replace(/^MAIN · /,'')}</b><span>${mainEv.desc}</span></div><button id="mainEventBtn">${mainEv.forced?'강제 진행':'진행'}</button>`;
      $('mainEventBtn').onclick=()=>{state.monthEvents.forEach(x=>x.chosen=false);mainEv.chosen=true;state.policy=mainEv.policy;state.subChoice=mainEv.id;activeActionCategory=null;render();};
    }else{banner.className='mainEventBanner';banner.innerHTML='';}
  }
  const forcedMain=!!mainEv?.forced;
  document.querySelectorAll('[data-action-policy]').forEach(b=>{
    const p=b.dataset.actionPolicy;b.classList.toggle('active',activeActionCategory===p||state.policy===p);b.disabled=forcedMain;
    b.onclick=()=>{if(forcedMain)return;activeActionCategory=p;openActionMissionPicker(p);renderSelection();document.querySelectorAll('[data-action-policy]').forEach(x=>x.classList.toggle('active',x.dataset.actionPolicy===p));};
  });
  if($('selectionChangeBtn')) $('selectionChangeBtn').onclick=()=>openActionMissionPicker(activeActionCategory||state.policy||'contract');
}
function renderSelection(){
  const box=$('selectionBox');if(!box)return;
  const e=(state.monthEvents||[]).find(x=>x.chosen);
  box.className='selection selectionV39 show';
  if(!e){$('selectionTitle').textContent='행동을 선택하세요';$('selectionDesc').textContent='의뢰 · 탐험 · 조사 · 휴식';if($('selectionChangeBtn'))$('selectionChangeBtn').textContent='후보 보기';return;}
  $('selectionTitle').textContent=e.title||policyNames[state.policy]||'선택';
  $('selectionDesc').textContent=e.main?e.desc:`${policyNames[e.policy]||''} · 난이도 ${e.difficulty||1}/4 · 보상 기대치 ${e.rewardTier||1}/4`;
  if($('selectionChangeBtn')){$('selectionChangeBtn').textContent=(e.main?'다른 행동 보기':'후보 바꾸기');$('selectionChangeBtn').onclick=()=>openActionMissionPicker(e.policy||activeActionCategory||state.policy||'contract');}
}

