function alignmentMod(){
  const intent=state.monthlyIntent;
  if(!intent)return {success:0,mind:0};
  if(intent.preferred.includes(state.policy))return {success:5,mind:2};
  if(intent.avoid.includes(state.policy))return {success:-5,mind:-2};
  return {success:0,mind:0};
}

function storyMeta(){
  const e=state.mainStory?.expedition||{supplies:0,ship:100,crew:0};
  const displayChapter=state.storyCtx?.chapterDisplay||state.mainStory?.chapter||1;const displayMeta=MAIN_CHAPTERS[displayChapter]||mainChapterMeta();
  const mainHud=state.policy==='sail'?`<div class="mainHud"><div>보급<b>${e.supplies}</b></div><div>함선<b>${e.ship}%</b></div><div>선원<b>${e.crew}</b></div><div>현재 장<b>${displayMeta.short}</b></div></div>`:'';
  return `<div class="storyMeters">
    <div class="storyMeter">HP<b>${state.hp}</b></div>
    <div class="storyMeter">정신<b>${state.mind}</b></div>
    <div class="storyMeter">공명<b>${Math.round(state.weapon.resonance)}/${state.weapon.maxResonance}</b></div>
    <div class="storyMeter">검 내구<b>${state.weapon.dur}</b></div>
  </div>${mainHud}`;
}

function applyPrepAfterCombat(enemy,result){
  /* v1.8: 소모품은 플레이어가 전투 중 직접 사용한다. 자동 소비하지 않는다. */
}


/* @include:combat-document */
let COMBAT_SRCDOC_CACHE=null;
function getCombatSrcdoc(){
  if(COMBAT_SRCDOC_CACHE)return COMBAT_SRCDOC_CACHE;
  const bin=atob(COMBAT_DOC_B64);
  const bytes=new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
  COMBAT_SRCDOC_CACHE=new TextDecoder("utf-8").decode(bytes);
  return COMBAT_SRCDOC_CACHE;
}


/* retired duplicate launchStoryCombat */


window.addEventListener("message",e=>{
  const d=e.data;
  if(!d||d.type!=="wc-story-combat")return;
  $("combatLayer").classList.remove("show");
  const frame=$("combatFrame");
  frame.removeAttribute("src");
  frame.srcdoc="";
  ["storyMode","ownerName","enemy","enemyHpScale","enemyAttackDelta","enemyDefenseDelta","enemyEvasionDelta","hp","maxHp","mind","maxMind","martial","survival","social","weaponPower","weaponPrecision","weaponToughness","weaponHandling","maxResonance","resonanceRecovery","resonance","weaponWeight","weaponLength","firstHandling","storySkills","medkit","bandage","antidote","armorDefense","armorEvasion","armorBlock","armorResist"].forEach(k=>delete frame.dataset[k]);

  const p=state.storyCtx?.combatPending;
  if(!p)return;
  state.storyCtx.combatPending=null;
   if(p?.mods?.v32SideEncounter)state.storyCtx.v32EncounterWin=d.result==="win";

  if(Number.isFinite(d.hp)&&d.result==="win") state.hp=clamp(d.hp,1,state.maxHp);
  if(Number.isFinite(d.resonance)) state.weapon.resonance=clamp(d.resonance,0,state.weapon.maxResonance);
  if(d.items){ if(Number.isFinite(d.items.medkit))state.prep.medkit=d.items.medkit; if(Number.isFinite(d.items.bandage))state.prep.bandage=d.items.bandage; if(Number.isFinite(d.items.antidote))state.prep.antidote=d.items.antidote; }
  applyPrepAfterCombat(p.enemy,d.result);
  gainCombatExperience(p?.tier||state.storyCtx?.difficulty||1,String(p?.enemy||'').startsWith('v25_')||['ismaros','cyclops'].includes(p?.enemy),d.result==='win'?1:.35);

  if(d.result==="win"){
    recordDeed("martial",`${state.year}-${state.month}:${p.enemy}`);
    state.weapon.dur=clamp(state.weapon.dur-ri(2,7),0,100);
    showStoryNode(p.nextWin);
  }else{
    state.mind=clamp(state.mind-8,0,state.maxMind);
    state.weapon.dur=clamp(state.weapon.dur-ri(4,9),0,100);
    resolveBattleDefeatV32(p);
  }
});

function storyChoiceButton(c){
  const b=document.createElement("button");
  b.className="storyChoice"+(c.connection?" connectionChoice":"");
  b.innerHTML=`<b>${ownerText(c.label)}</b>`;
  b.onclick=()=>chooseStory(c);
  return b;
}


const NOVEL_TEXT={
"contract:escort:start":`길드 앞마당에는 먼지를 뒤집어쓴 마차 세 대가 서 있었다. 맨 앞의 말은 코끝에서 흰 김을 뿜었고, 짐칸 위에는 기름 먹인 천이 단단히 묶여 있었다. 천 사이로 향신료 냄새가 희미하게 새어 나왔다.

상인 카론은 그를 보자마자 서쪽 산등성이를 손가락으로 가리켰다.

“해 지기 전에 저 고개만 넘겨주면 38G. 늦으면 절반이다. 내 물건은 밤길을 좋아하지 않거든.”

그는 대답 대신 검자루를 한번 쥐었다. 검을 통해 손바닥의 긴장이 고스란히 전해졌다. 이번 달 돈이 필요하다고 말했던 사람의 손이었다.

문제는 길이었다. 요 며칠 서쪽 고개에서 ‘통행세’를 받는 자들이 나타났다는 소문이 돌았다. 길드에서는 도적이라고 했고, 카론은 경쟁 상단의 사주라고 했다. 어느 쪽이든 칼을 든 사람들이라는 점은 같았다.

카론은 지름길을 택하면 보수를 더 얹겠다고 했다. 안전한 북쪽 길은 멀고, 해가 지기 전에 도착할 가능성이 낮아진다. 돈과 위험이 같은 저울 위에 올라왔다.`,

"contract:escort:road":`고개가 가장 좁아지는 곳에서 수레 한 대가 비스듬히 길을 막고 있었다. 바퀴 하나가 빠져 있었지만 이상하게도 짐은 하나도 흩어지지 않았다.

수레 곁의 사내 셋이 손을 흔들었다. 도와달라는 말은 자연스러웠지만 자세는 그렇지 않았다. 옷에는 먼지가 묻어 있었는데 무릎에는 흙이 없었다. 수레를 밀었다면 생겼어야 할 흔적도 없었다. 셋 모두 한 손을 허리 가까이에 두고 있었다.

그의 엄지가 검집의 입구를 천천히 밀었다.

“사고 난 놈들 자세가 아니야.”

그가 아주 작게 말했다.

뒤에서는 카론이 시간을 재촉했다. 마차를 세우고 직접 확인할 수도 있고, 상단을 먼저 돌린 뒤 흔적을 쫓을 수도 있다. 어느 쪽이 더 나은지는 아직 알 수 없다.

검은 명령할 수 없다. 다만 이 순간 그가 어느 선택을 받아들일지, 지금까지의 공명으로 가늠할 수 있을 뿐이다.`,

"contract:escort:escort_win":`싸움이 끝난 뒤 고개에는 말의 거친 숨소리와 피 냄새만 남았다.

그는 검날에 묻은 피를 천으로 닦아냈다. 손이 조금 떨렸지만 칼끝은 아직 곧았다. 카론은 부서진 화살과 쓰러진 도적들을 번갈아 보다가 말없이 돈주머니를 던졌다.

“약속한 만큼이다.”

동전이 묵직하게 부딪쳤다.

카론은 마차에 올라타기 직전 뒤를 돌아봤다.

“다음에도 내 마차를 맡아줬으면 좋겠군. 네가 살아 있다면.”

그는 웃지 않았다. 대신 도적 하나의 팔목에 묶여 있던 낡은 천 조각을 풀어냈다. 단순한 무늬처럼 보였지만 같은 표식을 어디선가 본 기억이 검 안쪽에서 희미하게 울렸다.

돈은 의뢰의 보상이었다. 그 표식은 다음 이야기의 시작일지도 몰랐다.`,

"contract:hunt:start":`북부 광산은 사흘째 작업을 멈춘 상태였다. 갱도 입구에 도착하자 이유를 설명할 필요도 없었다. 목재 지지대 사이로 사람 팔만큼 굵은 거미줄이 여러 겹 엉켜 있었고, 그 안에는 광부의 가죽 장갑 하나가 반쯤 감겨 있었다.

실종자는 둘. 어제 새벽까지 안에서 곡괭이 소리가 들렸지만 구조조는 입구에서 거대한 그림자를 본 뒤 더 들어가지 못했다.

광산주는 55G를 내걸었다. 괴물을 죽이면 갑각과 부산물도 가져가도 좋다고 했다.

그는 검집 끝으로 거미줄을 건드렸다. 끈끈한 실이 늘어나며 금속에 달라붙었다.

“돈만 벌 거면 연기로 끌어내는 게 낫고.”

그가 어두운 갱도 안을 바라봤다.

“사람을 찾으려면 들어가야겠지.”

토벌 의뢰였지만, 어느 순간부터 문제는 괴물을 죽이는 것과 사람을 구하는 것 중 무엇을 먼저 둘 것인가로 바뀌어 있었다.`,

"contract:hunt:hunt_lure":`젖은 짚과 송진을 태운 연기가 갱도 안으로 밀려 들어갔다. 처음에는 아무 일도 없었다.

그러다 깊은 곳에서 돌을 긁는 소리가 났다.

한 번.
두 번.
세 번째에는 입구의 거미줄 전체가 떨렸다.

검은 다리 하나가 바위틈에서 튀어나왔다. 이어 몸통이 모습을 드러내자 뒤에서 기다리던 광부들이 욕설을 삼키며 물러났다. 사람 허리 높이까지 올라오는 몸집이었다. 연기에 쫓겨 나온 놈은 앞다리를 세우고 이빨을 드러냈다.

그는 검을 뽑았지만 앞으로 나가지는 않았다.

입구를 무너뜨리는 방법도 떠올랐다. 하지만 안쪽 상황을 모르는 채 길부터 닫는 것이 어떤 결과를 만들지는 아무도 알 수 없다.

죽이는 것과 봉쇄하는 것은 전혀 다른 결말이었다.`,

"contract:hunt:hunt_deep":`갱도 안으로 들어갈수록 공기는 축축하고 무거워졌다. 횃불 불꽃은 바람도 없는데 자꾸 한쪽으로 눕고, 신발 밑에서는 끈끈한 실이 끊어질 때마다 작은 소리가 났다.

세 번째 갈림길에서 신음이 들렸다.

무너진 광차 뒤에 광부 한 명이 웅크리고 있었다. 다리에는 상처가 있었지만 살아 있었다. 그가 몸을 낮춰 그를 일으키는 순간, 광부의 눈이 그의 어깨 너머를 보고 커졌다.

천장에 그림자가 있었다.

돌처럼 붙어 있던 거대한 몸이 천천히 떨어져 내려왔다. 여덟 개의 다리가 벽을 짚을 때마다 돌가루가 우수수 떨어졌다.

“뛰어.”

그가 광부를 출구 쪽으로 밀어냈다.

이제 선택은 단순해졌다. 누군가는 놈의 앞을 막아야 한다. 아니면 횃불과 어둠을 이용해 모두 함께 달아나야 한다.`,

"contract:guard:start":`항구 7번 창고는 사흘 연속 털렸다. 이상한 점은 도둑들이 욕심을 부리지 않았다는 것이다. 동전함도, 쉽게 팔 수 있는 포도주도 그대로였다. 사라진 것은 늘 같은 상단의 향신료 상자뿐이었다.

길드에서는 단순 절도라고 했지만 창고지기는 고개를 저었다.

“어떤 상자가 어디 있는지 정확히 알고 왔어. 문도 부수지 않았고.”

그날 밤 그는 등잔을 끄고 창고 안쪽에 앉았다. 건조한 후추 냄새와 젖은 밧줄 냄새가 뒤섞였다. 밖에서는 파도 소리 사이로 술 취한 선원들의 노랫소리가 조금씩 멀어졌다.

검은 그의 무릎 위에 놓여 있었다.

도둑을 잡는 것만이 목적이라면 이곳에서 매복하면 된다. 하지만 누가 물건을 받아 가는지 알고 싶다면, 일부러 놓아줘야 할 수도 있었다.

의뢰의 성공과 사건의 진실이 처음부터 같은 방향을 보고 있는 것은 아니었다.`,

"contract:guard:guard_ambush":`자정이 조금 넘자 문고리가 소리도 없이 돌아갔다.

들어온 두 사람은 등불도 켜지 않았다. 망설임 없이 세 번째 선반으로 가서 향신료 상자 두 개를 골라냈다. 길을 외운 사람들처럼 정확했다.

그는 숨을 죽이고 기다렸다.

그때 문 밖에 있던 세 번째 사내가 고개를 들었다. 달빛이 창고 틈으로 스치며 검날 끝에 한 줄 빛을 만들었다. 사내의 눈이 그 빛에 멈췄다.

“안에 누구 있다.”

낮은 목소리와 함께 칼이 뽑혔다.

지금 문을 막을 수도 있고, 한 번 더 지켜볼 수도 있다. 어느 선택이 도둑을 잡는 길이고 어느 선택이 더 큰 것을 놓치는 길인지는 아직 알 수 없다.`,

"explore:ruins:start":`썰물이 가장 깊은 날이면 절벽 아래에 돌계단이 드러난다는 이야기가 있었다. 오래전 신전으로 이어졌다는 사람도 있었고, 해적들이 숨겨둔 창고라고 말하는 사람도 있었다.

더 이상한 소문은 종소리였다. 바닷물이 완전히 빠진 밤, 아무도 없는 폐허 아래에서 청동 종이 한 번 울린다는 것이다.

그는 파도에 반쯤 잠긴 계단 앞에서 신발 끈을 다시 묶었다.

이런 곳은 보수를 약속하는 사람도, 실패를 기록하는 길드도 없다. 남는 것은 가져온 물건과 살아서 돌아온 이야기뿐이다.

그리고 검에게는, 어쩌면 그런 이야기가 돈보다 오래 남는다.

외곽부터 살필 수도 있고 중심부로 바로 들어갈 수도 있다. 지도도, 먼저 다녀온 사람의 확실한 기록도 없었다.`,

"explore:mine:start":`북부 광산의 오래된 도면에는 막다른 길로 표시된 곳이 있었다. 그런데 지난 폭우 뒤 그 벽이 무너지면서, 뒤쪽에서 또 하나의 갱도가 나왔다.

누가 팠는지 모르는 길이었다.

입구 주변에는 오래된 곡괭이 자국과 최근의 발자국이 함께 남아 있었다. 누군가 이미 안에 들어갔다는 뜻이었다. 광부들은 좋은 광맥일 거라 했고, 늙은 감독관은 그런 길은 발견하지 않은 셈 치는 게 낫다고 말했다.

그는 횃불을 높이 들었다.

탐험에는 계약서가 없다. 얼마를 벌어야 성공인지도 정해져 있지 않다. 찾은 것의 가치보다 어디까지 들어갈지를 스스로 정해야 하는 일이다.`,

"explore:grove:start":`올리브 숲 깊은 곳에는 길에서 조금 벗어난 돌기둥들이 있었다. 사냥꾼들은 그 근처에 짐승이 잘 나타나지 않는다고 말했다. 나무마다 붉은 천 조각이 묶여 있는데 누가 언제 묶었는지는 아무도 몰랐다.

그가 천 하나를 손가락으로 문질렀다. 색은 오래 바랜 것 같았지만 매듭은 최근에 묶은 것처럼 단단했다.

바람이 불자 잎들이 한꺼번에 뒤집혔다. 숲 안쪽에서 새 한 마리 날지 않았다.

이런 장소에는 대개 두 종류의 것이 남아 있다. 사람들이 일부러 숨긴 물건, 혹은 사람들이 일부러 피한 이유.

둘 중 어느 쪽인지 확인하려면 더 들어가야 했다.`,

"explore:mine:explore_deep":`갱도가 넓어지는 곳에서 오래된 광부 장비가 천장 가까이 매달려 있는 것이 보였다. 처음에는 밧줄인 줄 알았지만 횃불을 가까이 대자 희끗한 거미줄이 여러 겹 겹쳐 있었다.

그 아래에는 새로 깨진 광석 조각과 낡은 청동 장식이 함께 흩어져 있었다. 누군가 이곳에서 무언가를 캐내려 했던 흔적이었다.

그때 벽 뒤쪽에서 검은 다리 하나가 모습을 드러냈다.

거미는 길을 우연히 지나가는 괴물이 아니었다. 중심부를 둥지로 삼고 있었고, 발견물을 가져가려면 놈의 영역을 통과해야 했다.

뒤로 물러날 수도 있고 계속 들어갈 수도 있다. 어느 쪽이 더 많은 것을 남길지는 지금 판단하기 어려웠다.`,

"explore:ruins:explore_deep":`폐허 중심의 제단에는 검이 들어갈 만한 가느다란 홈이 파여 있었다. 그가 먼지를 걷어내자 금속이 닿았던 흔적이 드러났다.

검끝이 홈 가장자리를 스치는 순간 바닥 아래에서 물이 끓는 듯한 소리가 났다.

검은 점액이 돌 사이의 홈을 따라 천천히 올라왔다. 처음에는 고인 바닷물처럼 보였지만 곧 스스로 방향을 바꾸며 출구 쪽으로 퍼졌다. 안쪽에는 청동판과 부서진 칼자루가 놓여 있었다.

괴물과 싸우러 온 탐험은 아니었다. 하지만 봉인 너머의 물건을 가져가려면 이제 이 존재를 지나쳐야 했다.

물러날 수도 있다. 다만 지금 돌아가는 선택이 정말 손해인지, 오히려 다음 기회를 남기는 일인지는 알 수 없었다.`,

"explore:grove:explore_deep":`제단 가까이 갈수록 붉은 천의 매듭 모양이 일정하다는 것이 보였다. 종교적인 장식이 아니었다. 길을 표시하고 서로 위치를 알리기 위한 표식이었다.

그가 그 사실을 알아차린 것과 거의 동시에 돌기둥 뒤에서 사람이 일어났다.

한 명, 둘, 셋.

셋 모두 사냥꾼 차림이었지만 활보다 짧은 칼을 먼저 꺼냈다. 제단 뒤에는 이미 파헤친 흙과 부서진 상자, 아직 가져가지 못한 금속 조각이 쌓여 있었다.

이곳을 무서워해서 사람들이 오지 않은 게 아니었다. 누군가 무섭게 만들고 있었던 것이다.

뒤로 돌아갈 수도 있고 그대로 맞설 수도 있다. 저들이 정말 싸울 생각인지조차 아직 확실하지 않았다.`,

"rest:inn:start":`이번 달에는 아무 의뢰도 받지 않기로 했다.

처음 며칠 동안 그는 그 결정을 꽤 어색해했다. 아침에 눈을 뜨면 습관처럼 장비부터 확인했고, 점심 무렵이면 길드 쪽으로 걸어가다 중간에 방향을 틀었다. 몸은 쉬고 있었지만 생활의 속도는 쉽게 느려지지 않았다.

검은 침대 곁 벽에 기대어 있었다. 평소라면 하루에도 몇 번씩 손에 잡혔겠지만 이번에는 닦을 때를 제외하면 거의 움직이지 않았다.

일주일쯤 지나자 그의 걸음이 조금 가벼워졌다. 잠도 길어졌다.

그렇다고 세상이 함께 쉬어주는 것은 아니었다. 휴식이라는 것은 아무 일도 일어나지 않는 시간이 아니라, 일어나는 일에 어디까지 관여할지를 정하는 시간이기도 했다.`,

"rest:quiet:start":`도시 외곽의 작은 집은 밤이 되면 바람 소리밖에 들리지 않았다. 길드의 종도, 부두의 고함도 멀었다.

그는 처음 며칠 동안 거의 잠만 잤다. 깨어나면 물을 마시고, 검날을 한 번 닦고, 다시 누웠다. 평소에는 가만히 있는 것을 견디지 못하던 사람이었다.

검을 쥐는 시간도 줄었다. 그만큼 공명은 옅어졌지만 손의 떨림과 굳어 있던 어깨가 조금씩 풀리는 것은 분명했다.

이번 달의 목적은 단순하다. 살아남기 위해 소모한 몸과 정신을 다시 채우는 것.

다만 사람이 사는 곳에서 완전히 아무 일도 일어나지 않는 달은 드물다.`,

"rest:friends:start":`미라는 그가 한 달 쉬겠다고 하자 믿지 않는 얼굴을 했다.

“네가?”

그 한마디에 그는 대꾸하지 못했다.

며칠 동안은 별일이 없었다. 같이 식사를 하고, 오래 미뤄둔 이야기를 하고, 때로는 아무 말 없이 창밖을 봤다. 검은 문 옆에 세워져 있었다.

전투도 없고 보수도 없었다. 대신 그가 사람의 얼굴을 보며 웃는 시간이 늘었다.

휴식은 체력을 채우는 것만이 아니었다. 자신이 왜 계속 살아 돌아오려 하는지 확인하는 시간이기도 했다.

그런 달에도 바깥의 사건은 문을 두드릴 수 있다.`,

"rest:inn:rest_event":`한밤중에 아래층에서 의자가 넘어지는 소리가 났다. 곧이어 짧은 비명이 들렸고 여관 안이 이상할 만큼 조용해졌다.

그가 문을 조금 열어 아래를 내려다봤다.

칼을 든 두 사람이 식당 손님들을 벽 쪽으로 몰아놓고 돈주머니를 걷고 있었다. 여관주인은 바닥에 엎드린 채 움직이지 못했다. 아직 사람을 죽이지는 않았다. 돈만 챙기면 그대로 나갈 수도 있어 보였다.

그는 문을 닫으려다 멈췄다.

이번 달은 쉬는 달이다. 몸도 정신도 회복할 필요가 있다. 여기서 내려가면 며칠 동안 쌓아온 회복을 다시 잃을 수 있다.

반대로 검을 들지 않고 문을 닫는다면, 그 선택 역시 오래 남을 수 있다.`,

"rest:quiet:rest_event":`한밤중 마구간 쪽에서 말이 날카롭게 울었다. 이어 담장 너머로 무언가 떨어지는 둔탁한 소리가 났다.

그는 잠에서 깨자마자 창문으로 다가갔다. 이웃집 창고 문 앞에서 두 사람이 자루를 옮기고 있었다. 한 명은 계속 골목 끝을 살폈고, 다른 한 명의 허리에는 짧은 칼이 매달려 있었다.

이번 달은 쉬기로 했다.

그 약속은 누구와 한 것도 아니고 소유자 스스로 정한 것이었다. 몸의 통증도 거의 가라앉기 시작한 참이었다.

그는 한동안 움직이지 않았다. 그러다 침대 옆의 검을 바라봤다.

손을 뻗으면 싸움이 시작될 수 있다. 그대로 누우면 도둑들은 남의 물건을 가지고 사라질 것이다.`,

"rest:friends:rest_event":`한밤중에 아래층 문이 거칠게 열렸다. 미라가 몸을 일으키기 전에 낯선 남자의 고함이 들렸다.

빚을 받으러 왔다고 했다.

문틈으로 내려다보니 셋이었다. 처음에는 말로 끝날 것 같았지만 한 사람이 식탁을 걷어차면서 상황이 달라졌다. 허리춤에서 칼자루도 보였다.

미라는 그의 팔을 잡았다.

“이번 달은 쉬겠다며.”

그 말은 부탁인지 경고인지 알기 어려웠다.

그는 검을 바라봤다. 눈앞의 일을 막는 것과, 이번 달 자신이 정한 삶을 지키는 것이 서로 반대 방향에 서 있었다.`,

"rest:inn:rest_safe":`그는 끝내 검을 들지 않았다.

문밖의 소리는 한동안 이어졌지만 새벽이 오기 전에는 잦아들었다. 다음 날 사람들은 도둑 이야기를 했고 누군가는 왜 용병이 같은 건물에 있었는데도 나오지 않았느냐고 수군거렸다.

그는 변명하지 않았다.

대신 며칠 뒤부터 계단을 오를 때 옆구리가 당기지 않았고 밤에 깨는 횟수도 줄었다. 몸과 정신은 분명히 회복됐다.

검을 뽑지 않은 선택이 옳았는지는 숫자로 정리되지 않았다. 다만 계속 싸우려면 싸우지 않는 달도 필요했다.`,

"investigate:merc:start":`세 달 전 북쪽으로 떠난 용병단은 다섯 명이 돌아왔다. 사람들은 원래 다섯이 출발했다고 말했다.

하지만 길드의 오래된 출발 장부에는 이름이 여섯 줄 적혀 있었다.

마지막 줄은 칼로 긁어 지운 것처럼 훼손돼 있었다. 잉크 자국은 남아 있었고 옆에는 지급된 식량이 ‘6인분’이라고 적혀 있었다.

누군가 죽은 사람을 잊은 것이 아니라, 돌아온 뒤 일부러 한 사람을 없앤 흔적에 가까웠다.

이번 달의 조사는 돈이 되지 않을 수도 있다. 하지만 제대로 파고들면 검에 남길 만한 희귀한 이야기가 될 수 있다.`,

"investigate:black_sail:start":`최근 어부들 사이에서 검은 돛 이야기가 돌았다. 달이 없는 새벽이면 입항 기록에 없는 배 한 척이 외항에 나타나고, 해가 뜨기 전에 사라진다는 것이다.

이상한 점은 항만 기록에 아무 흔적도 없다는 데 있었다.

배가 실제로 없다면 여러 어부가 같은 거짓말을 할 이유가 없다. 반대로 배가 있다면 기록을 지울 수 있는 누군가가 항구 안쪽에 있다는 뜻이었다.

며칠 전에는 세관 창고의 야간 담당자가 갑자기 바뀌었다.

작은 소문 하나가 항구 전체의 거짓말로 이어질 수도 있었다.`,

"investigate:priest:start":`신전의 오래된 장부를 넘기던 중 이상한 빈칸 하나가 발견됐다. 매달 같은 날짜, 지하 납골당 출입 기록의 서명 자리가 칼끝으로 긁혀 있었다.

그런 기록이 열두 번 반복돼 있었다.

늙은 수녀 하나는 그 사제를 기억했다. 이름을 묻자 입을 닫았지만, 그가 매번 지하에서 올소유자 뒤 손을 씻고도 검은 얼룩이 사라지지 않았다고 말했다.

마지막 출입 기록 뒤로는 그 사람에 대한 기록 자체가 없다.

조사를 계속하면 신전이 숨기고 싶은 것까지 건드릴 수 있다.`,

"investigate:merc:investigate_testimony":`생존자 둘은 같은 말을 했다.

“여섯 번째 사람은 애초에 없었습니다.”

말투까지 비슷했다.

하지만 출발 전날 그들에게 술을 팔았던 주점 주인은 잔의 개수까지 기억했다. 여섯 명이 긴 탁자 하나를 차지했고 그중 한 명은 술을 거의 마시지 않았다고 했다.

“말수가 적은 친구였어. 다른 다섯이 이름을 부르긴 했는데… 이상하게 지금은 생각이 안 나네.”

그는 그 말을 듣고 검자루를 잠깐 쥐었다.

여러 사람이 같은 사람을 기억하지 못하게 된 것인지, 아니면 기억한다고 말할 수 없는 것인지 알 수 없었다. 누군가를 미행하면 더 빨리 답에 닿을 수 있다. 문서를 더 파면 칼을 뽑지 않고도 거짓말을 깰 수 있다.`,

"investigate:black_sail:investigate_testimony":`어부 셋은 서로 다른 날에 같은 배를 봤다고 말했다. 검은 돛, 낮은 선체, 등불을 거의 켜지 않은 배.

항만 관리인은 웃으며 그런 배는 없었다고 잘라 말했다.

“입항 기록에 없으면 안 온 겁니다.”

너무 빠른 대답이었다.

장부를 뒤지다 보니 더 이상한 사실이 나왔다. 검은 돛이 나타났다는 날마다 세관 창고 하나가 야간 점검 명목으로 비워져 있었다. 점검 담당자의 서명은 모두 같았다.

배가 없는 게 아니라, 배가 들어와도 기록되지 않는 길이 있는 것 같았다.`,

"investigate:priest:investigate_testimony":`늙은 수녀는 한참 동안 입을 열지 않았다. 그가 돌아서려 하자 그제야 낮은 목소리로 말했다.

“그분은 기도하러 내려간 게 아니었어요.”

매달 같은 날, 이름이 지워진 사제는 지하 납골당으로 내려갔다. 올라올 때마다 얼굴이 창백했고 손에서는 향 냄새보다 쇠 냄새가 났다.

마지막으로 본 날, 수녀가 왜 혼자 내려가느냐고 물었다고 했다.

사제는 웃지 않은 채 이렇게 답했다.

“아래에서 들리는 목소리를 잠재워야 합니다.”

그 다음 달부터 장부에서 이름이 사라졌다.`,

"investigate:merc:investigate_site":`오래된 숙소 창고에서 찢어진 장부 반쪽을 찾았다. 지워진 여섯 번째 이름은 완전히 사라지지 않았다. 먹물이 번진 틈 사이로 첫 글자가 남아 있었다.

그가 장부를 접으려는 순간 뒤에서 문이 닫혔다.

바깥에서 빗장이 걸렸다.

곧 다른 출입문 쪽에서 발소리가 들렸다. 한 사람이 아니라 둘 이상이었다. 그들은 장부가 여기 있다는 사실을 알고 있었고, 그가 그것을 찾을 가능성까지 생각한 모양이었다.

이제 질문은 ‘누가 여섯 번째였나’가 아니라 ‘누가 그 이름을 끝까지 지우려 하는가’가 됐다.

장부를 품고 나갈지, 지금은 물러날지 결정해야 했다. 밖의 사람들이 어디까지 준비했는지는 알 수 없었다.`,

"investigate:black_sail:investigate_site":`세관 창고 안쪽에는 일반 화물과 다른 상자들이 따로 쌓여 있었다. 측면에는 검은 돛을 닮은 문양이 작게 찍혀 있었다.

그가 상자 하나의 뚜껑을 들자 안에는 향신료도 술도 없었다. 여러 항구의 인장과 빈 출입증, 이름이 적히지 않은 금속 표찰이 들어 있었다.

그때 뒤에서 문이 닫혔다.

잠금쇠가 걸리는 소리 뒤로 두 사람이 걸어 나왔다. 세관 직원 복장이었지만 손에 든 것은 장부가 아니라 칼이었다.

“그 상자는 볼 필요가 없었는데.”

전투는 우연한 조우가 아니었다. 사람 둘이 출구 앞을 막고 있었다. 말로 끝날지, 칼을 뽑게 될지는 그 다음 순간에 달려 있었다.`,

"investigate:priest:investigate_site":`납골당 아래는 예상보다 넓었다. 벽마다 오래된 이름이 새겨져 있었고 바닥에는 제단을 중심으로 가느다란 홈이 퍼져 있었다.

그 홈을 따라 검은 액체가 움직였다.

처음에는 물인 줄 알았다. 하지만 횃불을 가까이 대자 액체가 불빛을 피하듯 뒤로 물러났다. 곧 여러 갈래가 하나로 뭉쳐 사람 허리 높이까지 부풀었다.

그 너머 바닥에 낡은 사제의 목걸이와 기록판이 보였다.

괴물은 우연히 이곳에 들어온 것이 아니었다. 조사하고 있는 사건의 중심을 그대로 덮고 있었다.

기록판은 저 너머에 있었다. 지금 손에 넣을지, 이 광경만 기억하고 물러날지는 그의 선택이었다.`,

"sail:main:start":`새벽 안개가 걷히기 전에 항구의 밧줄들이 하나씩 풀렸다.

오디세우스의 함대가 움직이기 시작했다.

부두에는 떠나는 사람을 부르는 목소리와 늦게 짐을 싣는 선원들의 욕설이 뒤섞였다. 그는 마지막 순간까지 육지 쪽을 돌아봤다. 이번 달에 항해를 선택한다는 것은 길드의 돈벌이도, 조용한 휴식도, 미처 끝내지 못한 사건의 추적도 모두 뒤로 미룬다는 뜻이었다.

검을 통해 그의 손에서 긴장과 기대가 동시에 느껴졌다.

바다는 월간 방침 중 하나가 아니었다. 세계의 다음 장으로 넘어가는 선택이었다.

배가 방파제를 벗어나자 도시가 빠르게 작아졌다. 이제 돌아가고 싶다고 해도 다음 항구까지는 돌아갈 수 없었다.`,

"sail:main:sail_event":`항해 셋째 주 새벽, 안개 속에서 작은 배 한 척이 나타났다.

돛은 찢어져 있었고 사람들은 물을 달라고 외쳤다. 선두 배가 속도를 줄였고 밧줄 사다리가 내려갔다. 구조된 사람들은 떨리는 몸으로 갑판에 올라왔다.

처음 몇 명은 정말 지쳐 보였다.

하지만 그는 그중 한 사람이 물동이보다 먼저 병사들의 창이 꽂힌 위치를 살피는 것을 봤다. 다른 한 명은 갑판 아래로 내려가는 계단 수를 세고 있었다.

검자루에 닿은 손에 힘이 들어갔다.

아직 오디세우스의 병사들은 눈치채지 못했다. 그가 먼저 움직일 수도 있고, 병사에게 조용히 알릴 수도 있었다.

어느 쪽이 더 많은 사람을 살릴지, 어느 쪽이 더 큰 문제를 불러올지는 아직 알 수 없었다.`
};

function novelStoryText(base){
  const key=`${state.policy}:${state.subChoice}:${state.storyCtx?.currentNode||""}`;
  // v1.4: 현재 분기에서 작성된 본문을 우선한다.
  // 예전 고정 장문 텍스트가 현재 선택/상태를 덮어써 서사가 어긋나는 문제를 막는다.
  const authored=typeof base==="string"?base.trim():"";
  const text=authored.length>=120?base:(NOVEL_TEXT[key]||base);
  return ownerText(text);
}


function rollWorldTwist(){
  const ctx=state.storyCtx;
  if(!ctx || Math.random()>.34)return "";

  const table={
    contract:[
      {t:"예상보다 이른 비가 내려 길이 질척해졌다. 카론의 계산보다 이동 속도가 늦어졌다.",e:()=>{ctx.danger+=6;state.mind=clamp(state.mind-1,0,state.maxMind);}},
      {t:"길드에서 출발 직전 전령이 도착했다. 소문의 일부가 틀렸다는 새로운 정보가 들어왔다.",e:()=>{ctx.danger-=5;}},
      {t:"의뢰주가 현장에서 조건 하나를 뒤늦게 덧붙였다. 처음 들었던 계약과 완전히 같지는 않았다.",e:()=>{ctx.rewardBonus+=ri(-3,5);}},
      {t:"지나가던 현지인이 길 상태를 알려줬다. 작은 정보 하나가 예상보다 큰 차이를 만들었다.",e:()=>{ctx.danger-=ri(2,8);}}
    ],
    explore:[
      {t:"아침까지 맑던 하늘이 갑자기 흐려졌다. 익숙하지 않은 지형이 한층 다르게 보이기 시작했다.",e:()=>{ctx.danger+=5;}},
      {t:"최근 사람이 지나간 흔적 하나가 우연히 눈에 들어왔다. 지도에 없던 방향이 생겼다.",e:()=>{ctx.notes.push("지도 밖 발자국을 확인함");}},
      {t:"찾고 있던 흔적 대신 전혀 다른 물건이 먼저 발견됐다. 쓸모가 있는지는 아직 알 수 없다.",e:()=>{ctx.notes.push("예상하지 못한 물건을 발견함");}},
      {t:"오래된 길 하나가 무너져 있었다. 계획했던 동선은 더 이상 사용할 수 없었다.",e:()=>{ctx.danger+=ri(-3,8);}}
    ],
    rest:[
      {t:"조용히 지나갈 것 같던 며칠 사이 몸 상태가 예상보다 빨리 좋아졌다.",e:()=>{state.hp=clamp(state.hp+ri(2,6),0,state.maxHp);}},
      {t:"별일 아닌 소음과 방문객 때문에 잠을 설쳤다. 쉬기로 한 달이라고 해서 반드시 편한 것은 아니었다.",e:()=>{state.mind=clamp(state.mind-ri(1,4),0,state.maxMind);}},
      {t:"오래 보지 못했던 사람이 우연히 찾아왔다. 짧은 대화가 생각보다 오래 남았다.",e:()=>{state.mind=clamp(state.mind+ri(1,5),0,state.maxMind);}},
      {t:"몸은 쉬었지만 검을 잡지 않는 시간이 길어지자 그는 오히려 초조해했다.",e:()=>{state.mind=clamp(state.mind-ri(1,3),0,state.maxMind);}}
    ],
    investigate:[
      {t:"증언 하나가 다음 날 갑자기 번복됐다. 어제까지 확실해 보이던 사실이 다시 흐려졌다.",e:()=>{ctx.docsCompromised=true;}},
      {t:"찾지 않았던 문서의 여백에서 이름 하나가 발견됐다. 우연한 메모가 단서의 방향을 바꿨다.",e:()=>{ctx.docsLead=true;}},
      {t:"조사 대상이 먼저 움직였다. 누군가 자신을 살피고 있다는 사실을 눈치챈 듯했다.",e:()=>{ctx.danger+=8;}},
      {t:"서로 관계없어 보였던 두 증언이 뜻밖의 지점에서 겹쳤다.",e:()=>{ctx.docsLead=true;}}
    ],
    sail:[
      {t:"오후부터 바람이 바뀌었다. 함대의 대형과 일정이 원래 계획과 달라졌다.",e:()=>{ctx.windChanged=true;}},
      {t:"다른 배의 판단 하나가 함대 전체에 영향을 줬다. 그가 통제할 수 없는 변수였다.",e:()=>{ctx.danger+=ri(-5,7);}},
      {t:"예상보다 빠른 해류를 타며 하루 일정이 단축됐다.",e:()=>{ctx.docsLead=true;}},
      {t:"멀리서 발견된 작은 돛 하나 때문에 함대가 한동안 진로를 바꿨다.",e:()=>{ctx.routeChanged=true;}}
    ]
  };

  const arr=table[state.policy]||[];
  if(!arr.length)return "";
  const x=choice(arr);
  x.e();
  return x.t;
}

function revealPendingTwist(text){
  const ctx=state.storyCtx;
  if(!ctx?.pendingTwist)return text;
  const twist=ctx.pendingTwist;
  ctx.pendingTwist="";
  return `${ownerText(twist)}\n\n${text}`;
}

function openStoryScene(kicker,title,text,choices){
  text=novelStoryText(text);
  text=revealPendingTwist(text);
  const isMain=state.policy==="sail";
  let header=`<div class="modalHead"><b>${policyNames[state.policy]} · 월간 서사</b><span style="font-size:8px;color:#776650">${state.year}년차 ${state.month}월</span></div>`;
  let progress='';
  if(isMain){
    if(typeof currentAct1ChapterV25==='function'&&(state.storyCtx?.v25DisplayChapter||currentAct1ChapterV25())){
      const v=(state.storyCtx?.v25DisplayChapter&&typeof act1ChapterByIndexV25==='function'?act1ChapterByIndexV25(state.storyCtx.v25DisplayChapter):currentAct1ChapterV25()),pct=Math.max(8,Math.min(100,v.index/8*100));
      header=`<div class="modalHead mainChapterHead"><div class="chapterName"><small>MAIN STREAM · 제1장 · CHAPTER ${v.index}/8</small><b>${v.title}</b></div><span style="font-size:8px;color:#776650">${state.year}년차 ${state.month}월</span></div>`;
      progress=`<div class="chapterRunProgress"><i style="width:${pct}%"></i></div>`;
    }else{
      const displayChapter=state.storyCtx?.chapterDisplay||state.mainStory.chapter;
      const ch=MAIN_CHAPTERS[displayChapter]||mainChapterMeta(),idx=Math.max(0,ch.nodes.indexOf(state.mainStory.node)),pct=state.storyCtx?.chapterDisplay?100:Math.max(8,Math.min(100,((idx+1)/Math.max(1,ch.nodes.length))*100));
      header=`<div class="modalHead mainChapterHead"><div class="chapterName"><small>MAIN STREAM · CHAPTER ${displayChapter}</small><b>${ch.title}</b></div><span style="font-size:8px;color:#776650">${state.year}년차 ${state.month}월</span></div>`;
      progress=`<div class="chapterRunProgress"><i style="width:${pct}%"></i></div>`;
    }
  }
  openModal(
    header+progress+storyMeta()+
    `<div class="storyScene">
      <div class="storyKicker">${ownerText(kicker)}</div>
      <div class="storyTitle">${ownerText(title)}</div>
      <div class="storyText">${text}</div>
      <div class="storyChoices" id="storyChoices"></div>
    </div>`
  );
  const box=$("storyChoices");
  choices.forEach(c=>box.appendChild(storyChoiceButton(c)));
}

function chooseStory(c){
  if(c.effect)c.effect(state.storyCtx);

  // v1.4: 선택 직후 무관한 랜덤 문장을 끼워 넣지 않는다.
  // 월간 상황과 사건 변화는 장면에 직접 작성된 인과로만 처리한다.

  if(c.combat){
    launchStoryCombat(c.combat.enemy,c.combat.label,c.combat.win,c.combat.lose,c.combat.mods||{});
    return;
  }
  if(c.next==="END"){
    finishStory(c.outcome||"이번 달의 일이 마무리됐다.");
    return;
  }
  showStoryNode(c.next);
}

function startStory(){
  if(!state.policy||!state.subChoice)return;
  const ev=state.monthEvents.find(e=>e.policy===state.policy&&e.id===state.subChoice);if(ev)ev.chosen=true;
  const forcedChanges=(ev?.main&&ev?.forced)?applyForcedMainPenalty():[];
  if(forcedChanges.length)saveGame();
  const picked=ev||{};
  state.storyCtx={
    policy:state.policy,id:state.subChoice,candidateKey:picked.candidateKey||state.subChoice,variant:picked.variant||'',difficulty:picked.difficulty||1,rewardTier:picked.rewardTier||1,
    before:{hp:state.hp,mind:state.mind,gold:state.gold,dur:state.weapon.dur,resonance:state.weapon.resonance},
    alignment:alignmentMod(),
    rewardBonus:Math.max(0,(picked.rewardTier||1)-1)*3,danger:Math.max(0,(picked.difficulty||1)-1)*5,notes:[],fragmentsGained:[],reconstructionReady:[],combatPending:null,
    condition:state.monthFacts[0]?.id||'clear',
    pendingTwist:"",forcedMainChanges:forcedChanges 
  };
  state.mind=clamp(state.mind+state.storyCtx.alignment.mind,0,state.maxMind);
  if(state.storyCtx.condition==='rain'&&state.policy==='contract')state.storyCtx.danger+=6;
  if(state.storyCtx.condition==='harbor_check'&&['contract','investigate','sail'].includes(state.policy))state.storyCtx.danger-=4;
  if(state.storyCtx.condition==='mine_closure'&&state.subChoice==='mine')state.storyCtx.danger+=5;
  state.activeStory=`${state.policy}:${state.subChoice}`;
  if(state.policy==="sail"&&chapterEntryPending())showStoryNode("chapter_intro");
  else showStoryNode("start");
}

function showStoryNode(node){
  const p=state.policy,id=state.subChoice,ctx=state.storyCtx;
  if(ctx)ctx.currentNode=node;

  if(p!=="sail"&&showAuthoredSideStory(node))return;

  /* ---------------- 의뢰 ---------------- */
  if(p==="contract"){
    if(id==="escort"){
      if(node==="start") return openStoryScene(
        "길드 · 상단 호위",
        "해가 지기 전 서쪽 고개를 넘겨라",
        `상인 카론은 마차 세 대를 가리켰다.\n\n“밤이 되기 전에 서쪽 고개만 넘기면 38G를 주지. 대신 늦으면 절반이다.”\n\n주점에서 들은 바로는 최근 서쪽 길에서 통행세를 뜯는 도적이 늘었다.`,
        [
          {label:"보수 8G를 더 받고 지름길로 간다",
           effect:c=>{c.rewardBonus+=8;c.danger+=25;c.notes.push("고액 조건을 받고 지름길 선택");},next:"road"},
          {label:"보수는 그대로, 경비초소가 있는 북쪽 길로 간다",
           effect:c=>{c.danger-=15;c.notes.push("안전한 북쪽 길 선택");},next:"road"}
        ]
      );
      if(node==="road"){
        const risky=ctx.danger>0;
        return openStoryScene(
          "서쪽 고개 · 이동 중",
          risky?"버려진 수레와 길을 막은 사람들":"경비초소 뒤편의 연기",
          risky
            ?`고개 입구에서 바퀴가 부서진 수레가 길을 가로막았다. 세 명의 남자가 도움을 청하지만, 손이 모두 칼자루 근처에 있다.\n\n그가 낮게 중얼거린다.\n“저건 사고 난 사람들 자세가 아닌데.”`
            :`북쪽 길은 조용했지만 경비초소 뒤편에서 연기가 올랐다. 초소병 하나가 피를 흘린 채 쓰러져 있다.\n\n누군가 상단이 이 길로 올 것을 미리 알고 있었던 듯하다.`,
          [
            ...(skillActive("road_reader")?[{label:"붉은 표식이 향한 옆 능선을 확인한다",next:"escort_skill_route"}]:[]),
            {label:"마차를 세우고 정면으로 확인한다",
             combat:{enemy:"bandit",label:"상단을 노린 도적",win:"escort_win",lose:"escort_lose"}},
            {label:"상단을 돌려 보내고 흔적만 추적한다",
             effect:c=>{state.gold+=12+c.rewardBonus;gainFragment("red_mark","burned_roster");c.notes.push("상단을 보존하고 도적 흔적 확보");},next:"escort_safe"}
          ]
        );
      }
      if(node==="escort_skill_route") return openStoryScene(
        "서쪽 고개 · 기억의 사용","표식은 사람보다 먼저 길을 말한다",
        `붉은 표식은 길을 막은 사람들의 허리에만 있지 않았다. 바위 세 곳에 같은 안료가 얇게 묻어 있었다. 예전 사건의 조각들이 맞물리자, 그것이 매복대가 서로 위치를 확인하는 표식임을 알아볼 수 있었다.\n\n상단이 아직 들키기 전이다.`,
        [
          {label:"상단을 숨기고 매복대 뒤로 돌아간다",combat:{enemy:"bandit",label:"뒤를 잡힌 고개 도적",win:"escort_win",lose:"escort_lose"}},
          {label:"표식이 없는 폐쇄 도로로 마차를 돌린다",effect:c=>{state.gold+=32+c.rewardBonus;c.notes.push("각인 「길목 읽기」로 매복 우회");},next:"escort_safe"}
        ]
      );
      if(node==="escort_win"){
        const reward=38+ctx.rewardBonus;
        state.gold+=reward;gainFragment("red_mark","bandit_mark");state.eventFlags.karonManifestOpen=true;
        return openStoryScene(
          "서쪽 고개를 넘다","상단은 고개를 넘었다",
          `도적들이 흩어진 뒤 카론은 약속한 돈을 건넸다.\n\n“다음에도 내 마차를 맡아줬으면 좋겠군.”\n\n보수 ${reward}G. 도적들이 허리에 달고 있던 붉은 나무 표식을 검이 기억했다.`,
          [{label:"이번 달을 마무리한다",next:"END",outcome:"상단 호위 성공"}]
        );
      }
      if(node==="escort_lose"){
        state.gold+=8;
        return openStoryScene(
          "호위가 무너진 뒤","마차 한 대를 잃었다",
          `그는 살아 돌아왔지만 상단은 짐 일부를 빼앗겼다. 카론은 치료비 명목으로 8G만 건넸다.\n\n의뢰는 실패했다. 하지만 도적의 습격 경로는 기억에 남았다.`,
          [{label:"부상을 정리하고 돌아간다",next:"END",outcome:"상단 호위 실패"}]
        );
      }
      if(node==="escort_safe"){
        return openStoryScene(
          "상단을 돌려보낸 뒤","돈보다 정보를 남겼다",
          `상단은 손해를 피했지만 계약은 끝까지 수행하지 못했다. 대신 도적들이 어느 방향에서 내려오는지 알아냈다.\n\n카론은 불만스러워했지만, “적어도 마차는 살렸군.”이라며 12G를 지급했다.`,
          [{label:"이번 달을 마무리한다",next:"END",outcome:"불탄 초소 교대표 확보"}]
        );
      }
    }

    if(id==="hunt"){
      if(node==="start") return openStoryScene(
        "길드 · 괴물 토벌","광산 입구에 남은 거미줄",
        `북부 광산에서 광부 둘이 실종됐다. 입구에는 사람 팔만 한 굵기의 거미줄이 남아 있다.\n\n광산주는 55G와 발견한 갑각을 보수로 걸었다.`,
        [
          {label:"불을 피워 거미를 바깥으로 유도한다",
           effect:c=>{c.danger-=15;c.notes.push("연기로 거미 유도");},next:"hunt_lure"},
          {label:"실종자를 찾기 위해 안쪽까지 들어간다",
           effect:c=>{c.notes.push("실종자 수색 우선");},next:"hunt_deep"}
        ]
      );
      if(node==="hunt_lure") return openStoryScene(
        "북부 광산 · 입구","연기에 밀려 나온 거미",
        `바위틈이 흔들리더니 동굴 거미가 모습을 드러냈다. 광부들이 뒤로 물러난다.\n\n이제 싸움을 피하면 거미는 다시 광산으로 들어간다.`,
        [
          {label:"여기서 끝낸다",
           combat:{enemy:"spider",label:"북부 광산 동굴 거미",win:"hunt_win",lose:"hunt_lose"}},
          {label:"광산 입구를 무너뜨려 봉쇄한다",
           effect:c=>{state.gold+=24;c.notes.push("광산 봉쇄");},next:"hunt_block"}
        ]
      );
      if(node==="hunt_deep") return openStoryScene(
        "북부 광산 · 안쪽 갱도","살아 있는 광부",
        `안쪽 갱도에서 실종된 광부 한 명을 발견했다. 하지만 그 위 천장에 거대한 그림자가 붙어 있다.\n\n광부를 들쳐 업는 순간 거미가 내려온다.`,
        [
          ...(hasPartTag("spider")?[{label:"갑각 가드를 거미줄에 대어 진동 방향을 읽는다",effect:c=>{gainFragment("spider_mine","shell_joint");markConnection("거미 갑각 가드 → 둥지 진동","거미 갑각 가드가 광산의 거미줄 진동을 읽어 숨은 해결법을 만들었다.");c.danger-=10;c.notes.push("거미 갑각 가드가 둥지 진동을 읽음");},next:"hunt_spider_link",connection:true}]:[]),
          {label:"광부를 뒤로 보내고 거미를 막는다",
           effect:c=>{c.rewardBonus+=8;},combat:{enemy:"spider",label:"갱도 동굴 거미",win:"hunt_win",lose:"hunt_lose"}},
          {label:"횃불을 던지고 광부와 도망친다",
           effect:c=>{state.gold+=28;gainFragment("spider_mine","torn_pack");c.notes.push("광부 구조");},next:"hunt_rescue"}
        ]
      );
      if(node==="hunt_spider_link") return openStoryScene(
        "광산 깊은 곳 · 검이 기억한 진동","가드는 장식이 아니었다",
        `거미 갑각 가드가 거미줄에 닿자 손잡이로 미세한 떨림이 올라왔다. 같은 갑각끼리 전달되는 진동 덕분에 천장에 붙은 거미가 움직이기 전에 방향을 읽을 수 있었다. 광부가 먼저 빠져나갈 틈이 생겼다.`,
        [
          {label:"진동이 멎는 순간 거미에게 들어간다",combat:{enemy:"spider",label:"진동을 읽힌 동굴 거미",win:"hunt_win",lose:"hunt_lose"}},
          {label:"광부를 데리고 그대로 빠져나간다",effect:c=>{state.gold+=32;gainFragment("spider_mine","torn_pack");},next:"hunt_rescue"}
        ]
      );
      if(node==="hunt_win"){
        state.gold+=55+ctx.rewardBonus;state.weapon.materials.shell++;gainFragment("spider_mine","shell_joint");
        let guardReward="";if(!equippedPartIds().includes("spider_guard")&&!spareCount("spider_guard")){addSpare("spider_guard",1);guardReward=" 대장장이가 온전한 갑각 한 장을 골라 즉석에서 거미 갑각 가드로 맞춰 주었다.";}
        return openStoryScene(
          "거미가 쓰러진 자리","거미 갑각을 떼어냈다",
          `거미가 쓰러졌다. 광산주는 약속한 보수를 지급했고, 단단한 갑각을 챙겼다.${guardReward}`,
          [{label:"갑각을 챙기고 귀환한다",next:"END",outcome:"괴물 토벌 성공"}]
        );
      }
      if(node==="hunt_lose"){
        return openStoryScene(
          "현장에서 물러나다","광산을 포기했다",
          `거미를 잡지 못했다. 광산은 당분간 폐쇄된다. 그는 살아 돌아왔지만 토벌 보수는 없다.`,
          [{label:"치료부터 한다",next:"END",outcome:"괴물 토벌 실패"}]
        );
      }
      if(node==="hunt_block"||node==="hunt_rescue"){
        return openStoryScene(
          "토벌하지 않은 해결","괴물을 잡지 않고 사람을 살렸다",
          `의뢰서의 ‘토벌’ 조건은 채우지 못했지만 피해는 줄였다. 길드에서는 완전한 성공으로 기록하지 않는다.`,
          [{label:"이번 달을 마무리한다",next:"END",outcome:"토벌 대신 피해 억제"}]
        );
      }
    }

    if(id==="guard"){
      if(node==="start") return openStoryScene(
        "길드 · 창고 경비","너무 조용한 야간 경비",
        `항구 창고 하나가 사흘 연속 털렸다. 싸구려 곡물은 그대로인데 값비싼 향신료 상자만 사라졌다.\n\n이번 밤에는 그가 창고 안에서 기다린다.`,
        [
          {label:"불을 모두 끄고 안에서 매복한다",next:"guard_ambush"},
          {label:"밖에서 운반 경로를 추적한다",next:"guard_track"}
        ]
      );
      if(node==="guard_ambush") return openStoryScene(
        "창고 · 자정","문고리가 아주 천천히 움직였다",
        `두 사람이 창고로 들어와 정확히 향신료 상자만 집는다. 뒤이어 칼을 든 세 번째 사람이 그를 발견한다.`,
        [
          {label:"문을 막고 체포한다",
           combat:{enemy:"bandit",label:"항구 창고 도둑",win:"guard_win",lose:"guard_lose"}},
          {label:"일부러 놓아주고 뒤를 밟는다",
           effect:c=>{state.gold+=18;gainFragment("black_sail","empty_warehouse");},next:"guard_track_end"}
        ]
      );
      if(node==="guard_track") return openStoryScene(
        "항구 · 부두 뒤편","도둑은 물건을 직접 팔지 않았다",
        `상자는 부두 뒤편의 검은 천막으로 옮겨졌다. 안에는 항구 세관의 인장이 찍힌 장부가 있다.`,
        [
          {label:"장부를 훔쳐 길드에 넘긴다",
           effect:c=>{state.gold+=20;gainFragment("black_sail","empty_warehouse");},next:"guard_track_end"},
          {label:"현장에서 사람까지 잡는다",
           combat:{enemy:"bandit",label:"밀수 조직 경비",win:"guard_win",lose:"guard_lose"}}
        ]
      );
      if(node==="guard_win"){
        state.gold+=28;gainFragment("black_sail","black_tar");
        return openStoryScene("창고 사건 · 해결","도둑과 장부를 함께 넘겼다",
          `길드는 경비 보수에 체포 보너스를 얹었다. 창고 절도는 단순 도둑질이 아니었다.`,
          [{label:"길드에 보고한다",next:"END",outcome:"창고 절도 사건 해결"}]);
      }
      if(node==="guard_lose"){
        state.gold+=6;
        return openStoryScene("창고 사건 · 놓친 밤","도둑은 달아났다",
          `향신료 상자 일부가 사라졌다. 길드는 최소한의 야간 수당만 지급했다.`,
          [{label:"돌아간다",next:"END",outcome:"창고 경비 실패"}]);
      }
      if(node==="guard_track_end"){
        return openStoryScene("배후의 흔적","칼을 뽑지 않고 더 큰 흔적을 얻었다",
          `이번 달 수입은 적지만, 세관 7번 창고가 반복해서 비워진 기록과 운반 경로를 손에 넣었다.`,
          [{label:"기록을 보관한다",next:"END",outcome:"세관 7번 창고 기록 확보"}]);
      }
    }
  }

  /* ---------------- 탐험 ---------------- */
  if(p==="explore"){
    if(node==="start"){
      const meta={
        ruins:["해안 폐허","물이 빠진 계단 아래","정오가 지나자 절벽 아래 돌계단이 바다에서 모습을 드러냈다. 가장 아래 계단에는 아직 젖은 청동 가루가 붙어 있었다."],
        mine:["북부 광산","지도에 없는 두 번째 갱도","무너진 벽 뒤에서 오래된 광차 레일이 이어졌다. 새 갱도라기보다 오래전에 일부러 막아둔 길처럼 보였다."],
        grove:["올리브 숲","붉은 천이 묶인 길","숲 안쪽으로 갈수록 붉은 천이 일정한 간격으로 묶여 있었다. 사냥꾼의 표식치고는 너무 규칙적이었다."]
      }[id];
      const choices=id==="ruins"?[
        {label:"물이 다시 차기 전에 아래 작업실부터 확인한다",effect:c=>{c.danger+=18;},next:"explore_deep"},
        {label:"계단과 벽면의 제작 표식부터 베껴둔다",effect:c=>{c.danger-=8;},next:"explore_outer"}
      ]:id==="mine"?[
        {label:"낡은 광차 레일을 따라 막힌 안쪽으로 들어간다",effect:c=>{c.danger+=18;},next:"explore_deep"},
        {label:"입구의 발자국과 운반 흔적부터 확인한다",effect:c=>{c.danger-=8;},next:"explore_outer"}
      ]:[
        {label:"붉은 천이 이어지는 제단 쪽으로 곧장 간다",effect:c=>{c.danger+=18;},next:"explore_deep"},
        {label:"천을 건드리지 않고 주변 발자국부터 돈다",effect:c=>{c.danger-=8;},next:"explore_outer"}
      ];
      if(id==="ruins"&&(hasPartTag("tide")||hasPartTag("waterproof")))choices.unshift({label:"검의 외장에 맺히는 염분 흔적을 돌계단의 자국과 비교한다",effect:c=>{gainFragment("sunken_forge","salt_scale");markConnection("조수 대응 파츠 → 해안 폐허","방수/조수 계열 파츠가 해안 폐허의 염분 흔적을 읽는 도구가 됐다.");c.danger-=8;},next:"explore_tide_link",connection:true});
      return openStoryScene("탐험 · "+meta[0],meta[1],meta[2],choices);
    }
    if(node==="explore_tide_link")return openStoryScene(
      "해안 폐허 · 조수선 아래","검의 외장이 먼저 알아본 자리",
      `가드와 검집에 맺힌 염분 자국이 계단 한쪽 벽의 하얀 비늘과 같은 방향으로 굳어 있었다. 파도가 닿는 높이를 따라가자 무너진 벽 뒤에 작은 작업 공간이 드러났다. 우연히 얻은 파츠의 성질이 폐허의 구조를 읽는 도구가 됐다.`,
      [
        {label:"작업 공간의 표식을 더 확인한다",effect:c=>{gainFragment("sunken_forge","maker_mark");},next:"explore_deep"},
        {label:"위치만 기억하고 바깥으로 돌아간다",next:"explore_outer"}
      ]
    );
    if(node==="explore_deep"){
      const enemy=id==="mine"?"spider":id==="ruins"?"slime":"bandit";
      const label=id==="mine"?"갱도 동굴 거미":id==="ruins"?"폐허의 검은 점액":"제단을 노리는 약탈자";
      const why=id==="mine"
        ?"갱도 끝에 광부의 장비가 거미줄째 매달려 있다. 뒤편에서 다리가 여덟 개 달린 그림자가 움직인다."
        :id==="ruins"
          ?"제단 아래의 봉인을 건드리자 검은 점액이 홈을 따라 흘러나와 길을 막는다."
          :"붉은 천은 제사의 흔적이 아니라 약탈자들의 영역 표시였다. 셋이 돌기둥 뒤에서 나온다.";
      return openStoryScene(
        "탐험지 · 중심부",label,
        why+"\n\n돌아갈 수는 있지만, 중심부의 물건과 기록은 포기해야 한다.",
        [
          {label:"검을 뽑고 길을 연다",
           combat:{enemy,label,win:"explore_win",lose:"explore_lose"}},
          {label:"표식과 지형만 기록하고 철수한다",
           effect:c=>{if(id==="ruins")gainFragment("sunken_forge","salt_scale");if(id==="mine")gainFragment("spider_mine","egg_map");},next:"explore_retreat"}
        ]
      );
    }
    if(node==="explore_outer"){
      if(id==="ruins")return openStoryScene("해안 폐허 · 벽면","물보다 먼저 지워지는 것",`벽면의 제작 표식을 베끼는 동안 파도가 한 계단씩 올라왔다. 표식 아래에는 최근 누군가 쇠도구로 긁어낸 흔적도 있었다. 오래된 폐허를 찾는 사람이 ${state.owner.name}만은 아니었다.`,[
        {label:"긁힌 자국을 따라 작업실 쪽으로 내려간다",combat:{enemy:"bandit",label:"폐허를 뒤지는 약탈자",win:"explore_win",lose:"explore_lose"}},
        {label:"염분 비늘과 표식만 확보하고 물이 차기 전에 나온다",effect:c=>{state.weapon.materials.iron+=1;gainFragment("sunken_forge","salt_scale");},next:"explore_retreat"}
      ]);
      if(id==="mine")return openStoryScene("북부 광산 · 입구","광차가 지나간 지 오래되지 않았다",`폐광이라고 들었지만 레일 위 먼지에는 바퀴가 지나간 두 줄이 선명했다. 옆에는 사람 발자국과 거미 다리가 끌린 자국이 뒤섞여 있었다. 안쪽에서 금속이 한 번 부딪혔다.`,[
        {label:"광차 흔적이 끝나는 곳까지 따라간다",combat:{enemy:"spider",label:"미등록 갱도의 동굴 거미",win:"explore_win",lose:"explore_lose"}},
        {label:"알집 위치와 레일 방향만 지도에 옮기고 나온다",effect:c=>{state.weapon.materials.iron+=1;gainFragment("spider_mine","egg_map");},next:"explore_retreat"}
      ]);
      return openStoryScene("올리브 숲 · 바깥 고리","천을 묶은 사람의 발자국",`붉은 천 아래마다 같은 장화 자국이 있었다. 제사를 지낸 사람이라기보다 여러 번 오가며 경계를 표시한 사람의 걸음이었다. 숲 반대편에서는 낮은 목소리가 들렸다.`,[
        {label:"목소리가 들리는 쪽을 돌아서 확인한다",combat:{enemy:"bandit",label:"숲을 점거한 약탈자",win:"explore_win",lose:"explore_lose"}},
        {label:"충돌하지 않고 약초와 물만 챙겨 돌아온다",effect:c=>{state.hp=clamp(state.hp+6,0,state.maxHp);state.mind=clamp(state.mind+3,0,state.maxMind);},next:"explore_retreat"}
      ]);
    }
    if(node==="explore_win"){
      if(id==="mine"){state.weapon.materials.iron+=2;gainFragment("spider_mine","egg_map");return openStoryScene("북부 광산 · 거미가 물러난 자리","막힌 갱도 뒤의 지도",`거미줄 아래에서 오래된 갱도 표식과 알집 위치가 함께 드러났다. 광차 레일은 더 깊은 곳에서 끊겨 있었고, 끊긴 지점 너머에는 누군가 판자를 새로 댄 흔적이 있었다. 철광석보다 그 지도가 다음 방문의 이유가 됐다.`,[{label:"알집 지도를 접어 검집 안에 넣는다",next:"END",outcome:"미등록 갱도 탐험 성공"}]);}
      if(id==="ruins"){state.weapon.materials.iron+=1;gainFragment("sunken_forge","maker_mark");gainFragment("sunken_forge","temper_tablet");return openStoryScene("해안 폐허 · 잠긴 작업실","깨진 담금질 판",`검은 점액이 사라진 자리 아래에서 얇은 청동판 하나가 나왔다. 불의 세기와 물에 담그는 순서가 긁혀 있었고, 모서리에는 같은 제작자 표식이 남아 있었다. 파도가 차오르기 전에 가져갈 수 있는 것은 그것뿐이었다.`,[{label:"판과 표식을 챙겨 물이 차기 전에 나온다",next:"END",outcome:"침몰 작업실 탐험 성공"}]);}
      state.weapon.materials.shell+=1;return openStoryScene("올리브 숲 · 제단 뒤","약탈자가 찾던 금속 조각",`약탈자들이 파헤친 흙 아래에는 제물보다 오래된 금속 장식과 단단한 갑각 조각이 섞여 있었다. 붉은 천은 신성한 표식이 아니라 그들이 서로 영역을 확인하는 표시였다.`,[{label:"쓸 수 있는 조각만 챙기고 제단은 그대로 둔다",next:"END",outcome:"올리브 숲 탐험 성공"}]);
    }
    if(node==="explore_lose"){
      return openStoryScene(
        "강제 철수","탐험보다 생존이 먼저였다",
        `그는 더 깊이 들어가지 못하고 후퇴했다. 지형과 적의 흔적은 남았지만 보상은 거의 챙기지 못했다.`,
        [{label:"다음 기회를 노린다",next:"END",outcome:"탐험 실패"}]
      );
    }
    if(node==="explore_retreat"){
      state.weapon.dur=clamp(state.weapon.dur-2,0,100);
      if(id==="ruins")gainFragment("sunken_forge","salt_scale");
      if(id==="mine")gainFragment("spider_mine","egg_map");
      return openStoryScene(
        "탐험에서 돌아오다","위험을 피한 탐험",
        `큰 발견은 없었지만 지형과 흔적을 충분히 기록했다. 다음 조사나 탐험에서 쓸 수 있는 자료가 남았다.`,
        [{label:"기록을 정리한다",next:"END",outcome:"탐험 종료"}]
      );
    }
  }

  /* ---------------- 휴식 ---------------- */
  if(p==="rest"){
    if(node==="start"){
      if(id==="inn")return openStoryScene(
        "휴식 · 도시 여관","닫힌 문과 열린 식당",
        `여관주인은 가장 안쪽 방 열쇠를 건넸다. 창문을 열면 항구 냄새가 들어왔고, 문을 닫으면 복도의 소리도 거의 들리지 않았다. ${state.owner.name}은 검을 침대 옆에 기대 세우고 한참 동안 아무 일정도 정하지 않았다.\n\n이번 달에는 정말 쉬어도 된다. 쉬는 방식만 고르면 된다.`,
        [
          {label:"며칠은 식사 시간에도 내려가지 않고 잔다",effect:c=>{state.hp=clamp(state.hp+24,0,state.maxHp);c.notes.push("여관에서 수면과 식사에 집중");},next:"rest_inn_silence"},
          {label:"저녁에는 공용 식탁에 내려가 사람들 틈에 앉는다",effect:c=>{state.mind=clamp(state.mind+14,0,state.maxMind);c.notes.push("여관 사람들과 어울림");},next:"rest_inn_table"}
        ]
      );
      if(id==="quiet")return openStoryScene(
        "휴식 · 외곽의 집","아무도 찾아오지 않는 곳",
        `도시 성벽에서 반나절 떨어진 작은 집에는 침대 하나와 화덕, 뒤뜰의 우물뿐이었다. 밤이 되면 항구 소리도 들리지 않았다.\n\n${state.owner.name}은 첫날 검을 벽에 걸고 손가락을 몇 번 폈다 쥐었다. 싸우지 않는 시간이 어색한 사람의 손이었다.`,
        [
          {label:"검을 건드리지 않고 몸을 완전히 쉰다",effect:c=>{state.hp=clamp(state.hp+22,0,state.maxHp);c.notes.push("완전 휴식");},next:"rest_quiet_body"},
          {label:"아침마다 짧게 걷고 몸 상태를 확인한다",effect:c=>{state.hp=clamp(state.hp+12,0,state.maxHp);state.mind=clamp(state.mind+8,0,state.maxMind);c.notes.push("가벼운 회복 루틴");},next:"rest_quiet_walk"}
        ]
      );
      return openStoryScene(
        "휴식 · 미라의 집","말을 미뤄둔 식탁",
        `미라는 문을 열어주고도 한동안 아무 말이 없었다. 식탁에는 두 사람 몫의 빵과 수프가 놓여 있었다. 예전에 금이 간 술잔도 아직 선반 한쪽에 그대로였다.\n\n${state.owner.name}도 검부터 내려놓았다. 이번에는 싸움보다 대화가 어려워 보였다.`,
        [
          {label:"지난번 다툼 이야기를 먼저 꺼낸다",effect:c=>{state.mind=clamp(state.mind+10,0,state.maxMind);gainFragment("mira_home","old_cup");c.notes.push("미라와 미뤄둔 대화를 시작");},next:"rest_mira_talk"},
          {label:"일 이야기는 하지 않고 같이 밥부터 먹는다",effect:c=>{state.hp=clamp(state.hp+10,0,state.maxHp);state.mind=clamp(state.mind+8,0,state.maxMind);c.notes.push("미라와 평범한 저녁");},next:"rest_mira_meal"}
        ]
      );
    }

    if(node==="rest_inn_silence")return openStoryScene(
      "여관 · 닷새째 아침","잠이 먼저 돌아왔다",
      `닷새째가 되자 ${state.owner.name}은 알람처럼 해 뜨기 전에 깨지 않았다. 통증도 처음보다 줄었다. 방문 앞에는 여관주인이 놓고 간 따뜻한 물과 빵이 식어 있었다.\n\n복도 끝에서는 늙은 선원 둘이 옛 전쟁 이야기를 하고 있었다. 검집의 모양을 본 한 사람이 이쪽을 두 번 흘겨봤다.`,
      [
        {label:"그 시선을 모른 척하고 다시 방으로 들어간다",effect:c=>{state.hp=clamp(state.hp+12,0,state.maxHp);},next:"rest_plain_end"},
        {label:"노인 옆에 앉아 왜 검을 봤는지 묻는다",effect:c=>{state.mind=clamp(state.mind+6,0,state.maxMind);addWorldFact("여관의 늙은 선원이 검집의 오래된 군용 형식을 알아봤다.",`inn_veteran:${state.year}:${state.month}`);recordDeed("social",`${state.year}-${state.month}:inn_veteran`);},next:"rest_plain_end"}
      ]
    );
    if(node==="rest_inn_table")return openStoryScene(
      "여관 · 공용 식탁","모르는 사람들 사이에서 쉬는 법",
      `식탁에는 광부, 짐꾼, 떠돌이 상인이 뒤섞여 있었다. 아무도 ${state.owner.name}에게 일을 부탁하지 않았다. 그 사실만으로도 대화는 평소보다 가벼웠다.\n\n한 상인이 주사위를 굴리며 길 이야기만 듣고 가도 술값은 자기가 내겠다고 했다.`,
      [
        {label:"주사위판에는 끼지 않고 길 이야기만 듣는다",effect:c=>{state.mind=clamp(state.mind+8,0,state.maxMind);addWorldFact("서쪽 고개보다 북쪽 초소 길을 쓰는 상단이 늘고 있다는 말을 들었다.",`inn_road:${state.year}:${state.month}`);},next:"rest_plain_end"},
        {label:"아무 이야기에도 끼지 않고 식사만 하고 올라간다",effect:c=>{state.hp=clamp(state.hp+8,0,state.maxHp);state.mind=clamp(state.mind+4,0,state.maxMind);},next:"rest_plain_end"}
      ]
    );
    if(node==="rest_quiet_body")return openStoryScene(
      "외곽의 집 · 비 오는 날","아무 일도 일어나지 않았다",
      `사흘 동안 비가 내렸다. 지붕 끝에서 떨어지는 물소리 말고는 들리는 것이 없었다. ${state.owner.name}은 낮잠을 자고, 먹고, 다시 잤다.\n\n전투도 사건도 없었다. 대신 몸이 얼마나 지쳐 있었는지가 뒤늦게 드러났다.`,
      [
        {label:"비가 그칠 때까지 더 쉰다",effect:c=>{state.hp=clamp(state.hp+16,0,state.maxHp);state.mind=clamp(state.mind+5,0,state.maxMind);},next:"rest_plain_end"},
        {label:"마지막 날에는 검 없이 마을까지 걸어본다",effect:c=>{state.hp=clamp(state.hp+7,0,state.maxHp);state.mind=clamp(state.mind+9,0,state.maxMind);},next:"rest_plain_end"}
      ]
    );
    if(node==="rest_quiet_walk")return openStoryScene(
      "외곽의 집 · 짧은 산책","검 없이 걷는 거리",
      `처음 며칠은 손이 자꾸 허리로 갔다. 검이 없다는 사실을 확인한 뒤에야 걸음이 느려졌다. 길가에는 올리브나무와 작은 묘지가 있었고, 지나가는 사람 누구도 ${state.owner.name}을 모험가로 보지 않았다.\n\n돌아오는 길에는 숨이 덜 찼다.`,
      [
        {label:"이 속도로 남은 날도 보낸다",effect:c=>{state.hp=clamp(state.hp+10,0,state.maxHp);state.mind=clamp(state.mind+8,0,state.maxMind);},next:"rest_plain_end"},
        {label:"몸이 괜찮은 날만 짧게 검을 잡아본다",effect:c=>{state.mind=clamp(state.mind+4,0,state.maxMind);state.weapon.dur=clamp(state.weapon.dur-1,0,state.weapon.maxDur);recordDeed("martial",`${state.year}-${state.month}:quiet_form`);},next:"rest_plain_end"}
      ]
    );
    if(node==="rest_mira_talk")return openStoryScene(
      "미라의 집 · 늦은 밤","말하지 않았던 이유",
      `말은 한 번 시작되자 오래 걸렸다. 미라는 화가 난 이유보다 ${state.owner.name}이 다친 뒤에도 아무 일 없다는 듯 떠난 것이 더 싫었다고 했다.\n\n잠들기 전, 두 사람은 한동안 창가에 서 있었다. 골목 끝에서 순찰등이 움직였지만 이번에는 누구도 검을 뽑지 않았다.`,
      [
        {label:"미라가 말을 끝낼 때까지 변명하지 않는다",effect:c=>{state.mind=clamp(state.mind+12,0,state.maxMind);gainFragment("mira_home","night_watch");},next:"rest_mira_end"},
        {label:"다음에는 먼저 말하겠다고 약속한다",effect:c=>{state.mind=clamp(state.mind+8,0,state.maxMind);gainFragment("mira_home","promise");},next:"rest_mira_end"}
      ]
    );
    if(node==="rest_mira_meal")return openStoryScene(
      "미라의 집 · 평범한 며칠","대답을 요구하지 않는 시간",
      `미라는 더 묻지 않았다. 둘은 시장에 다녀오고, 낡은 의자를 고치고, 저녁마다 같은 식탁에 앉았다. 며칠이 지나자 다툼을 해결하지 않았다는 사실보다 서로 말을 피하지 않는다는 사실이 더 중요해졌다.`,
      [
        {label:"떠나기 전 지난번 일을 짧게 사과한다",effect:c=>{state.mind=clamp(state.mind+10,0,state.maxMind);gainFragment("mira_home","promise");},next:"rest_mira_end"},
        {label:"이번에는 굳이 결론을 내리지 않는다",effect:c=>{state.hp=clamp(state.hp+8,0,state.maxHp);state.mind=clamp(state.mind+6,0,state.maxMind);},next:"rest_mira_end"}
      ]
    );
    if(node==="rest_mira_end")return openStoryScene(
      "미라의 집 · 떠나는 아침","문은 닫히지 않았다",
      `짐을 챙긴 ${state.owner.name}이 문 앞에 섰을 때 미라는 배웅 대신 빈 그릇을 치웠다.\n\n“다음에 올 거면 노크는 해.”\n\n대단한 화해 선언은 없었다. 그래도 돌아올 수 있는 장소 하나가 남았다.`,
      [{label:"검을 차고 집을 나선다",next:"END",outcome:"미라의 집에서 휴식"}]
    );
    if(node==="rest_plain_end")return openStoryScene(
      "휴식의 끝","다시 움직일 몸",
      `한 달 동안 세상을 바꾸는 일은 거의 하지 않았다. 대신 ${state.owner.name}의 걸음과 호흡이 처음보다 가벼워졌다. 검도 이번만큼은 대부분 벽이나 침대 곁에 머물렀다.`,
      [{label:"다음 달 일정을 생각한다",next:"END",outcome:"충분히 쉬었다"}]
    );

    // 이전 버전의 저장 도중 노드가 남아 있어도 막히지 않게 흡수한다.
    if(["rest_event","rest_safe","rest_win","rest_lose"].includes(node))return showStoryNode("rest_plain_end");
  }

  /* ---------------- 조사 ---------------- */
  if(p==="investigate"){
    const storyId={merc:"sixth_merc",black_sail:"black_sail",priest:"nameless_priest"}[id];
    const info={
      merc:{title:"사라진 여섯 번째 용병",lead:"같은 용병단에서 다섯 명만 돌아왔는데, 출발 기록에는 여섯 명이 있었다.",testimony:"tavern_testimony",docs:"departure_ledger",site:"hidden_contract"},
      black_sail:{title:"검은 돛",lead:"새벽마다 입항 기록에 없는 배가 외항에 나타났다 사라진다.",testimony:"empty_warehouse",docs:"smuggling_manifest",site:"black_tar"},
      priest:{title:"이름 없는 사제",lead:"신전 장부에서 이름이 긁혀 나간 사제가 매달 같은 날 지하 납골당에 내려갔다.",testimony:"erased_name",docs:"prayer_strip",site:"catacomb_groove"}
    }[id];

    if(node==="start"){
      return openStoryScene(
        `조사 · ${info.title} ${storyProgressText(storyId)}`,info.title,info.lead,
        [
          {label:"사람들의 말을 하나씩 맞춰본다",next:"investigate_testimony"},
          {label:"기록에 나온 장소부터 확인한다",next:"investigate_site"}
        ]
      );
    }

    if(node==="investigate_testimony"){
      const text=id==="merc"
        ?`생존자 둘은 여섯 번째 사람은 처음부터 없었다고 말했다. 그런데 주점 주인은 출발 전날 그들이 놓고 간 술잔을 여섯 개 닦았다고 기억했다. 이름은 몰랐지만 한 사람만 왼손으로 잔을 들었다는 것까지 기억했다.`
        :id==="black_sail"
          ?`어부들은 검은 돛을 봤다고 했고 항만 관리인은 그런 배는 없었다고 잘라 말했다. 세관 짐꾼 하나는 그날마다 7번 창고가 비워지는 것을 봤다고 했다. 입출고 장부에는 이유가 적혀 있지 않았다.`
          :`늙은 수녀는 이름이 지워진 사제를 기억했다. 그가 마지막으로 내려간 날, 장부에서 자신의 이름을 직접 긁어내 달라고 부탁했다고 했다. 이유는 말하지 않았지만 손에는 피가 묻어 있었다.`;
      return openStoryScene(
        "증언 대조", "말이 맞지 않는 지점", text,
        [
          {label:"이 증언을 기록하고 문서와 대조한다",effect:c=>{gainFragment(storyId,info.testimony);},next:"investigate_docs"},
          {label:"이 증언을 들고 현장으로 간다",effect:c=>{gainFragment(storyId,info.testimony);},next:"investigate_site"}
        ]
      );
    }

    if(node==="investigate_docs"){
      if(!ctx.docsResolved){
        ctx.docsResolved=true;
        ctx.docsSuccess=ri(1,100)<=clamp(48+effectiveOwnerStats().social*2+ctx.alignment.success+(ctx.docsLead?18:0)-(ctx.docsCompromised?20:0)+(ctx.condition==='harbor_check'&&id==='black_sail'?8:0),18,90);if(ctx.docsSuccess)recordDeed('social',`${state.year}-${state.month}:records:${id}`);
        if(ctx.docsSuccess) gainFragment(storyId,info.docs);
        else state.mind=clamp(state.mind-3,0,state.maxMind);
      }
      if(ctx.docsSuccess){
        const found=id==="merc"
          ?`길드 창고 맨 아래에서 출발 장부 원본을 찾았다. 지워진 줄 아래에는 여섯 명의 숙박비와 식량 지급량이 그대로 남아 있었다. 다섯 명이 출발했다면 맞지 않는 숫자였다.`
          :id==="black_sail"
            ?`서류철 두 권의 날짜를 겹쳐 보자 같은 밤마다 사라지는 화물 번호가 나타났다. 별도 장부에는 목적지가 적혀 있지 않았지만 검은 밀랍으로 찍힌 동일한 인장이 반복됐다.`
            :`오래된 기도문 뒷면에 잘린 문장이 남아 있었다. “목소리가 이름을 부르면 대답하지 말 것.” 장부에서 지워진 사제의 필체와 같았다.`;
        return openStoryScene(
          "기록 보관소", "남아 있던 기록", found,
          [{label:"원본의 위치와 내용을 검에 기억시킨다",next:"investigate_docs_end"}]
        );
      }
      return openStoryScene(
        "기록 보관소", "비어 있는 자리", `관련 날짜의 기록은 여러 번 덧칠되어 있었다. 종이를 빛에 비춰도 원래 글씨를 읽기 어려웠다. 누군가 흔적을 없애려 한 것은 분명하지만 이번에는 가져갈 수 있는 증거가 없었다.`,
        [{label:"억지로 결론 내리지 않고 접어둔다",next:"investigate_docs_end"}]
      );
    }

    if(node==="investigate_docs_end"){
      return openStoryScene(
        "조사 기록 정리",ctx.docsSuccess?"한 조각이 맞았다":"아직 비어 있는 부분",
        ctx.docsSuccess
          ?`이번 달에 확보한 물건은 추측이 아니라 실제 기록이다. 다른 조각과 맞물리기 전까지는 결론을 내리지 않기로 했다.`
          :`아무것도 얻지 못한 것은 아니다. 누군가 특정 날짜의 기록을 지웠다는 사실은 남았다. 다만 Legend Core에 하나의 증거로 남길 만큼 확실한 물건은 아직 없다.`,
        [{label:"이번 조사를 끝낸다",next:"END",outcome:ctx.docsSuccess?`${info.title} 기록 확보`:`${info.title} 기록 추적 실패`}]
      );
    }

    if(node==="investigate_site"){
      const enemy=id==="priest"?"slime":"bandit";
      const label=id==="priest"?"납골당의 검은 점액":id==="black_sail"?"검은 돛 조직의 경비":"용병단의 입막음꾼";
      const text=id==="priest"
        ?`납골당 바닥의 홈을 따라 검은 액체가 움직였다. 홈의 끝에는 사제의 목걸이와 깨진 기록판이 놓여 있었다. 액체는 그 앞을 가로막듯 한 덩어리로 부풀었다.`
        :id==="black_sail"
          ?`7번 창고 안쪽 상자에는 검은 타르가 묻어 있었다. 그가 손가락으로 표면을 긁는 순간 출구 쪽에서 두 사람이 칼을 뽑았다.`
          :`실종자의 이름 일부가 남은 계약서가 낡은 숙소 창고에 끼워져 있었다. 그가 종이를 빼내는 순간 바깥에서 빗장이 걸렸다.`;
      return openStoryScene(
        "현장 확인",label,text,
        [
          ...(id==="priest"&&hasPartTag("ritual_thread")?[{label:"은사 래핑을 바닥 홈에 가까이 대어 공명 흐름을 확인한다",effect:c=>{gainFragment("nameless_priest","catacomb_groove");gainFragment("nameless_priest","prayer_strip");markConnection("은사 래핑 → 사제 의식 홈","은사 래핑이 납골당 의식 홈과 공명해 증거를 직접 드러냈다.");c.notes.push("은사 래핑이 의식 홈과 반응");},next:"investigate_partial",connection:true}]:[]),
          {label:"증거를 가지고 나가기 위해 길을 뚫는다",combat:{enemy,label,win:"investigate_win",lose:"investigate_lose"}},
          {label:"지금 본 것만 기억하고 물러난다",effect:c=>{if(id!=="merc")gainFragment(storyId,info.site);},next:"investigate_partial"}
        ]
      );
    }

    if(node==="investigate_win"){
      gainFragment(storyId,info.site);
      
      return openStoryScene(
        "증거 확보", "손에 남은 증거",
        id==="merc"
          ?`싸움이 끝난 뒤 그는 찢긴 계약서를 챙겼다. 여섯 번째 서명란은 반쯤 뜯겨 있었지만 지급액과 서명 흔적은 남아 있었다.`
          :id==="black_sail"
            ?`그는 경비의 칼집과 상자 모서리에서 같은 검은 타르를 긁어냈다. 단순한 소문이 아니라 실제 배와 창고를 잇는 물질이었다.`
            :`검은 점액이 흩어지자 바닥의 봉인 홈 전체가 드러났다. 홈의 배열은 사제가 매달 내려온 이유와 직접 이어져 있었다.`,
        [{label:"확보한 증거를 Legend Core에 남긴다",next:"END",outcome:`${info.title} 현장 증거 확보`}]
      );
    }

    if(node==="investigate_lose"){
      state.mind=clamp(state.mind-5,0,state.maxMind);
      return openStoryScene(
        "증거를 두고 나온 밤", "증거까지 가져오지는 못했다",
        `그는 살아 빠져나왔지만 손에 넣으려던 물건은 현장에 남았다. 다음에 다시 간다면 상대도 같은 모습으로 기다리지는 않을 것이다.`,
        [{label:"상처를 추스른다",next:"END",outcome:`${info.title} 현장 조사 실패`}]
      );
    }

    if(node==="investigate_partial"){
      return openStoryScene(
        "현장에서 물러나다", "본 것과 가진 것은 다르다",
        id==="merc"
          ?`문서가 있다는 사실과 위치는 확인했지만 계약서를 손에 넣지는 못했다. 기억만으로는 아직 하나의 조각을 완성하기 부족했다.`
          :`그는 싸움을 피했지만 현장에서 직접 확인한 흔적 하나는 검의 기억에 남았다. 다음 조각이 들어오면 의미가 달라질 수 있다.`,
        [{label:"이번에는 여기까지 한다",next:"END",outcome:`${info.title} 현장 확인`}]
      );
    }
  }

  /* ---------------- MAIN STREAM ---------------- */
  if(p==="sail") return showMainStoryNode(node);

  finishStory("이번 달의 일이 끝났다.");
}

const MAIN_AFTER_META={
  "1-01":{title:"육지가 뒤로 밀려난다",hook:"해가 기울 무렵 이스마로스의 낮은 성벽과 항구 연기가 수평선에 걸렸다."},
  "1-02":{title:"해가 진 뒤",hook:"시장의 소리가 잦아들자 항구 바깥에서 짧은 북소리가 세 번 울렸다."},
  "1-04":{title:"달콤한 냄새가 남은 갑판",hook:"섬을 떠난 뒤에도 몇몇 선원은 노를 젓다가 멍하니 뒤를 돌아봤다."},
  "1-05":{title:"빈자리 하나",hook:"다음 섬은 조용했다. 바위 위에는 염소가 있었고 절벽 안쪽에는 큰 동굴이 입을 벌리고 있었다."},
  "1-06":{title:"동굴 앞의 저녁",hook:"해가 사라지기 전에 동굴 안쪽에서 돌이 끌리는 소리가 들렸다."},
  "1-07":{title:"거인의 뒤를 벗어나다",hook:"배가 절벽에서 멀어질 때까지 누구도 먼저 입을 열지 않았다."}
};
function mainChoice(label,choiceId,nextNode,patch={},fact="",extra={}){
  return {label,effect:c=>{
    const sourceNode=state.mainStory.node,changes=mainAdjust(extra.delta||{});
    c.mainResolution={sourceNode,choiceId,nextNode,fact:fact||label,changes};
    mainCommit(choiceId,nextNode,patch,fact,extra.callbackId||"");
    if(extra.connectionId)markConnection(extra.connectionId,extra.connectionText||fact||label);
    if(extra.after)extra.after(c);
  },next:extra.storyNext||"main_transition"};
}
function applyChapterEntryBenefits(chapter){
  const f=state.mainStory.flags;if(f[`chapter_${chapter}_entry_applied`])return [];
  const changes=[];
  if(chapter===1){
    if(hasMainFact('provisions_trade'))changes.push(...mainAdjust({supplies:1}));
    if(hasMainFact('provisions_mine'))changes.push(...mainAdjust({supplies:1}));
    if(hasMainFact('farewell_mira'))changes.push(...mainAdjust({mind:3}));
  }else if(chapter===2){
    if(hasMainFact('provisions_second'))changes.push(...mainAdjust({supplies:1}));
  }
  f[`chapter_${chapter}_entry_applied`]=true;saveGame();return changes;
}
function mainRewardLine(title,desc){return `<div class="mainRewardBox"><b>${title}</b><span>${desc}</span></div>`;}
function grantChapter1Reward(){
  const f=state.mainStory.flags;if(f.chapter1_rewarded)return f.chapter1_reward_text||"이미 획득한 장 보상";
  let text="";
  if(f.chapter1_resolution==='boss_win'){
    addSpare('ismaros_hook',1);state.weapon.materials.iron=(state.weapon.materials.iron||0)+1;text="이스마로스 갈고리 가드 + 전투철 1";
  }else if(f.chapter1_resolution==='hideout'){
    f.ismaros_network=true;text="이스마로스 항구망 해금 · 이후 시장 파츠 입고 +1";
  }else if(f.chapter1_resolution==='exchange'){
    state.weapon.materials.bronze=(state.weapon.materials.bronze||0)+2;f.ismaros_truce=true;text="청동 2 + 이스마로스 휴전";
  }else if(f.chapter1_resolution==='mediated'){
    f.ismaros_truce=true;f.ismaros_merchant_route=true;text="이스마로스 휴전 + 상인 항로 인맥";
  }else if(f.chapter1_resolution==='outer_run'){
    f.coast_route_knowledge=true;state.weapon.materials.wax=(state.weapon.materials.wax||0)+1;text="연안 수로 지식 + 밀랍 1";
  }else if(f.chapter1_resolution==='cut_rope'){
    f.fast_departure=true;state.weapon.resonance=clamp(state.weapon.resonance+10,0,state.weapon.maxResonance);text="빠른 이탈 판단 기록 + 공명 10 회복";
  }else{
    state.weapon.materials.iron=(state.weapon.materials.iron||0)+1;text="전투철 1 · 대가를 치른 탈출 기록";
  }
  f.chapter1_rewarded=true;f.chapter1_reward_text=text;addChapterResult(1,f.chapter1_resolution||'unknown',text);saveGame();return text;
}
function grantChapter2Reward(){
  const f=state.mainStory.flags;if(f.chapter2_rewarded)return f.chapter2_reward_text||"이미 획득한 장 보상";
  let text="";
  if(f.poly_resolution==='defeat'){
    addSpare('cyclops_horn',1);state.weapon.materials.horn=(state.weapon.materials.horn||0)+1;text="「폴리페모스 뿔 폼멜」 + 거인의 뿔 1";
  }else if(f.poly_resolution==='blind'){
    unlockMainSkill('cyclops_gap');text="메인 전승 「외눈의 빈틈」";
  }else if(f.poly_resolution==='rescue'){
    unlockMainSkill('carry_them');text="메인 전승 「끝까지 데리고 간다」";
  }else if(f.poly_resolution==='scout'){
    f.cave_route_knowledge=true;state.weapon.materials.iron=(state.weapon.materials.iron||0)+1;text="영구 지식 「동굴의 숨은 길」 + 철광석 1";
  }else if(f.poly_resolution==='livestock'){
    mainAdjust({supplies:2});text="보급 +2 · 폴리페모스 직접 원한 회피";
  }else if(f.poly_resolution==='quickdraw'){
    f.quickdraw_escape_memory=true;state.weapon.resonance=clamp(state.weapon.resonance+8,0,state.weapon.maxResonance);text="역사 상태 「찰나의 이탈」 + 공명 8";
  }else{
    unlockMainSkill('cyclops_gap');text="메인 전승 「외눈의 빈틈」";
  }
  f.chapter2_rewarded=true;f.chapter2_reward_text=text;addChapterResult(2,f.poly_resolution||'unknown',text);return text;
}
function chapterEndScene(chapter){
  const f=state.mainStory.flags,e=state.mainStory.expedition;
  if(chapter===1){
    if(state.storyCtx)state.storyCtx.chapterDisplay=1;
    const reward=grantChapter1Reward();
    const ending=f.chapter1_resolution==='boss_win'?'역습대장의 전열을 부수고 마지막 사람까지 태웠다.':f.chapter1_resolution==='hideout'?'낮에 살려 둔 인연이 밤의 뒷길이 되었다.':f.chapter1_resolution==='mediated'?'낮의 거래가 밤의 중재자를 만들었다.':f.chapter1_resolution==='exchange'?'피 대신 물건과 포로가 오갔다.':f.chapter1_resolution==='outer_run'?'배를 바깥 수로에 두었던 판단이 탈출로가 되었다.':'밧줄을 끊고 떠나는 쪽을 택했다.';
    return openStoryScene("제1장 완료","전쟁의 잔향",`${ending}

이스마로스의 불빛이 수평선 아래로 사라졌다. 선원들은 갑판에 누운 사람을 세고, 남은 물통을 다시 묶었다. Legend Core는 누가 옳았는지가 아니라 무엇을 남기고 무엇을 데려왔는지를 기억했다.

획득: ${reward}`,[{label:"제1장의 기록을 닫는다",next:"END",outcome:`제1장 완료 · ${reward}`}]);
  }
  if(state.storyCtx)state.storyCtx.chapterDisplay=2;
  const reward=grantChapter2Reward();
  return openStoryScene("제2장 완료","잊는 섬과 외눈",`로토스의 향기는 사라졌지만 폴리페모스의 동굴에서 남은 흔적은 검과 사람에게 붙어 있었다.

보급 ${e.supplies} · 함선 ${e.ship}% · 선원 ${e.crew}

획득: ${reward}`,[{label:"제3장의 항로를 기록해 둔다",effect:c=>{state.mainStory.prototypeEnd=true;state.mainStory.chapter=3;saveGame();},next:"END",outcome:`제2장 완료 · ${reward} · 제3장 「잃어버린 바람」 해금 대기`}]);
}
function showMainStoryNode(node){
  ensureMainStory();const ms=state.mainStory,f=ms.flags,cur=ms.node;
  if(node==="chapter_intro"){
    const ch=mainChapterMeta(),benefits=applyChapterEntryBenefits(ms.chapter);
    const facts=mainFactTexts();
    const forced=!!f[`forced_chapter_${ms.chapter}`];
    let text='';
    if(ms.chapter===1){
      const passage=f.passage_method==='cargo_hold'?'마지막 수송선 화물칸':hasMainFact('passage_karon')?'카론이 마련한 상단 수송선':hasMainFact('passage_harbor')?'항구 경비대가 올려 준 귀향선':hasMainFact('passage_veteran')?'귀환 용병 기록에서 찾은 군선':'귀향선';
      text=`트로이의 불길이 아직 바다 위에 붉게 남아 있었다. ${state.owner.name}은 ${passage}에 올라 검을 무릎에 세웠다. 이제 전쟁은 뒤에 있고, 앞에는 집으로 돌아가는 바다가 있다.`;
      if(forced)text+=`\n\n자리를 미리 구하지 못한 대가는 분명했다. 선실도, 제대로 묶은 짐칸도 없었다.`;
    }else if(ms.chapter===2){
      text=`이스마로스를 떠난 뒤 바람이 멎었다. 며칠 뒤 낮은 섬 하나가 보였고, 해변 쪽에서는 낯선 달콤한 냄새가 올라왔다.`;
      if(forced)text+=`\n\n항로를 찾지 못한 채 다른 배의 돛만 따소유자 탓에 선원들은 이미 지쳐 있었다.`;
    }else text=`귀향길의 다음 장이 열린다.`;
    if(facts.length)text+=`\n\n출항 전에 손에 들어온 것들이 있다. ${facts.slice(0,4).join(' / ')}${facts.length>4?' 외 '+(facts.length-4)+'건':''}.`;
    if(benefits.length)text+=`\n\n출항 직전 실제 변화: ${benefits.join(' · ')}`;
    return openStoryScene(`CHAPTER ${ms.chapter}`,ch.title,text,[{label:"항해를 시작한다",next:"start"}]);
  }
  if(node==="main_transition"){
    const r=state.storyCtx?.mainResolution;if(!r)return showMainStoryNode('start');
    const meta=MAIN_AFTER_META[r.sourceNode]||{title:"선택의 여파",hook:"배는 다시 움직이기 시작했다."};
    const changes=(r.changes||[]).length?`<div class="mainAftermath"><b>실제 변화</b>${r.changes.join(' · ')}</div>`:'';
    return openStoryScene(`MAIN · ${r.sourceNode}`,meta.title,`${ownerText(r.fact)}${changes}\n\n${ownerText(meta.hook)}`,[{label:"계속 간다",next:"main_resume"}]);
  }
  if(node==="main_resume")return showMainStoryNode('start');
  if(node==="chapter1_end")return chapterEndScene(1);
  if(node==="chapter2_end")return chapterEndScene(2);

  if(node==="ms103_boss_win"){
    const changes=mainAdjust({ship:-6});f.chapter1_resolution='boss_win';mainCommit('ismaros_boss_win','1-04',{ismaros_boss_defeated:true},'이스마로스 역습대장을 꺾고 뒤처진 사람들을 태운 채 항구를 빠져나왔다.','이스마로스 역습 정면 돌파');
    state.storyCtx.mainResolution={sourceNode:'1-03',fact:'역습대장의 전열이 무너진 뒤 마지막 배가 부두를 밀어냈다.',changes};return chapterEndScene(1);
  }
  if(node==="ms103_boss_lose"){
    const changes=mainAdjust({ship:-20,crew:-2,supplies:-1});f.chapter1_resolution='boss_costly';mainCommit('ismaros_boss_costly','1-04',{ship_damaged:true},'역습대장을 넘지 못해 함선과 선원을 잃고 겨우 항구를 벗어났다.');
    state.storyCtx.mainResolution={sourceNode:'1-03',fact:'전열은 무너졌고 배 한쪽 난간도 뜯겼다. 남은 사람들은 불붙은 부두를 등지고 도망쳤다.',changes};return chapterEndScene(1);
  }
  if(node==="poly_defeat_win"){
    mainAdjust({supplies:-1});f.poly_resolution='defeat';f.poly_defeated=true;mainCommit('poly_defeat','1-08',{poly_escape:'defeat',poly_grudge:false},'폴리페모스를 정면으로 쓰러뜨리고 동굴을 장악했다.');return openStoryScene('폴리페모스','거인이 쓰러진 동굴',`거대한 몸이 바닥을 울리며 쓰러졌다. 뿔 끝에는 아직 온기가 남아 있었다.`,[{label:'절벽 쪽으로 출항한다',next:'poly_to_identity'}]);
  }
  if(node==="poly_blind_win"){
    f.poly_resolution='blind';f.poly_grudge=true;mainCommit('poly_blind','1-08',{poly_escape:'blind',poly_grudge:true},'폴리페모스의 눈을 멀게 하고 열린 틈으로 탈출했다.');return openStoryScene('폴리페모스','외눈이 닫힌 순간',`거인은 죽지 않았다. 피를 흘리며 절벽을 더듬는 고함이 배가 물살을 탈 때까지 따라왔다.`,[{label:'절벽 쪽으로 출항한다',next:'poly_to_identity'}]);
  }
  if(node==="poly_rescue_win"){
    const changes=mainAdjust({crew:1,supplies:-1});f.poly_resolution='rescue';f.poly_survivor=true;mainCommit('poly_rescue','1-08',{poly_escape:'rescue',poly_survivor:true},'거인의 압박을 버티며 갇힌 사람부터 빼냈다.','폴리페모스 구조 우선');return openStoryScene('폴리페모스','마지막 사람의 손',`동굴을 빠져나올 때 뒤에 남은 사람은 없었다.\n\n실제 변화: ${changes.join(' · ')}`,[{label:'절벽 쪽으로 출항한다',next:'poly_to_identity'}]);
  }
  if(node==="poly_combat_lose"){
    const changes=mainAdjust({crew:-2,supplies:-1,ship:-5});f.poly_resolution='blind';f.poly_grudge=true;mainCommit('poly_forced_escape','1-08',{poly_escape:'costly',poly_grudge:true},'폴리페모스를 넘지 못해 사람과 짐을 잃고 좁은 틈으로 강제 철수했다.');return openStoryScene('폴리페모스','부서진 탈출',`거인을 이기지는 못했다. 전투 중 열린 틈으로 남은 사람들이 빠져나왔다.\n\n실제 변화: ${changes.join(' · ')}`,[{label:'절벽 쪽으로 출항한다',next:'poly_to_identity'}]);
  }
  if(node==="poly_to_identity")return showMainStoryNode('start');

  if(cur==="1-01"){
    const opts=[
      mainChoice("부상자를 먼저 배에 태운다","wounded_first","1-02",{wounded_saved:true,departure:"people"},"부상자들이 살아서 배에 올랐다.",{delta:{supplies:-1,crew:2}}),
      mainChoice("약속된 몫과 보급품부터 챙긴다","share_first","1-02",{provisions_first:true,departure:"supplies"},"선창의 보급을 우선했다.",{delta:{supplies:2}}),
      mainChoice("승전 연회에 얼굴을 드러낸 뒤 출항한다","public_departure","1-02",{identity_seed:"public"},"동맹군과 항구 사람들이 얼굴과 이름을 기억했다.",{delta:{mind:3}}),
      mainChoice("새벽에 조용히 배를 띄운다","quiet_departure","1-02",{identity_seed:"hidden"},"축하도 원한도 피한 채 조용히 출항했다.",{delta:{mind:1}})
    ];
    if(hasPartTag("fleet"))opts.unshift(mainChoice("검집의 오래된 함대 표식을 보여 부상자 수송 자리를 연다","fleet_passage","1-02",{wounded_saved:true,departure:"fleet_mark",fleet_mark_seen:true},"검집의 함대 표식이 부상자 수송 자리를 열었다.",{delta:{crew:2},connectionId:"함대 검집 → 부상자 수송",connectionText:"검집의 함대 표식이 첫 출항의 부상자 수송 자리를 바꿨다."}));
    if(hasMainFact('coast_chart'))opts.push(mainChoice("폐허에서 그린 남쪽 수로 메모를 따라 먼저 빠져나간다","south_channel_departure","1-02",{departure:"south_channel",coast_route_used:true},"큰 배들이 엉킨 항구를 피해 남쪽 암초 사이로 빠져나갔다.",{delta:{supplies:-1,ship:2}}));
    return openStoryScene("트로이 · 마지막 부두","전쟁이 끝난 날",`새벽까지 술과 함성이 이어졌지만 부두에서는 이미 밧줄을 풀고 있었다. 부상자는 들것에 누워 있고, 약속된 전리품 자루는 선창 앞에 쌓였다.\n\n${state.owner.name}은 검자루를 쥔 채 어느 줄에 먼저 설지 바라봤다. 집으로 가는 길은 여기서 시작된다.`,opts);
  }
  if(cur==="1-02"){
    const variant=f.wounded_saved?"부상자를 태운 배는 물과 약을 먼저 찾았다.":f.provisions_first?"선창에 보급이 넉넉해 급하게 시장으로 뛰어갈 필요는 없었다.":f.identity_seed==="public"?"승전 연회에서 본 얼굴을 알아보는 사람이 항구에도 있었다.":"이곳에서 그를 알아보는 사람은 거의 없었다.";
    const opts=[
      mainChoice("시장과 정식으로 거래한다","trade","1-03",{ismaros:"neutral",ismaros_trader:true},"시장 상인과 정식으로 거래해 식량과 물을 샀다.",{delta:{gold:-10,supplies:2}}),
      mainChoice("창고를 털고 바로 떠날 준비를 한다","raid","1-03",{ismaros:"hostile",raid:true,captured_scout:true},"창고의 보급을 가져갔고 항구에 적대가 남았다.",{delta:{supplies:3,mind:-2}}),
      mainChoice("주민의 실종자를 먼저 찾는다","help_missing","1-03",{ismaros:"friendly",helped_missing:true},"무너진 창고 뒤에서 실종자 한 명을 찾아 주민에게 돌려보냈다.",{delta:{supplies:-1,mind:3}}),
      mainChoice("필요한 것만 보급하고 오래 머물지 않는다","quick_supply","1-03",{ismaros:"distant"},"큰 도움도 큰 원한도 남기지 않고 짧게 보급했다.",{delta:{gold:-5,supplies:1}})
    ];
    if(hasMainFact('harbor_watch')||hasMainFact('harbor_manifest'))opts.push(mainChoice("기억해 둔 접안 순서를 피해 외곽 부두에 배를 댄다","outer_berth","1-03",{ismaros:"distant",ismaros_outer_berth:true},"혼잡한 안쪽 부두를 피하고 바깥 수로에 배를 묶었다.",{delta:{gold:-3,supplies:1}}));
    return openStoryScene("이스마로스 · 낮","항구의 문",`첫 기항지 이스마로스. ${variant}\n\n전쟁에서 돌아온 배를 반기는 사람도 있었고, 닫힌 창고 앞에서 팔짱을 낀 사람도 있었다. 멀리서는 아이 이름을 부르는 여자의 목소리가 끊기지 않았다.`,opts);
  }
  if(cur==="1-03"){
    const hostile=f.ismaros==='hostile',friendly=f.ismaros==='friendly';
    const intro=hostile?"해가 떨어지자 창고 쪽에서 먼저 불이 올랐다. 낮에 쫓겨난 사람들이 무기를 들고 돌아왔다.":friendly?"밤이 되자 성 밖 잔병들이 항구로 밀려왔다. 낮에 도움받은 주민 몇은 문을 닫고 싸움에서 빠졌다.":"밤이 깊자 항구 바깥에서 북소리가 세 번 울렸다. 잠시 뒤 횃불 줄이 부두 쪽으로 움직였다.";
    const forced=!!f.forced_chapter_1,harborIntel=hasMainFact('harbor_watch')||hasMainFact('harbor_manifest'),coastChart=hasMainFact('coast_chart');
    const mods={hpScale:(hostile?1.20:friendly?.90:1)*(forced?1.12:1)*(coastChart?.96:1),attackDelta:(hostile?2:0)+(forced?1:0)+(harborIntel?-1:0),defenseDelta:friendly?-1:0};
    const opts=[
      {label:"후미에 남아 역습대장을 막고 뒤처진 사람들을 태운다",effect:c=>{c.notes.push('이스마로스 보스전 진입');},combat:{enemy:"ismaros",label:"제1장 BOSS · 이스마로스 역습대장",win:"ms103_boss_win",lose:"ms103_boss_lose",mods}},
      mainChoice("밧줄을 끊고 주력선을 즉시 출항시킨다","cut_rope","1-04",{crew_left:true,ship_saved:true,chapter1_resolution:'cut_rope'},"배를 살리기 위해 부두에 남은 사람을 포기했다.",{delta:{crew:-3},storyNext:'chapter1_end'})
    ];
    if(f.captured_scout)opts.push(mainChoice("붙잡아 둔 정찰병과 항구의 포로를 교환한다","prisoner_exchange","1-04",{ismaros:"softened",chapter1_resolution:'exchange'},"붙잡은 정찰병을 넘기고 항구에 묶인 사람들을 돌려받았다.",{delta:{supplies:-1},storyNext:'chapter1_end'}));
    if(f.ismaros_trader)opts.push(mainChoice("낮에 거래한 상인에게 중재를 맡긴다","merchant_mediation","1-04",{ismaros:"softened",chapter1_resolution:'mediated'},"상인이 양쪽 사이에 서는 동안 전리품 일부를 내려놓고 사람들을 배에 태웠다.",{delta:{gold:-12,supplies:-1},storyNext:'chapter1_end'}));
    if(f.helped_missing)opts.push(mainChoice("낮에 도운 주민에게 뒷길을 부탁한다","resident_hideout","1-04",{ismaros_escape:true,chapter1_resolution:'hideout'},"낮에 구해 준 사람이 항구 뒤편 창고문을 열어 주었다.",{storyNext:'chapter1_end',callbackId:"이스마로스 실종자 구조"}));
    if(f.ismaros_outer_berth&&harborIntel)opts.push(mainChoice("외곽 부두의 수로를 따라 상륙조만 회수해 빠져나간다","outer_run","1-04",{chapter1_resolution:'outer_run',outer_channel_escape:true},"배가 안쪽 부두에 묶여 있지 않았기 때문에 상륙조만 뛰어오르면 됐다.",{delta:{crew:-1,ship:-3},storyNext:'chapter1_end',callbackId:"이스마로스 외곽 부두"}));
    return openStoryScene("이스마로스 · 밤","북소리 세 번",`${intro}\n\n선착장의 밧줄은 팽팽했고, 아직 돌아오지 못한 사람도 있었다. 앞쪽에서는 갑옷을 입은 대장이 부두를 가로막았다.`,opts);
  }

  // 제2장은 v2.0의 연속 장 엔진을 사용하지만 콘텐츠 확장은 다음 패스에서 진행한다.
  if(cur==="1-04"){
    const forcedNote=f.forced_chapter_2?`\n\n항로를 잡지 못한 채 다른 배를 따라 들어온 탓에 선원들의 얼굴은 이미 지쳐 있었다.`:'';
    return openStoryScene("로토스 섬","달콤한 냄새",`바람이 끊긴 섬에서 선원 몇이 달콤한 열매를 먹은 뒤 고향 이야기를 멈췄다.${forcedNote}`,[
      mainChoice("먹은 사람을 강제로 배로 끌고 간다","lotus_force","1-05",{lotus:"force"},"대부분을 데려왔지만 반발이 남았다.",{delta:{mind:-3}}),
      mainChoice("직접 조금 먹어 효과를 확인한다","lotus_taste","1-05",{lotus:"experienced",lotus_experience:true},"로토스가 기억과 욕망을 흐리는 방식을 직접 겪었다.",{delta:{mind:-6}}),
      mainChoice("남고 싶다는 사람은 남겨둔다","lotus_leave","1-05",{lotus:"left",lotus_left:true},"몇 사람은 섬에 남았다.",{delta:{crew:-2}}),
      mainChoice("밭을 태워 모두를 깨운다","lotus_burn","1-05",{lotus:"hostile"},"선원들은 깨어났지만 섬 주민과 충돌했다.",{delta:{supplies:-1,mind:-2}})
    ]);
  }
  if(cur==="1-05"){
    const variant=f.lotus==='force'?"강제로 데려온 사람들 사이에 침묵이 길었다.":f.lotus_left?"빈자리는 출항 직전 더 선명해졌다.":"출항 직전 한 사람이 사라진 사실이 드러났다.";
    return openStoryScene("로토스 섬 · 출항 전","돌아오지 않는 선원",variant,[
      mainChoice("직접 찾으러 간다","search_sailor","1-06",{missing_sailor:"searched",sailor_saved:true},"숲 가장자리에서 사라진 선원을 찾아냈다.",{delta:{supplies:-1,crew:1,mind:2}}),
      mainChoice("두 사람만 보내고 배는 준비한다","send_two","1-06",{missing_sailor:"delegated"},"수색을 맡기고 출항 준비를 계속했다.",{}),
      mainChoice("종을 세 번 울리고 정해진 시간까지만 기다린다","bell_wait","1-06",{missing_sailor:"waited"},"돌아올 기회를 주되 시간 제한을 뒀다.",{delta:{supplies:-1}}),
      mainChoice("떠난다","leave_sailor","1-06",{missing_sailor:"left",sailor_left:true},"항로를 지키고 한 사람을 섬에 남겼다.",{delta:{crew:-1}})
    ]);
  }
  if(cur==="1-06")return openStoryScene("염소섬","절벽 안쪽의 불빛",`바위 위에는 염소 떼가 흩어져 있었고 절벽 안쪽에는 사람이 서서 걸어 들어갈 만큼 큰 동굴이 있었다. 입구 주변에는 너무 큰 발자국이 찍혀 있었다.`,[
    mainChoice("동굴과 바위틈을 멀리서 정찰한다","scout_cave","1-07",{poly_scout:true},"가축이 드나드는 바위틈과 내부 동선을 미리 확인했다.",{delta:{supplies:-1}}),
    mainChoice("가축만 챙기고 깊이 들어가지 않는다","take_livestock","1-07",{poly_entry:"shallow",livestock_ready:true},"식량을 확보했지만 동굴 주인의 흔적을 건드렸다.",{delta:{supplies:2}}),
    mainChoice("주인을 만나 거래하자고 한다","negotiate_entry","1-07",{poly_entry:"talk",poly_talk_ready:true},"정면으로 들어가되 먼저 말을 걸 준비를 했다.",{delta:{mind:1}}),
    mainChoice("선원들에게 결정을 맡긴다","crew_decides","1-07",{poly_entry:"crew",crew_agency:true},"통제권과 책임을 선원들에게 나눴다.",{delta:{mind:2}})
  ]);
  if(cur==="1-07"){
    const build=activeBuilds().map(x=>x.id),forced=!!f.forced_chapter_2,omen=hasMainFact('omen_oneeye'),rope=hasMainFact('rope_cave'),modsBase={hpScale:(f.poly_scout?0.88:1)*(forced?1.12:1)*(omen?.95:1),attackDelta:(f.poly_talk_ready?-2:0)+(forced?1:0)+(omen?-1:0),defenseDelta:f.poly_scout?-1:0,evasionDelta:(f.poly_scout?-1:0)+(rope?-1:0)};
    const opts=[];
    if(build.includes('breaker')||state.weapon.power>=20)opts.push({label:"거인의 공격을 받아내며 정면으로 쓰러뜨린다",combat:{enemy:"cyclops",label:"제2장 BOSS · 폴리페모스 정면전",win:"poly_defeat_win",lose:"poly_combat_lose",mods:{...modsBase,hpScale:Math.max(1.05,modsBase.hpScale)}}});
    opts.push({label:"눈을 노려 시야를 끊고 탈출로를 만든다",combat:{enemy:"cyclops",label:"제2장 BOSS · 폴리페모스 약점전",win:"poly_blind_win",lose:"poly_combat_lose",mods:{...modsBase,hpScale:modsBase.hpScale*.82,evasionDelta:(modsBase.evasionDelta||0)-2}}});
    if(f.sailor_saved||f.wounded_saved)opts.push({label:"갇힌 사람부터 꺼내며 거인의 압박을 버틴다",combat:{enemy:"cyclops",label:"제2장 BOSS · 폴리페모스 구조전",win:"poly_rescue_win",lose:"poly_combat_lose",mods:{...modsBase,hpScale:modsBase.hpScale*1.05,attackDelta:(modsBase.attackDelta||0)+1}}});
    if(f.poly_scout)opts.push(mainChoice("정찰 때 본 바위틈으로 사람들을 빼낸다","poly_scout_escape","1-08",{poly_resolution:'scout',poly_escape:'scout'},"사전 정찰로 확인한 바위틈을 이용해 빠져나왔다.",{callbackId:"염소섬 사전 정찰"}));
    if(f.livestock_ready)opts.push(mainChoice("가축 무리 아래로 숨어 동굴을 빠져나간다","poly_livestock_escape","1-08",{poly_resolution:'livestock',poly_escape:'livestock'},"가축 무리를 이용해 사람들을 먼저 빼냈다.",{}));
    if(hasPartTag('quickdraw')&&state.weapon.handling>=12)opts.push(mainChoice("거인이 손을 뻗는 순간 결박끈을 끊고 빠져나간다","poly_quickdraw_escape","1-08",{poly_resolution:'quickdraw',poly_escape:'quickdraw',cargo_left:true},"빠른 발도 세팅이 찰나의 탈출로를 만들었지만 짐 일부를 버렸다.",{delta:{supplies:-2},connectionId:"빠른 발도 검집 → 폴리페모스 탈출",connectionText:"빠른 발도 검집이 폴리페모스 보스의 별도 탈출법을 열었다."}));
    return openStoryScene("폴리페모스의 동굴","외눈의 거인",`동굴 입구가 거대한 바위로 막혔다. 안쪽에서 하나뿐인 눈이 횃불을 따라 움직였다.`,opts);
  }
  if(cur==="1-08"){
    if(!f.chapter2_rewarded)grantChapter2Reward();
    const opts=[
      mainChoice("진짜 이름을 외친다","true_name","1-09",{identity:"A",polyphemus_name:"true"},"폴리페모스는 진짜 이름을 기억했다.",{storyNext:'chapter2_end'}),
      mainChoice("끝까지 침묵한다","silent_name","1-09",{identity:"B",polyphemus_name:"silent"},"정체를 밝히지 않은 채 바다로 멀어졌다.",{storyNext:'chapter2_end'}),
      mainChoice("거짓 이름을 남긴다","false_name","1-09",{identity:"B",polyphemus_name:"false"},"진짜 정체는 숨겼지만 거짓 이름이 바다에 떠돌기 시작했다.",{storyNext:'chapter2_end'})
    ];
    if(f.poly_survivor||f.sailor_saved||f.wounded_saved)opts.push(mainChoice("살아난 사람이 대신 이름을 외치게 둔다","witnessed_name","1-09",{identity:"A",polyphemus_name:"witnessed"},"생존자의 목소리가 이름을 남겼다.",{storyNext:'chapter2_end',callbackId:"생존자의 증언"}));
    return openStoryScene("폴리페모스의 절벽","이름을 부르는 목소리",`배가 절벽에서 멀어질 때 뒤에서 거인의 고함이 들렸다. 누구냐고 묻는 목소리였다.`,opts);
  }
  if(state.mainStory.prototypeEnd)return openStoryScene("MAIN STREAM","제2장 완료",`다음 MAIN은 제3장 「잃어버린 바람」에서 이어진다.`,[{label:"현재 연대기로 돌아간다",next:"END",outcome:"제2장까지 MAIN 구현 완료"}]);
  return openStoryScene("MAIN STREAM","현재 구현 범위 종료",`제2장 이후의 MAIN은 아직 열리지 않았다.`,[{label:"돌아간다",next:"END",outcome:"MAIN 구현 범위 종료"}]);
}

function finishStory(outcome){
  const c=state.storyCtx,b=c.before;
  if(state.prep.rations>0 && ["contract","explore"].includes(state.policy)){
    state.prep.rations--;
    state.hp=clamp(state.hp+5,0,state.maxHp);
    c.notes.push("고급 건조식을 먹어 HP 5 회복");
  }

  state.weapon.dur=clamp(state.weapon.dur,0,state.weapon.maxDur);
  if(state.hp>0&&state.hp<35)recordDeed("survival",`${state.year}-${state.month}:${state.policy}:${state.subChoice}`);
  if(state.weapon.dur<=20){
    state.mind=clamp(state.mind-4,0,state.maxMind);
    c.notes.push("검 내구가 20 이하로 떨어져 정신 4 감소");
  }
  let failed=/실패|패배|포기|놓친|미완료/.test(String(outcome||''));
  const integrated=resolveIntegratedEventOutcomeV27(state.policy,clamp(Number(c.difficulty)||1,1,4),c,outcome);
  if(integrated){failed=failed||integrated.grade==='setback';c.v27Narrative=integrated.narrative;c.v27OutcomeLabel=integrated.outcomeLabel;}
  awardLifeExperience(state.policy,clamp(Number(c.difficulty)||1,1,4),failed,c);
  if(!failed && !['sail','succession'].includes(state.policy)){
    const tier=clamp(Number(c.rewardTier)||1,1,4);
    if(state.policy==='contract'&&tier>1){const bonus=(tier-1)*5;state.gold+=bonus;c.notes.push(`난이도 보상 GOLD +${bonus}`);}
    if(state.policy==='explore'&&tier>1){const mat=tier>=4?'steel':tier===3?'bronze':'iron';state.weapon.materials[mat]=(state.weapon.materials[mat]||0)+1;c.notes.push(`난이도 보상 ${MATERIAL_LABELS[mat]||mat} +1`);}
    if(state.policy==='investigate'&&tier>1){const rr=(tier-1)*2;state.weapon.resonance=clamp(state.weapon.resonance+rr,0,state.weapon.maxResonance);c.notes.push(`조사 성과 공명 +${rr}`);}
    if(state.policy==='rest'&&tier>1){const heal=(tier-1)*3;state.hp=clamp(state.hp+heal,0,state.maxHp);state.mind=clamp(state.mind+heal,0,state.maxMind);c.notes.push(`회복 보상 HP/정신 +${heal}`);}
  }

  const selectedEvent=state.monthEvents.find(e=>e.chosen);
  if(selectedEvent)settleWorldIncident(selectedEvent,c.v27OutcomeLabel||outcome,failed,c);
  const dh=state.hp-b.hp,dm=state.mind-b.mind,dg=state.gold-b.gold,dr=Math.round(state.weapon.resonance-b.resonance);
  const fragmentHtml=(c.fragmentsGained||[]).length
    ?`<div class="sectionMini">확보한 증거</div><div class="invList">${c.fragmentsGained.map(x=>{const st=STORY_CATALOG[x.storyId],fr=st.fragments.find(f=>f.id===x.fragmentId);return `<div class="invItem"><div><b>${fr?.name||x.fragmentId}</b><span>「${st.name}」 ${storyProgressText(x.storyId)}</span></div><span class="invQty">◆</span></div>`}).join('')}</div>`:'';
  const unlockHtml=(c.reconstructionReady||[]).map(sid=>{const st=STORY_CATALOG[sid];return `<div class="unlockBox"><b>증거 완성 · 「${st?.name||sid}」</b><span>조각은 모두 모였다. 아직 스킬이 아니다.</span><span>기억 재구성을 거쳐야 Legend Core의 실제 능력이 된다.</span></div>`}).join('');
  const extra=[];
  if(dr)extra.push(`공명 ${delta(dr)}`);
  if(c.notes.length)extra.push(...c.notes);
  const extraHtml=extra.length?`<div class="dialogue"><div class="speaker">실제 변화</div><div class="quote" style="font-size:9px">${extra.join(" · ")}</div></div>`:'';
  if(selectedEvent){recordMainPreparation(selectedEvent,c.v27OutcomeLabel||outcome);addWorldFact(`「${selectedEvent.title}」 — ${ownerText(c.v27OutcomeLabel||outcome)}`,`outcome:${state.year}:${state.month}:${state.policy}:${state.subChoice}`);}
  if(state.policy==='contract'&&state.subChoice==='escort')state.contacts.karon.status=String(outcome).includes('실패')?'이번 호위 결과를 지켜보는 거래 상대':'호위를 맡길 수 있다고 보는 거래 상대';
  if(state.policy==='rest'&&state.subChoice==='friends')state.contacts.mira.status='검의 소유자에게 문을 열어두는 사람';

  openModal(
    `<div class="modalHead"><b>${state.year}년차 ${state.month}월 결과</b></div>
     <div class="dialogue"><div class="speaker">${policyNames[state.policy]}</div><div class="quote">${ownerText(c.v27Narrative||outcome)}</div></div>
     <div class="resultStats">
       <div class="resultStat">HP<b class="${dh<0?'warn':'goodText'}">${delta(dh)}</b></div>
       <div class="resultStat">정신<b class="${dm<0?'warn':'blueText'}">${delta(dm)}</b></div>
       <div class="resultStat">GOLD<b>${delta(dg)}</b></div>
       <div class="resultStat">서사<b>${state.unlockedSkills.length}</b></div>
     </div>
     ${fragmentHtml}${unlockHtml}${extraHtml}
     <button class="primary" id="nextMonth">다음 달</button>`
  );
  $("nextMonth").onclick=()=>{
    const selected=state.monthEvents.find(e=>e.chosen);if(selected)state.eventHistory.push({year:state.year,month:state.month,event:`${selected.policy}:${selected.id}`,result:'chosen'});
    const ready=[...(c.reconstructionReady||[])];
    const advance=()=>advanceCalendar();
    if(ready.length){let i=0;const step=()=>{if(i>=ready.length)return advance();openReconstruction(ready[i++],step);};closeModal();step();}else advance();
  };
}


