function blankOwnerEquipment(){return {helmet:null,armor:null,gloves:null,boots:null};}
function ensureV24State(){
  if(!state.ownerEquipment)state.ownerEquipment=blankOwnerEquipment();
  for(const k of Object.keys(OWNER_GEAR_SLOTS))if(!(k in state.ownerEquipment))state.ownerEquipment[k]=null;
  if(!state.ownerGearOwned||typeof state.ownerGearOwned!=='object')state.ownerGearOwned={};
  if(!state.bagId||!BAG_CATALOG[state.bagId])state.bagId='cloth_sack';
  if(!state.foodBuff)state.foodBuff=null;
  if(!Array.isArray(state.pastOwners))state.pastOwners=[];
  if(!Array.isArray(state.pastContacts))state.pastContacts=[];
  if(!Array.isArray(state.weapon.deathMemories))state.weapon.deathMemories=[];
  if(!Array.isArray(state.weapon.legacyTitles))state.weapon.legacyTitles=[];
  if(!state.marketV24||typeof state.marketV24!=='object')state.marketV24={};
  if(!state.prep)state.prep={}; if(!Number.isFinite(state.prep.tonic))state.prep.tonic=0;
  if(!state.smithPartStock||!Array.isArray(state.smithPartStock))state.smithPartStock=[];
  if(!state.contactTopics)state.contactTopics={mira:[],karon:[]};
  if(!state.weapon.materials)state.weapon.materials={iron:0,shell:0,bronze:0,leather:0,wood:0,steel:0,silverWire:0,wax:0,cloth:0,horn:0};
}
function ownerGearBonuses(){
  ensureV24State();const out={defense:0,evade:0,resist:0,maxHp:0,survival:0};
  Object.values(state.ownerEquipment).filter(Boolean).forEach(id=>{const m=OWNER_GEAR_CATALOG[id]?.mods||{};for(const k of Object.keys(out))out[k]+=Number(m[k]||0);});
  return out;
}

