function randomGearStock(){const ids=Object.keys(OWNER_GEAR_CATALOG),picked=[];while(picked.length<6&&picked.length<ids.length){const id=choice(ids);if(!picked.includes(id))picked.push(id);}return picked.map(id=>({id,sold:false}));}
function generateSmithPartStockV24(){const out=[],used=new Set(),count=state.mainStory?.flags?.ismaros_network?6:5;for(let i=0;i<count;i++){const x=weightedMarketPart(used);if(!x)break;used.add(x.id);out.push({id:x.id,slot:x.slot,sold:false,price:marketPartPrice(x.id)});}return out;}
function resetMarketOnlyV24(){ensureV24State();state.marketStock={medkit:ri(1,3),rations:ri(1,3),antidote:ri(0,2),bandage:ri(1,3),tonic:ri(1,2)};state.marketV24={armor:randomGearStock(),general:{iron:ri(1,3),bronze:ri(1,2),leather:ri(1,3),wood:ri(1,3),steel:ri(0,1),cloth:ri(1,2),rations:ri(1,3)},food:{mutton_stew:1,fish_olive:1,spiced_wine:1,sailor_plate:1}};}
function resetMarketStock(){resetMarketOnlyV24();state.smithPartStock=generateSmithPartStockV24();state.marketPartStock=[];}
function refreshMarket(tab='healer'){const cost=state.marketRefreshFree?0:8;if(cost&&state.gold<cost)return;if(cost){state.gold-=cost;state.marketPaidRefreshes=(state.marketPaidRefreshes||0)+1;}else state.marketRefreshFree=false;resetMarketOnlyV24();addLog(cost?'시장 상인들의 재고를 8G에 다시 확인했다.':'시장 재고를 무료로 한 번 다시 확인했다.');saveGame();openMarket(tab);render();}
