function sellOwnerGear(id){ensureV24State();const it=OWNER_GEAR_CATALOG[id];if(!it||(state.ownerGearOwned[id]||0)<1)return 0;if(Object.values(state.ownerEquipment).includes(id))return 0;const price=Math.max(4,Math.floor(it.price*.45));state.ownerGearOwned[id]--;state.gold+=price;addLog(`${it.name}을 ${price}G에 팔았다.`);saveGame();return price;}
