function openSmithBuy(filterSlot=null){ensureV24State();if(!state.smithPartStock.length)state.smithPartStock=generateSmithPartStockV24();const rows=state.smithPartStock.filter(row=>!filterSlot||row.slot===filterSlot).map(row=>{const it=PART_CATALOG[row.slot]?.[row.id];if(!it)return '';discoverPart(row.id);return `<button class="smithChoiceBtn ${rarityFrameClass(row.id)}" data-smith-buy="${row.id}" data-smith-slot="${row.slot}" ${row.sold||state.gold<row.price||!hasOwnerCapacity(1,'part')?'disabled':''}><b>${PART_LABELS[row.slot]} · ${it.name}</b><span>${it.material}${it.passive?'<br>'+it.passive:''}<br>${row.sold?'판매 완료':row.price+'G'}</span>${partDeltaHtml(row.slot,row.id)}</button>`}).join('');const empty=filterSlot?`현재 ${PART_LABELS[filterSlot]} 입고품이 없다.`:'입고된 파츠가 없다.';openModal(smithWorkbenchShell('구매','완성 검 부품은 시장이 아니라 대장간을 통해 유통된다. 우측 장착 파츠를 누르면 같은 부위만 본다.',`<div class="smithChoiceGrid">${rows||`<div class="invEmpty">${empty}</div>`}</div>`,filterSlot,true));bindSmithBack();bindSmithPartFilter(openSmithBuy,filterSlot);document.querySelectorAll('[data-smith-buy]').forEach(b=>b.onclick=()=>{const id=b.dataset.smithBuy,slot=b.dataset.smithSlot,row=state.smithPartStock.find(x=>x.id===id&&x.slot===slot&&!x.sold);if(!row||state.gold<row.price||!hasOwnerCapacity(1,'part'))return;state.gold-=row.price;row.sold=true;addSpare(id,1);state.partOrigins[id]=state.partOrigins[id]||`${state.year}년차 ${state.month}월 · 대장간 구매`;addLog(`대장간에서 ${PART_CATALOG[slot][id].name}을 구입했다.`);saveGame();openSmithBuy(filterSlot);render();});}
function openSmithSell(filterSlot=null){const rows=Object.entries(state.weapon.spareParts).filter(([id,n])=>n>0&&(!filterSlot||findPartSlot(id)===filterSlot)).map(([id,n])=>{const slot=findPartSlot(id),it=PART_CATALOG[slot]?.[id],price=Math.max(4,Math.floor(Number(it.shopPrice||it.cost?.gold||12)*.45));return `<button class="smithChoiceBtn ${rarityFrameClass(id)}" data-smith-sell="${id}"><b>${PART_LABELS[slot]} · ${it.name}</b><span>보관 ${n} · 판매 ${price}G</span></button>`}).join('');const empty=filterSlot?`판매할 ${PART_LABELS[filterSlot]} 예비 파츠가 없다.`:'판매할 예비 파츠가 없다.';openModal(smithWorkbenchShell('판매','검 부품 매각 대금은 즉시 소유자의 GOLD에 들어온다. 우측 장착 파츠로 부위를 좁힐 수 있다.',`<div class="smithChoiceGrid">${rows||`<div class="invEmpty">${empty}</div>`}</div>`,filterSlot,true));bindSmithBack();bindSmithPartFilter(openSmithSell,filterSlot);document.querySelectorAll('[data-smith-sell]').forEach(b=>b.onclick=()=>{sellSparePart(b.dataset.smithSell);openSmithSell(filterSlot);render();});}
function openSmithCraft(filterSlot=null){const rows=[];for(const [slot,items] of Object.entries(PART_CATALOG)){if(filterSlot&&slot!==filterSlot)continue;for(const [id,it] of Object.entries(items)){const known=(state.discoveredParts||[]).includes(id)||(!it.requiresSkill&&partRarity(id).rank<=1);const skillOk=!it.requiresSkill||skillUnlocked(it.requiresSkill);if(!known||!skillOk||!it.cost)continue;rows.push(`<button class="smithChoiceBtn ${rarityFrameClass(id)}" data-smith-craft="${id}" ${canPay(it.cost)&&hasOwnerCapacity(1,'part')?'':'disabled'}><b>${PART_LABELS[slot]} · ${it.name}</b><span>${it.material}<br>${costText(it.cost)}</span></button>`)}}const empty=filterSlot?`현재 알고 있는 ${PART_LABELS[filterSlot]} 제작법이 없다.`:'현재 제작 가능한 설계가 없다.';openModal(smithWorkbenchShell('제작','발견했거나 기억으로 알아낸 제작법만 나타난다. 우측의 장착 파츠를 누르면 그 부위의 제작법만 왼쪽에 표시된다.',`<div class="smithChoiceGrid">${rows.join('')||`<div class="invEmpty">${empty}</div>`}</div>`,filterSlot,true));bindSmithBack();bindSmithPartFilter(openSmithCraft,filterSlot);document.querySelectorAll('[data-smith-craft]').forEach(b=>b.onclick=()=>{const id=b.dataset.smithCraft,slot=findPartSlot(id),it=PART_CATALOG[slot]?.[id];if(!it||!canPay(it.cost||{})||!hasOwnerCapacity(1,'part'))return;payCost(it.cost||{});addSpare(id,1);discoverPart(id);state.partOrigins[id]=state.partOrigins[id]||`${state.year}년차 ${state.month}월 · 대장간 제작`;addLog(`${it.name}을 제작했다.`);saveGame();openSmithCraft(filterSlot);render();});}

