function weaponLineageHtml(){ensureV24State();const past=state.pastOwners.slice(-4).reverse().map(o=>`<div class="lineageCard"><b>제${o.generation}대 · ${o.name}</b>${o.role} · ${o.endReason||'검을 떠남'}${o.legacyTitle?`<br>${o.legacyTitle}`:''}</div>`).join('');const memories=state.weapon.deathMemories.slice(-3).reverse().map(m=>`<div class="lineageCard"><b>${m.title}</b>${m.text}</div>`).join('');return `<div class="ownerLineage">${past||'<div class="lineageCard"><b>제1대의 기록</b>아직 이 검은 첫 주인의 손에 있다.</div>'}${memories}</div>`;}
function applyFoodToCombat(g){const f=state.foodBuff;if(!f)return {...g,combatHp:0};const out={...g,defense:g.defense+(f.defense||0),evade:g.evade+(f.evasion||0),resist:g.resist+(f.resist||0),combatHp:f.combatHp||0};state.foodBuff=null;return out;}

