function loadGame(){try{const raw=localStorage.getItem(SAVE_KEY)||LEGACY_SAVE_KEYS.map(k=>localStorage.getItem(k)).find(Boolean);if(!raw){ensureV24State();return false;}const data=v48PrepareLoad(raw);Object.assign(state,data);state.gold=Number(state.gold)||0;state.resonanceTopics=new Set(data.resonanceTopics||[]);state.storyCtx=null;state.activeStory=null;ensureV24State();ensureMainStory();if(!state.firstYear)state.firstYear={callbacks:[],connections:[],summaryShown:false,mainCompletedMonth:null,ownerRefusals:0};state.firstYear.callbacks=state.firstYear.callbacks||[];state.firstYear.connections=state.firstYear.connections||[];state.discoveredParts=Array.isArray(data.discoveredParts)?data.discoveredParts:[];Object.values(state.weapon.parts||{}).forEach(discoverPart);Object.keys(state.weapon.spareParts||{}).forEach(discoverPart);ensureWorldEngine();processWorldCallbacks();syncOwnerVitalCaps(false);if(!state.marketV24?.armor?.length)resetMarketStock();v48EnsureState();return true;}catch(e){console.error("v4.8: 저장 불러오기 실패",e);try{const bad=localStorage.getItem(SAVE_KEY);v48BackupRaw(bad,true);}catch(_){}ensureV24State();return false;}}


