// ===== v2.6 OWNER GROWTH / MIND / FOUR-ARMOR SYSTEM =====
function ensureV26Progression(){
  ensureV24State();
  if(!state.ownerProgress||typeof state.ownerProgress!=='object')state.ownerProgress={};
  const p=state.ownerProgress;
  if(!Number.isFinite(p.level))p.level=1;if(!Number.isFinite(p.combatXp))p.combatXp=0;if(!Number.isFinite(p.lifeXp))p.lifeXp=0;if(!Number.isFinite(p.reputation))p.reputation=0;
  if(!p.eventCounts||typeof p.eventCounts!=='object')p.eventCounts={contract:0,explore:0,investigate:0,rest:0};
  for(const k of ['contract','explore','investigate','rest'])if(!Number.isFinite(p.eventCounts[k]))p.eventCounts[k]=0;
  if(!Number.isFinite(p.eventWins))p.eventWins=0;if(!Number.isFinite(p.eventFails))p.eventFails=0;
  // v2.6 migration: owner armor is only four body slots.
  const clean=blankOwnerEquipment();for(const k of Object.keys(clean)){const id=state.ownerEquipment?.[k];clean[k]=id&&OWNER_GEAR_CATALOG[id]?id:null;}state.ownerEquipment=clean;
  const owned={};for(const [id,n] of Object.entries(state.ownerGearOwned||{}))if(OWNER_GEAR_CATALOG[id]&&n>0)owned[id]=n;state.ownerGearOwned=owned;
  for(const n of Object.values(state.contacts||{}))if(!Number.isFinite(n.affinity))n.affinity=20;
  if(state.marketV24?.armor)state.marketV24.armor=state.marketV24.armor.filter(x=>OWNER_GEAR_CATALOG[x.id]);
  if(!state.marketV24?.armor?.length)state.marketV24.armor=randomGearStock();
}
function mentalPerformance(){
  const ratio=state.maxMind>0?state.mind/state.maxMind:0;
  if(ratio>=.80)return {mult:1,label:'안정',pct:100};
  if(ratio>=.60)return {mult:.95,label:'동요',pct:95};
  if(ratio>=.40)return {mult:.85,label:'불안',pct:85};
  if(ratio>=.20)return {mult:.70,label:'심각',pct:70};
  if(ratio>0)return {mult:.50,label:'붕괴',pct:50};
  return {mult:.35,label:'정신 붕괴',pct:35};
}
function combatXpNeed(level){return 55+Math.max(1,level)*35;}
function levelMartialBonus(){ensureV26Progression();return Math.floor((state.ownerProgress.level-1)*.75);}

