function weaponNarrativeBonus(){const n=(state.weapon.legacyTitles?.length||0)+(state.unlockedSkills?.length||0)+Math.floor((state.mainStory?.act1ChapterResults?.length||0)/2);return clamp(Math.floor(n/3),0,4);}
