  const level=levelMartialBonus(),weapon=weaponMartialBonus(),life=lifeExperienceBonus(),armor=armorSurvivalValue(),relations=relationNetworkBonus(),reputation=reputationBonus(),narrative=weaponNarrativeBonus();
