  state.mind=clamp(Number(state.mind)||0,0,100);
  if(!state.visitAffinityMonth||typeof state.visitAffinityMonth!=='object')state.visitAffinityMonth={};
  if(!state.contactDialogueCounters||typeof state.contactDialogueCounters!=='object')state.contactDialogueCounters={};
  if(!state.resonanceDialogueCounters||typeof state.resonanceDialogueCounters!=='object')state.resonanceDialogueCounters={};
