function resolveMainDefeatV29(ch,died=false){
  ensureV25MainState();const c=act1ChapterByIndexV25(ch);if(!c||state.mainStory.flags[`act1_ch${ch}_complete`])return MAIN_DEFEAT_V29[ch];
  const d=MAIN_DEFEAT_V29[ch];if(d?.delta)mainAdjust(d.delta);if(d?.flag)state.mainStory.flags[d.flag]=true;
  state.mainStory.flags[`act1_ch${ch}_defeat`]=died?'death':'survived';
  addWorldFact(`${c.title} — ${d?.title||'패배의 결과가 세계에 남았다.'}`,`act1:defeat:${ch}`);
  completeAct1ChapterV25(ch,died?'owner_death':'defeat',{[`act1_ch${ch}_boss_result`]:'defeat'});
  if(ch===8){state.mainStory.flags.polyphemus_name='unknown';state.mainStory.flags.act1_final_result=died?'owner_death':'escaped_after_defeat';}
  return d;
}
