function ensureV30State(){
  ensureV26Progression();ensureV25MainState();ensureWorldEngine();ensureV24State();
  state.systemVersion='3.3';
  state.mainStory.engine='act1_8ch_v30';
  state.mainStory.gate=null;state.mainStory.prototypeEnd=false;state.successionDone=false;
  if(!Array.isArray(state.mainStory.act1ChapterResults))state.mainStory.act1ChapterResults=[];
  // migrate legacy chapter result rows only when no canonical result exists.
  if(!state.mainStory.act1ChapterResults.length&&Array.isArray(state.mainStory.chapterResults)){
    for(const r of state.mainStory.chapterResults){const ch=Number(r.chapter);if(ch>=1&&ch<=8&&!state.mainStory.act1ChapterResults.some(x=>x.chapter===ch))state.mainStory.act1ChapterResults.push({chapter:ch,result:r.result||'legacy',year:r.year||state.year,month:r.month||state.month,migrated:true});}
  }
  const current=currentAct1ChapterV25();state.mainStory.chapter=current?current.index:8;
  // Canonical four owner equipment slots. v2.9 accidentally audited "head" instead of "helmet".
  const eq=state.ownerEquipment||{},clean=blankOwnerEquipment();
  for(const k of Object.keys(clean)){const id=eq[k];clean[k]=id&&OWNER_GEAR_CATALOG[id]?.slot===k?id:null;}state.ownerEquipment=clean;
  state.maxMind=100;state.mind=clamp(Number(state.mind)||0,0,100);
  state.monthEvents=(state.monthEvents||[]).filter(e=>e.policy!=='succession'&&e.id!=='handover');
  if(!Array.isArray(state.worldPeople))state.worldPeople=[];
  if(!state.worldClock)state.worldClock={skippedMonths:0,lastSuccessionGap:0};
  for(const [id,n] of Object.entries(state.contacts||{})){
    if(!Number.isFinite(n.affinity))n.affinity=18;
    if(n.alive===undefined)n.alive=true;if(n.present===undefined)n.present=true;
    if(!n.profession)n.profession=n.kind==='broker'?'중개·작업업':'지역 주민';
    if(!n.place)n.place=contactPlaceV28(id,n);
    if(!n.home)n.home=n.place;
    if(!n.worldId)n.worldId=`g${state.generation}_${id}_${String(n.name||'npc')}`;
  }
  // Spare weapon parts are deliberately persistent smith-vault assets. 45% resale prevents
  // death-before-liquidation from becoming lossless gold inheritance.
  state.weaponVaultRule='검 예비 파츠는 대장간 보관 자산으로 세대를 넘어 유지 · 판매가는 기준가의 약 45%';
}
function contactPlaceV28(id,n){return n?.place||n?.home||(id==='mira'?`${n.name}의 집`:id==='karon'?`${n.name}의 창고`:n?.kind==='broker'?`${n.name}의 작업실`:`${n.name}이 머무는 곳`);}
function makeNewContacts(profile){
  const origin=profile?.origin||(/어부|연안/.test(profile?.role||'')?'coast':/수습|전장/.test(profile?.role||'')?'battlefield':/짐꾼/.test(profile?.role||'')?'road':/밀수|항만/.test(profile?.role||'')?'harbor':'city');
  const pool=CONTACT_ARCHETYPES_V30[origin]||CONTACT_ARCHETYPES_V30.city;const out={};
  pool.forEach((x,i)=>{const id=i===0?'mira':i===1?'karon':`contact${i+1}`;out[id]={name:x[0],profession:x[1],status:x[2]+'에서 생활하는 '+x[1],place:x[2],home:x[2],flags:[],kind:x[3],affinity:i<2?ri(12,20):ri(7,15),alive:true,present:true,worldId:`g${state.generation+1}_${id}_${x[0]}`};});
  return out;
}
function evolveNpcWorldV30(){
  ensureV30State();const stamp=absMonth();
  for(const [id,n] of Object.entries(state.contacts||{})){
    if(n.alive===false)continue;const r=stableIncidentRoll(`npc:${stamp}:${n.worldId||id}`);
    n.present=r>.13;
    if(!n.present){n.place='거점 밖';n.status=`${n.profession||'주민'} · 이번 달은 다른 지역에 나가 있다.`;continue;}
    const move=stableIncidentRoll(`npcmove:${stamp}:${n.worldId||id}`);
    if(move<.18&&n.kind==='broker'){n.place='중앙시장';n.status=`${n.profession} · 이번 달은 중앙시장에서 사람을 만난다.`;}
    else if(move<.30&&n.kind==='local'){n.place='중앙광장';n.status=`${n.profession} · 이번 달은 중앙광장에 자주 보인다.`;}
    else{n.place=n.home||n.place;n.status=`${n.profession} · ${n.place}에 있다.`;}
  }
}
const _openContactsV30Base=openContacts;
openContacts=function(){ensureV30State();const visible=Object.entries(state.contacts||{}).filter(([,n])=>n.alive!==false);const pos=['p0','p1','p2','p3','p4','p5'];const homes=visible.map(([id,n],i)=>{const a=clamp(Math.round(Number(n.affinity)||0),0,100),away=n.present===false;return `<button class="npcHome ${pos[i%pos.length]}" data-contact-open="${id}" ${away?'disabled':''}><div class="npcHomeTop"><span class="npcMiniPortrait">${contactAvatarV28(n)}</span><div><b>${n.name}</b><span>${contactPlaceV28(id,n)}<br>${away?'부재':relationStageV28(a)+' · 친밀도 '+a}</span></div></div><div class="affMini"><i style="width:${a}%"></i></div></button>`;}).join('');const map=`<div class="settlementMap"><div class="mapLandmark lodge">숙소</div><div class="mapLandmark temple">신전</div><div class="mapLandmark plaza">중앙 광장</div><div class="mapLandmark market">시장</div><div class="mapLandmark smith">대장간</div><div class="mapLandmark harbor">항구</div><div class="mapWater"></div>${homes}</div>`;openModal(modalHead('방문','거점에 실제로 머무는 인물만 찾아갈 수 있다. 사람은 직업 때문에 자리를 비우거나 다른 장소로 움직인다.')+map);bindClose();document.querySelectorAll('[data-contact-open]').forEach(b=>b.onclick=()=>startVisit(b.dataset.contactOpen));};
function archiveContactsToWorldV30(){
  ensureV30State();for(const [id,n] of Object.entries(state.contacts||{})){const key=n.worldId||`g${state.generation}_${id}_${n.name}`;if(!state.worldPeople.some(x=>x.worldId===key))state.worldPeople.push({...JSON.parse(JSON.stringify(n)),worldId:key,generationMet:state.generation,lastSeen:{year:state.year,month:state.month}});}
}
function chooseSuccessorProfileV30(sc){
  const pool=SUCCESSOR_CONTEXT_V30[sc?.successor]||SUCCESSOR_CONTEXT_V30.wanderer;const used=new Set([state.owner?.name,...(state.pastOwners||[]).slice(-6).map(x=>x.name)]);let rows=pool.filter(x=>!used.has(x.name));if(!rows.length)rows=pool.filter(x=>x.name!==state.owner?.name);return {...choice(rows.length?rows:pool)};
}
function successionGapMonthsV30(sc){return sc?.id==='enemy_spoil'?2:sc?.id==='sea'?1:sc?.id==='road'?1:sc?.id==='battlefield'?1:1;}
function advanceWorldTimeV30(months,reason){
  months=Math.max(1,Math.floor(Number(months)||1));const fromYear=state.year;
  for(let i=0;i<months;i++){state.month++;if(state.month>12){state.month=1;state.year++;state.owner.age=(Number(state.owner.age)||20)+1;}processWorldCallbacks();}
  if(fromYear===1&&state.year>1&&state.firstYear)state.firstYear.summaryShown=true;
  state.worldClock.skippedMonths=(state.worldClock.skippedMonths||0)+months;state.worldClock.lastSuccessionGap=months;
  addWorldFact(`${reason||'시간이 흘렀다'} · ${months}개월 경과`,`worldtime:${absMonth()}:${months}`);
}
function completeDeathSuccession(sc,old,p){
  ensureV30State();archiveContactsToWorldV30();const profile=chooseSuccessorProfileV30(sc),gap=successionGapMonthsV30(sc),legacyTitle=`${old}을 잃고도 남은 검`;
  state.weapon.deathMemories.push({owner:old,title:`${old}의 마지막 순간`,text:`${p?.label||'이름 없는 싸움'}에서 주인을 잃었다. 능력 보상은 없지만 검의 연대기에 영구히 남는다.`});if(!state.weapon.legacyTitles.includes(legacyTitle))state.weapon.legacyTitles.push(legacyTitle);
  addWorldFact(`${old}이 전투에서 죽었다. 검은 ${sc?.title||'주인 없는 시간'}을 거쳐 다음 손으로 넘어갔다.`,`owner_death_${state.generation}_${absMonth()}`);
  resetOwnerAssetsForSuccessor(profile,'전투에서 사망',legacyTitle);advanceWorldTimeV30(gap,`${sc?.title||'주인 없는 시간'} 동안 세계도 멈추지 않았다`);
  evolveNpcWorldV30();state.storyCtx=null;state.activeStory=null;state.policy=null;state.subChoice=null;state.monthCandidateCache={};closeModal();genMonth();addLog(`제${state.generation}대 소유자 ${state.owner.name}이 ${gap}개월 뒤 검을 발견했다.`);saveGame();
}
function yearEndSummaryHtml(){
  ensureV30State();const prof=weaponProfile(),completed=Object.keys(STORY_CATALOG).filter(id=>storyProgress(id).done).map(id=>STORY_CATALOG[id].name),spareCountTotal=Object.values(state.weapon.spareParts||{}).reduce((a,b)=>a+b,0),rows=state.mainStory.act1ChapterResults||[],done=new Set(rows.map(x=>Number(x.chapter))).size,c=currentAct1ChapterV25();
  return `<div class="modalHead"><b>${state.year}년차 연대기 결산</b></div><div class="dialogue"><div class="speaker">Legend Core</div><div class="quote">사람의 해는 끝나도 검의 기록은 이어진다. 이번 해의 선택과 패배도 되감기지 않고 다음 달의 세계에 남는다.</div></div><div class="resultStats"><div class="resultStat">제1장<b>${done}/8 CH</b></div><div class="resultStat">세대<b>제${state.generation}대</b></div><div class="resultStat">Callback<b>${state.firstYear.callbacks.length}</b></div><div class="resultStat">완성 서사<b>${completed.length}</b></div></div><div class="sectionMini">현재 소유자</div><div class="statusHero"><div class="statusCard"><b>${state.owner.name} · Lv.${state.ownerProgress?.level||1}</b><span>HP ${state.hp}/${state.maxHp} · 정신 ${state.mind}/100</span></div><div class="statusCard"><b>${prof.name}</b><span>예비 파츠 ${spareCountTotal}개 · 검의 기록은 세대를 넘어 유지</span></div></div><div class="sectionMini">MAIN</div><div class="dialogue"><div class="quote" style="font-size:9px">${c?`제1장 CH.${c.index} 「${c.title}」 · ${act1ResearchDoneV25(c.index)?'조사 완료':'필수 조사 진행 중'}`:'제1장 8챕터 완료'}</div></div><div class="sectionMini">세계 시간</div><div class="modalDesc">소유권 이전으로 건너뛴 시간 ${state.worldClock.skippedMonths||0}개월 · 과거 인물 ${state.worldPeople.length}명 기록</div><button class="primary" id="startYear2">계속한다</button>`;
}
function auditFrozenRulesV29(){
  ensureV30State();
  // authored MAIN is the only canonical MAIN; legacy gate/chapter result/prototype states cannot reopen old flows.
  state.mainStory.gate=null;state.mainStory.prototypeEnd=false;state.successionDone=false;
  for(const policy of ['contract','explore','investigate','rest'])for(const a of ROUTINE_ACTIONS_V29[policy]||[]){const r=incidentState(a.key);if(['closed','resolved','hidden'].includes(r.status))r.status='active';}
}
