const FATE_STORIES_V32={
 shatter:[
 ['쪼개진 중심석','검이 바위를 받아내는 순간 손잡이 속 작은 핵이 갈라졌다. 주인은 마지막까지 검을 붙잡고 있었으나, 돌빛이 꺼질 때 숨도 멎었다.'],
 ['화염 속의 붕괴','불길이 대피로를 끊었다. 검은 문을 받치며 사람을 내보냈지만 마지막 충격에 칼날과 핵이 함께 부서졌다.'],
 ['파도에 삼켜진 금속','갑판이 기울고 검자루가 난간을 부딪쳤다. 검의 끝이 갈라지면서 중심의 빛도 바닷물 속에 흩어졌다. 주인은 수면 위로 돌아오지 못했다.'],
 ['벽 아래 묻힌 이름','무너진 성벽에서 검으로 돌을 버티려 했지만 압력이 너무 컸다. 손에서 힘이 빠질 때 핵의 잔향도 사라졌다.'],
 ['마지막 맞부딪침','적의 무기가 검의 중심을 정확히 때렸다. 살아남기 위한 마지막 반격은 성공하지 못했고 조각난 Core는 누구도 다시 잇지 못했다.']
 ],
 lost:[
 ['빗속에 버려진 검','주인이 쓰러진 뒤 검은 시체 곁에 남았다. 몇 해가 지나도록 비와 흙이 금속을 덮었고 끝내 주인의 이름과 함께 잊혔다.'],
 ['도시 장물시장의 밤','검은 여러 손을 거쳤으나 누구도 오래 품지 않았다. 값어치를 모르는 거래와 도난 끝에 행방이 끊겼다.'],
 ['바다를 떠도는 검집','주인은 파도 아래 사라졌다. 검은 부유물 사이를 따라 흘렀고 어느 해안에도 오랫동안 닿지 못했다.'],
 ['땅속의 침묵','전장 수습꾼이 검을 거두지 못했다. 후대의 길이 그 위에 깔렸고 Core의 기억은 돌 밑에 갇혔다.'],
 ['주인 없는 화물','밀폐된 상자에 담긴 검은 항구에서 항구로 옮겨졌다. 장부도 소유자도 사라져 더 이상 사람의 손에 닿지 않았다.']
 ],
 inherit:[
 ['유언을 따소유자 사람','주인의 마지막 부탁을 들은 동료가 검을 거두었다. 흠집은 남았어도 어떤 부품도 사라지지 않았다.'],
 ['새벽에 발견된 검','시신을 찾아온 장례 일꾼이 검을 조심히 들어 올렸다. 이름을 알지 못했지만 다른 이에게 넘길 때까지 온전히 보관했다.'],
 ['부두에서 건넨 물건','어부가 파도에 걸린 검집을 건졌다. 마을의 젊은 사람에게 전달되는 동안 가드와 칼날은 원래 자리를 지켰다.'],
 ['닫힌 상자의 열쇠','오래된 지인이 검을 잠긴 상자에 넣었다. 이듬달 상자를 연 사람이 새로운 주인이 되었고 어떤 파츠도 바뀌지 않았다.'],
 ['위험을 이어받는 사람','살아남은 동료가 마지막 싸움을 기록했다. 그 기록을 읽은 후계자가 검을 거두며 새로운 장이 시작되었다.']
 ],
 escape:[
 ['좁은 골목의 퇴각','주인은 승산이 없음을 깨닫고 미끄러운 골목으로 몸을 던졌다. 쫓아오는 발소리가 멀어질 때까지 검을 놓지 않았다.'],
 ['누군가의 구조','먼저 물러났던 동료가 다시 돌아와 주인의 팔을 잡았다. 검과 사람은 둘 다 들것 위에 실려 빠져나왔다.'],
 ['폭우가 가린 발자국','갑작스러운 소나기가 추격을 끊었다. 주인은 쓰러지듯 숨을 고르며 검의 균열부터 살폈다. 핵은 무사했다.'],
 ['문 하나의 거리','무너진 문짝을 세우고 간신히 몸을 뺐다. 상대는 더 쫓지 못했고 주인은 뒤돌아보지 않고 안전한 곳까지 걸었다.'],
 ['목숨을 건 양보','승부를 끝내지 않고 가진 보급 일부를 내주었다. 적은 길을 열었고 주인과 검은 다른 기회를 찾아 떠났다.']
 ]
};
function drawDefeatFateV32(){const roll=ri(1,100);return roll<=10?'shatter':roll<=30?'lost':roll<=60?'inherit':'escape';}
function resolveBattleDefeatV32(p){
 const fate=drawDefeatFateV32();
 if(fate==='escape'){
  state.hp=Math.max(1,Math.round(state.maxHp*.22));state.mind=clamp(state.mind-4,0,100);
  ensureAilmentsV34().injury=true;
  if(String(p?.enemy||'').includes('spider'))ensureAilmentsV34().poison=true;
  addLog('전투 패배 후 생존: 지속 부상 (생존 -2)'+(state.ailmentsV34.poison?' · 중독':''));
  showDefeatFateV32(fate,p);return;
}
 state.hp=0;beginOwnerDeathTransition({...p,v32Fate:fate});
}
function showDefeatFateV32(fate,p){
 const kind=DEATH_FATES_V32.find(x=>x.id===fate),sample=choice(FATE_STORIES_V32[fate]),old=state.owner.name;
 const paragraph=`${old} — ${sample[1]}`;
 if(fate==='escape'){
   state.lastFate={fate,title:sample[0],year:state.year,month:state.month,generation:state.generation};
   addWorldFact(`${old}은 ${sample[0]} 이후 생존했다.`,`fate:${absMonth()}:${Math.random()}`);
   openModal(`<div class="modalHead"><b>${kind.title}</b></div><div class="storyScene"><div class="storyTitle">${sample[0]}</div><div class="storyText">${paragraph}</div></div><div class="modalDesc">체력이 낮은 상태로 살아남았다. 이번 전투는 패배로 기록된다.</div><button id="fateGo32" class="primary">패배의 후속 사건으로</button>`);
   $('fateGo32').onclick=()=>showStoryNode(p.nextLose);saveGame();return;
 }
 if(state.policy==='sail'){const ch=currentAct1ChapterV25();if(ch&&!state.mainStory.flags[`act1_ch${ch.index}_complete`])resolveMainDefeatV29(ch.index,true);}
 if(fate==='inherit'){
   state.lastFate={fate,title:sample[0],year:state.year,month:state.month,generation:state.generation};
   openModal(`<div class="modalHead"><b>${kind.title}</b></div><div class="storyScene"><div class="storyTitle">${sample[0]}</div><div class="storyText">${paragraph}</div></div><div class="modalDesc">검 파츠·각인·검의 서사는 그대로 보존된다. 새 소유자의 능력치와 방어구는 주사위 추첨으로 정해진다.</div><button id="fateGo32" class="primary">새 소유자에게 계승</button>`);
   $('fateGo32').onclick=()=>completeDeathSuccession({id:'succession_intact',title:sample[0],successor:chooseDeathScenario(p)?.successor||'wanderer'},old,p);
   saveGame();return;
 }
 if(fate==='shatter')state.weapon.dur=0;
 state.gameOver={type:fate,title:sample[0],text:paragraph,year:state.year,month:state.month,generation:state.generation};
 archiveContactsToWorldV30();archiveCurrentOwner(fate==='shatter'?'검 완전 파괴':'검 유랑 · 단절',sample[0]);
 state.storyCtx=null;state.activeStory=null;state.policy=null;state.subChoice=null;
 saveGame();showGameOverV32();
}
function showGameOverV32(){const o=state.gameOver;if(!o)return;
 openModal(`<div class="modalHead"><b>GAME OVER · ${o.type==='shatter'?'검 파괴':'검의 행방 단절'}</b></div><div class="storyScene"><div class="storyTitle">${o.title}</div><div class="storyText">${o.text}</div></div><div class="modalDesc">제${o.generation}대 · ${o.year}년차 ${o.month}월. 이번 연대기는 여기서 끝난다. 다시 시작하면 저장된 진행은 초기화된다.</div><button class="primary" id="v32Restart">새 연대기 시작</button>`);
 $('v32Restart').onclick=openRestartConfirm;
}
beginOwnerDeathTransition=function(p){
 const fate=p?.v32Fate||drawDefeatFateV32();
 if(fate==='escape'){state.hp=Math.max(1,Math.round(state.maxHp*.22));showDefeatFateV32('escape',p);return;}
 showDefeatFateV32(fate,p);
};
const _successionV32=completeDeathSuccession;
function rollSuccessorStatV32(){const r=ri(1,100);return r<=57?ri(2,5):r<=85?ri(6,8):r<=97?ri(9,11):ri(12,14);}
completeDeathSuccession=function(sc,old,p){
 _successionV32(sc,old,p);
 // The new owner does not inherit the old owner's armor and inventory; randomized dice stock.
 state.owner.martial=rollSuccessorStatV32();state.owner.survival=rollSuccessorStatV32();state.owner.social=rollSuccessorStatV32();
 state.owner.aggression=ri(20,85);state.owner.caution=ri(20,85);state.owner.boldness=ri(20,85);
 const ownItems=[];
 for(const slot of Object.keys(OWNER_GEAR_SLOTS)){
   if(ri(1,100)>78)continue;
   const rarity=v32RarityDraw(),pool=Object.entries(OWNER_GEAR_CATALOG).filter(([,g])=>g.slot===slot&&g.rarity===rarity);
   const fallback=Object.entries(OWNER_GEAR_CATALOG).filter(([,g])=>g.slot===slot&&g.rarity==='common');
   const id=choice(pool.length?pool:fallback)?.[0];if(id){state.ownerGearOwned[id]=1;state.ownerEquipment[slot]=id;ownItems.push(id);}
 }
 syncOwnerVitalCaps(false);state.hp=Math.round(state.maxHp*.88);state.mind=clamp(state.mind,0,100);
 state.lastSuccessionRoll={martial:state.owner.martial,survival:state.owner.survival,social:state.owner.social,armor:ownItems.map(id=>OWNER_GEAR_CATALOG[id].name)};
 addLog(`계승자 주사위 · 무예 ${state.owner.martial} / 생존 ${state.owner.survival} / 처세 ${state.owner.social} / 방어구 ${ownItems.length}개`);
 saveGame();render();
};
const _executeMonthV32=executeMonth;
executeMonth=function(){if(state.gameOver)return showGameOverV32();return _executeMonthV32();};
const _loadGameV32=loadGame;
loadGame=function(){const ok=_loadGameV32();if(state.gameOver)queueMicrotask(showGameOverV32);return ok;};
const _loadBetaStockV32=loadGame;
loadGame=function(){const ok=_loadBetaStockV32();if(!state.betaInventoryV32){state.betaInventoryV32=true;resetMarketStock();saveGame();}return ok;};
const _resetMarketV32=resetMarketStock;
resetMarketStock=function(){_resetMarketV32();if(V32_BETA){state.smithPartStock=generateSmithPartStockV24();state.marketV24.armor=randomGearStock();}};


// ==================== v3.3 canonical storytelling / rest / gear visual ====================
const RARITY_LABEL_33={common:'일반',rare:'레어',unique:'유니크',legendary:'레전더리',beyond:'레전더리+'};
gearBoardHtml=function(){ensureV24State();return `<div class="ownerGearBoard">${Object.entries(OWNER_GEAR_SLOTS).map(([slot,label])=>{
 const id=state.ownerEquipment[slot],it=id&&OWNER_GEAR_CATALOG[id],rarity=it?.rarity||'common';
 return `<button class="ownerGearSlot rarity-${rarity}" data-owner-slot="${slot}" aria-label="${label} ${it?it.name:'비어 있음'}">
 <b>${label}</b><span class="gearIcon33" aria-hidden="true">${v32Icon(id,'armor')||'◇'}</span>
 <span>${it?it.name:'비어 있음'}</span>${it?`<small class="gearGrade33">${RARITY_LABEL_33[rarity]}</small>`:''}</button>`;}).join('')}</div>`;};

