function restQuiet33(){state.storyCtx.skipIntegratedResolution=true;}
function restRecover33(){
 const ctx=state.storyCtx;restQuiet33();const hp=Math.max(0,Math.min(25,state.maxHp-state.hp)),mind=Math.max(0,Math.min(20,100-state.mind));
 state.hp+=hp;state.mind+=mind;ctx.notes.push(`완전휴식 회복 · HP +${hp}, 정신 +${mind}`);
 return openStoryScene('숙소','쉬는 것도 결정이었다',`${state.owner.name}은 일감이 들어와도 받지 않았다. 첫날에는 몸이 오히려 아팠고, 둘째 날에는 오래 참아 온 피로가 밀려왔다. 며칠이 지나자 비로소 잠이 깊어졌다.\n\n문밖에서는 이번 주의 소란이 지나갔다. 아무것도 얻지 못한 것이 아니라, 다음에 움직일 힘을 되찾았다.`,[{label:'휴식을 끝내고 다음 달을 맞는다',next:'END',outcome:'완전휴식 · 체력과 정신 회복'}]);
}
function restAffinity33(id,rare=false){
 const n=state.contacts[id];if(!n)return;let gain=grantRegularAffinityV28(id);
 if(rare){n.affinity=clamp((n.affinity||0)+3,0,100);gain+=3;state.v33RareUsed||={};state.v33RareUsed[n.worldId||id]=true;}
 state.storyCtx.notes.push(`${n.name} 친밀도 +${gain}${rare?' · 희귀 관계 사건 완료':''}`);
 addLog(`${n.name}과 함께 시간을 보냈다 · 친밀도 +${gain}`);
 recordDeed('social',`${v28MonthKey()}:rest33:${id}`);
}
function showRest33(node,key){
 const c=state.storyCtx;if(!c)return; c.currentNode=node;
 if(key==='routine_rest_recovery'){
  if(node==='start')return openStoryScene('숙소','완전휴식',`${state.owner.name}은 이번 달 의뢰를 거절하고 검을 벽에 세웠다. 피로가 남아 있는데 다음 일을 받으면 사람과 검 중 하나가 먼저 무너질 것 같았다.`,[
   {label:'완전히 쉬며 회복한다 (HP 최대 +25 · 정신 최대 +20)',next:'rest_recover'}
   ]);
  if(node==='rest_recover')return restRecover33();
 }
 if(key==='routine_rest_walk'){
  if(node==='start'){
   const scene=choice(WALK_ENCOUNTERS_33);c.v33Walk=scene;
   return openStoryScene(scene.where,'우연히 마주친 일',`${state.owner.name}은 특별한 목적 없이 거리를 거닐었다. 그러다 ${scene.where}에서 발길이 멈췄다.\n\n${scene.intro}`, [
    {label:'무슨 일인지 가까이 가서 살펴본다',next:'rest_walk_turn'},
    {label:'오늘은 쉬기로 했으니 지나간다',effect:()=>{restQuiet33();state.mind=clamp(state.mind+3,0,100);},next:'rest_walk_pass'}]);
  }
  if(node==='rest_walk_pass')return openStoryScene('거리','외면한 사건도 흔적을 남긴다','그 자리를 떠나자 뒤에서 누군가 다시 도움을 청했다. 돌아보지 않았다. 오후에 숙소로 돌아와서도 그 소리는 잠시 귓가에 남았다. 오늘은 아무것도 해결하지 않았지만, 자신이 선택한 쉬는 시간을 지켰다.',[{label:'다음 달로',next:'END',outcome:'거리 산책 · 사건에 개입하지 않음'}]);
  if(node==='rest_walk_turn'){
   const e=c.v33Walk;
   return openStoryScene(e.where,'예상 밖의 진실',e.turn,[
    {label:'눈앞의 문제를 직접 처리한다',effect:()=>{restQuiet33();c.v33RestMode='normal';},next:'routine_result'},
    {label:'말로 풀어 해결한다 · 설전',effect:()=>{restQuiet33();c.v33RestMode='debate';},next:'rest_debate'},
    ...(e.type==='combat'?[{label:'위협을 무력으로 막는다 · 실전 전투',effect:()=>{restQuiet33();c.v33RestMode='combat';},combat:{enemy:'bandit',label:e.where+' 습격',win:'routine_result',lose:'routine_result',mods:{v32SideEncounter:true}}}]:[])
   ]);
  }
  if(node==='rest_debate')return startDebateV32(`${c.v33Walk.where} · 길 위의 설전`);
  if(node==='routine_result'){
   const e=c.v33Walk;restQuiet33();const win=c.v33RestMode==='debate'?c.debateWin:c.v33RestMode==='combat'?c.v32EncounterWin:ri(1,100)<=(50+effectiveOwnerStats().survival*3);
   if(win){c.notes.push('거리 사건 해결 · 생활 경험');state.mind=clamp(state.mind+4,0,100);}else{c.notes.push('거리 사건의 여파 · 정신 -4');state.mind=clamp(state.mind-4,0,100);}
   return openStoryScene(e.where,win?'우연한 일의 매듭':'남은 문제',win?e.clear:e.lose,[{label:'거리를 떠나 다음 달로',next:'END',outcome:win?'거리 인카운트 · 해결':'거리 인카운트 · 미해결'}]);
  }
 }
 if(key==='routine_rest_companion'){
  if(node==='start'){
   const people=Object.entries(state.contacts||{}).filter(([,n])=>n.alive!==false&&n.present!==false);
   const choices=people.map(([id,n])=>({label:`${n.name} · ${n.profession||n.status} (친밀도 ${n.affinity||0})`,effect:ctx=>{ctx.v33Friend=id;},next:'rest_friend_meet'}));
   if(!choices.length)return openStoryScene('거점','오늘은 만날 사람이 없다','찾아가려던 사람들은 모두 거점 밖에서 일하고 있었다. 기다릴까 고민하다가 숙소로 돌아와 집 앞을 쓸었다. 아무도 만나지 못했지만, 억지로 찾으러 나서지 않기로 했다.',[{label:'돌아와 조용히 쉰다',effect:()=>{restQuiet33();state.mind=clamp(state.mind+5,0,100);},next:'rest_friend_absent'}]);
   return openStoryScene('거점 · 주변 인물','누구와 시간을 보낼까',`${state.owner.name}은 혼자 쉬는 대신 누군가의 문을 두드리기로 했다. 이달 거점에 실제로 머무는 사람 중 한 사람을 고를 수 있었다.`,choices);
  }
  if(node==='rest_friend_absent')return openStoryScene('숙소','조용한 오후','돌아온 뒤 잠시 눈을 감자 거리의 소음이 희미해졌다. 만나지 못한 사람에게는 다음 달에도 기회가 있을 것이다.',[{label:'다음 달로',next:'END',outcome:'동료 방문 · 부재'}]);
  const id=c.v33Friend,n=state.contacts?.[id];if(!n)return showRest33('rest_friend_absent',key);
  if(node==='rest_friend_meet'){
   const rareType=/약초|치료|의무/.test((n.profession||'')+' '+(n.status||''))?'healer':/목수|수선|대장|장인/.test((n.profession||'')+' '+(n.status||''))?'craft':(id==='karon'||n.kind==='broker'||/중개|상단|거래/.test((n.profession||'')+' '+(n.status||'')))?'broker':'local',route=COMPANION_RARE_33[rareType],saved=state.v33RareUsed?.[n.worldId||id];
   const eligible=(n.affinity||0)>=25&&!saved;
   c.v33FriendRare=!!(eligible&&ri(1,100)<=(n.affinity>=55?32:18));c.v33FriendPlot=route;
   return openStoryScene(`${n.name}의 ${n.home||'거처'}`,'일 대신 함께한 시간',`${n.name}은 손님인 ${state.owner.name}에게 자리를 내주었다. 최근에 있었던 일과 자잘한 집안일을 이야기하는 동안, 서로에 대해 알고 있다고 생각했던 사실 몇 가지가 달랐다.\n\n${c.v33FriendRare?route.intro:'함께 상을 치우고 문밖의 소란을 들었다. 예전에는 일 이야기만 하던 사이였다면 이제는 아무 말 없이 앉아 있어도 어색하지 않았다.'}`,c.v33FriendRare?[
     {label:'낯선 사건의 사정을 더 듣는다 · 희귀 관계 사건',next:'rest_friend_rare_turn'},
     {label:'오늘만큼은 사건에 관여하지 않는다',next:'rest_friend_bond'}]:[
     {label:'같이 시간을 보내며 가까워진다',next:'rest_friend_bond'},
     {label:'주변 일을 조금 거든다',next:'rest_friend_bond'}]);
  }
  if(node==='rest_friend_bond'){
   restQuiet33();restAffinity33(id,false);state.mind=clamp(state.mind+4,0,100);
   return openStoryScene(`${n.name}의 집`,'일상으로 쌓인 관계',`해가 내려앉을 때 ${n.name}은 다음에 오면 가져갈 물건이 있다며 웃었다. 새로운 정보나 보상은 없었다. 하지만 문을 열어 주는 사이가 되었다는 사실은 변하지 않았다.`,[{label:'인사를 나누고 돌아간다',next:'END',outcome:`${n.name}과 함께한 휴식 · 친밀도 상승`}]);
  }
  if(node==='rest_friend_rare_turn'){
   const e=c.v33FriendPlot;
   return openStoryScene(`${n.name}의 집`,e.name,e.turn,[
     {label:'차분히 증거를 모아 돕는다',effect:()=>{restQuiet33();c.v33RestMode='normal';},next:'rest_friend_rare_result'},
     {label:'관련된 사람을 설득한다 · 설전',effect:()=>{restQuiet33();c.v33RestMode='debate';},next:'rest_debate'}]);
  }
  if(node==='rest_debate')return startDebateV32(`${n.name}의 ${c.v33FriendPlot?.name||'사건'} · 설전`);
  if(node==='routine_result'||node==='rest_friend_rare_result'){
   restQuiet33();const win=c.v33RestMode==='debate'?!!c.debateWin:ri(1,100)<=(53+effectiveOwnerStats().social*3);
   if(win){restAffinity33(id,true);state.mind=clamp(state.mind+4,0,100);}
   else{restAffinity33(id,false);c.notes.push('희귀 관계 사건은 아직 미해결');}
   return openStoryScene(`${n.name}의 집`,win?'숨기던 이야기가 열리다':'남겨 둔 약속',win?c.v33FriendPlot.clear:c.v33FriendPlot.lose,[{label:'다음 달로 · 관계를 기록한다',next:'END',outcome:`${n.name} 희귀 사건 · ${win?'해결':'미해결'}`}]);
  }
 }
 return openStoryScene('휴식','돌아가는 길','오늘은 그만 돌아갈 시간이었다.',[{label:'다음 달',next:'END',outcome:'휴식 종료'}]);
}

const _successionV34=completeDeathSuccession;
completeDeathSuccession=function(...args){const out=_successionV34(...args);state.ailmentsV34={injury:false,poison:false};saveGame();return out;};


