const OD36_BY_KEY=Object.fromEntries(OD36_ROWS.map(x=>[x.key,x]));
const OD36_PHASE={1:[1,1],2:[2,3],3:[2,3],4:[4,5],5:[4,5],6:[6,8],7:[6,8],8:[6,8]};
for(const ep of OD36_ROWS){
 const typeName={contract:'의뢰',explore:'탐험',investigate:'조사'}[ep.policy];
 const a={key:ep.key,route:ep.key,title:ep.title,desc:ep.premise,difficulty:Math.min(4,1+Math.floor((ep.ch-1)/2)),reward:Math.min(4,1+Math.floor((ep.ch-1)/2)),rewardText:`${ep.stake} · ${typeName} 성과`,phase:'routine'};
 ACTION_OPTIONS[ep.policy].push(a);
 WORLD_INCIDENTS[ep.key]={policy:ep.policy,region:ep.ch===1?'home':ep.ch<=3?'harbor':ep.ch<=5?'coast':'mine',kind:'routine'};
}
function od36CurrentChapter(){ensureV25MainState();return Math.max(1,Math.min(8,Number(state.mainStory?.chapter||currentAct1ChapterV25()?.index||1)));}
function od36Accessible(ep){let ch=od36CurrentChapter(),range=OD36_PHASE[ep.ch];return ch>=range[0]&&ch<=range[1];}
const _actionCandidates36=actionCandidatesForPolicy;
actionCandidatesForPolicy=function(policy,rebuild=false){
 const prev=_actionCandidates36(policy,rebuild);
 if(!['contract','explore','investigate'].includes(policy))return prev;
 ensureWorldEngine();
 const now=absMonth(),ch=od36CurrentChapter(),pool=OD36_ROWS.filter(ep=>ep.policy===policy&&od36Accessible(ep)).filter(ep=>routineAvailableV29(actionDefByKey(ep.key)));
 // Prefer unplayed scenes and different underlying premises; keep the MAIN research on the board.
 pool.sort((a,b)=>{
  const ar=state.worldIncidents[a.key],br=state.worldIncidents[b.key];
  const ac=Number(ar?.cycles||0),bc=Number(br?.cycles||0);
  const ah=Math.min(...[0,1,2].map(v=>state.worldIncidents[a.key.slice(0,-1)+(v+1)]?.completedAt??-999));
  const bh=Math.min(...[0,1,2].map(v=>state.worldIncidents[b.key.slice(0,-1)+(v+1)]?.completedAt??-999));
  if(ac!==bc)return ac-bc;
  if(ah!==bh)return ah-bh;
  return stableIncidentRoll(`${now}:${ch}:${a.key}`)-stableIncidentRoll(`${now}:${ch}:${b.key}`);
 });
 const fresh=[];const premises=new Set();
 for(const ep of pool){let stem=ep.key.slice(0,-2);if(premises.has(stem))continue;premises.add(stem);fresh.push({...actionDefByKey(ep.key),reward:candidateWorldDifficulty(actionDefByKey(ep.key))});if(fresh.length>=2)break;}
 if(!fresh.length)return prev;
 const pinned=prev.filter(a=>/^act1_research_/.test(a.key));
 const prevOther=prev.filter(a=>!pinned.some(x=>x.key===a.key));
 const picks=[];const usedKeys=new Set();
 for(const x of [...pinned,...fresh,...prevOther]){if(!x||usedKeys.has(x.key))continue;picks.push(x);usedKeys.add(x.key);if(picks.length===4)break;}
 state.monthCandidateCache={...(state.monthCandidateCache||{}),stamp:`${state.year}-${state.month}`,[policy]:picks.map(a=>a.key)};
 return picks;
};
const _showStoryNode36=showStoryNode;
showStoryNode=function(node){
 const ep=OD36_BY_KEY[String(state.subChoice||'')];
 if(ep)return od36ShowStory(node,ep);
 return _showStoryNode36(node);
};
function krParticle36(word,yes,no){const ch=String(word||'').slice(-1),v=ch.charCodeAt(0);if(v>=0xAC00&&v<=0xD7A3)return (v-0xAC00)%28===0?no:yes;return no;}
function od36Record(ep,grade,mode){
 state.od36Chronicle=Array.isArray(state.od36Chronicle)?state.od36Chronicle:[];
 state.od36Chronicle.push({key:ep.key,grade,mode,year:state.year,month:state.month,owner:state.owner?.name||''});
 if(state.od36Chronicle.length>120)state.od36Chronicle=state.od36Chronicle.slice(-120);
}
function od36ShowStory(node,ep){
 const c=state.storyCtx;if(!c)return; c.currentNode=node;
 const hero=state.owner.name,place=ep.place,actor=ep.person;
 if(node==='start'){
  const note=(state.od36Chronicle||[]).find(x=>x.key===ep.key);
  return openStoryScene(`${place} · 제1장 CH.${ep.ch}` ,ep.title,
    `${hero}이 ${place}에 도착했을 때는 이미 사람들 사이에 작은 다툼이 번져 있었다. ${ep.premise}.\n\n${actor}${krParticle36(actor,'이','가')} 낡은 종이와 손때 묻은 물건을 들고 다가왔다. 보상으로 제시한 것은 단순한 금전만이 아니었다. ${ep.stake}${krParticle36(ep.stake,'이','가')} 이번 일에 달려 있었다.\n\n${note?'이곳에는 지난번 선택의 소문이 아직 남아 있었다. 사람들은 검을 알아보고는 쉽게 말을 꺼내지 않았다.':'바다는 멀리서 잔잔해 보였지만, 전쟁 뒤의 귀향길에서 사람의 약속은 언제나 파도보다 먼저 깨졌다.'}`,
    [
      {label:'실물과 현장의 흔적을 먼저 살핀다',effect:x=>{x.od36Path='trace';x.lastApproach='survival';},next:'od36_evidence'},
      {label:`${actor}${krParticle36(actor,'과','와')} 관련자들의 진술을 맞춰본다`,effect:x=>{x.od36Path='witness';x.lastApproach='social';},next:'od36_evidence'}
    ]);
 }
 if(node==='od36_evidence'){
  const trace=c.od36Path==='trace';
  const intro=trace?`${hero}은 돌의 이음새와 발자국, 물건의 사용 흔적을 차례로 짚었다. 종이보다 현장이 먼저 말을 걸었다.`:`${hero}은 서둘러 결론을 내리지 않았다. ${actor}${krParticle36(actor,'과','와')} 말을 섞으며 누구의 진술이 먼저 바뀌었는지 기억했다.`;
  return openStoryScene(place,trace?'말없는 증거':'엇갈린 증언',
     `${intro}\n\n${ep.clue}. 가까이서 확인하지 않았다면 누구나 지나쳤을 흔적이었다. 그러나 흔적을 이해하는 것과 진실을 밝히는 것은 달랐다.\n\n그때 ${actor}의 눈빛이 바뀌었다. 누군가가 다가왔고, 당초 의뢰에는 없던 조건이 붙었다.`,
     [
      {label:'위험을 감수하고 더 가까이 확인한다',effect:x=>{x.lastApproach='survival';x.od36Detail='risk';},next:'od36_twist'},
      {label:'당사자들을 같은 자리에 모아 대조한다',effect:x=>{x.lastApproach='social';x.od36Detail='people';},next:'od36_twist'}
     ]);
 }
 if(node==='od36_twist'){
  const detail=c.od36Detail==='risk'?'직접 다가간 순간 옆에서 조용히 기다리던 사람들이 움직였다.':'말을 맞춰 보려는 순간 누군가 먼저 입을 열었다.';
  return openStoryScene(place,'진상이 뒤집히다',
    `${detail} ${ep.twist}.\n\n${ep.reversal}. ${hero}은 눈앞의 충돌이 단순한 약탈이나 실수 때문만은 아니라는 것을 깨달았다. 처음 들었던 의뢰대로 처리하면 ${ep.stake}까지 잃을 수 있었다.\n\n${actor}은 대답을 기다리고 있었다. 검을 뽑으면 길은 짧아지지만 상처가 남을 수 있다. 말로 풀면 상대가 거짓말할 시간을 번다. 다른 길을 찾으면 위험은 줄지만 확실한 보상도 놓칠 수 있었다.`,
    [
      {label:'위협하는 상대를 막는다 · 실전 전투',effect:x=>{x.od36Mode='combat';x.lastApproach='martial';},combat:{enemy:ep.ch>=6?'spider':'bandit',label:ep.title+' · 격돌',win:'od36_result',lose:'od36_result',mods:{v32SideEncounter:true}}},
      {label:`${actor}${krParticle36(actor,'과','와')} 책임을 따진다 · 설전`,effect:x=>{x.od36Mode='debate';x.lastApproach='social';},next:'od36_debate'},
      {label:'증거와 퇴로를 확보해 비무력으로 해결한다',effect:x=>{x.od36Mode='normal';x.lastApproach=x.od36Path==='witness'?'social':'survival';},next:'od36_result'}
    ]);
 }
 if(node==='od36_debate')return startDebateV32(`${ep.title} · ${actor} 설전`);
 if(node==='od36_result'){
  if(c.od36Mode==='debate'&&!c.debateResolved)return startDebateV32(`${ep.title} · ${actor} 설전`);
  if(c.od36Mode==='combat'&&c.v32EncounterWin===undefined)return openStoryScene(place,'아직 끝나지 않은 대치','사람들이 서로를 노려보았다. 먼저 결론을 내릴 수는 없었다.',[{label:'승패를 확인한다',next:'od36_twist'}]);
  const resolved=(c.od36Mode==='combat'&&c.v32EncounterWin!==undefined)||(c.od36Mode==='debate'&&c.debateResolved);
  let forced=resolved?((c.od36Mode==='combat'?c.v32EncounterWin:c.debateWin)?'strong':'setback'):null;
  if(forced&&!c.v27Resolution){
    applyResolutionConsequencesV27(ep.policy,forced,c.difficulty||1,c);
    c.v27Resolution={grade:forced,outcomeLabel:ep.title+' · '+(forced==='strong'?'대결 승리':'대결 패배'),narrative:ep.title+' · '+(forced==='strong'?'대결을 승리로 끝냈다.':'대결에서 밀려났다.')};
  }
  let result=resolveIntegratedEventOutcomeV27(ep.policy,c.difficulty||1,c,'진실이 드러난 뒤 일행은 결말을 감당했다.');
  let grade=result?.grade||'steady';
  if(!c.od36Paid){
    const t=clamp(Number(c.difficulty)||1,1,4);
    if(ep.policy==='contract'&&grade!=='setback'){
      const pay=grade==='costly'?Math.max(2,Math.round((3+t*3)/2)):3+t*3;
      state.gold+=pay;c.notes.push(`의뢰 기본 보수 +${pay}G`);
    }
    if(ep.policy==='explore'&&grade!=='setback'){
      const mat=t>=4?'steel':t>=3?'bronze':'iron';
      state.weapon.materials[mat]=(state.weapon.materials[mat]||0)+1;c.notes.push(`${MATERIAL_LABELS[mat]||mat} +1`);
    }
    c.od36Paid=true;
  }
  const modeName=c.od36Mode==='combat'?'싸움':c.od36Mode==='debate'?'설전':'증거 확보';
  const endings={
    strong:`${hero}은 처음부터 의심했던 흔적을 다시 꺼냈다. ${ep.clue}. ${actor}도 더는 반박하지 못했다. ${ep.resolution}.\n\n누가 왜 거짓말을 했는지가 밝혀지자 다툼은 멈췄다. ${ep.stake}${krParticle36(ep.stake,'은','는')} 지켰지만 서로의 얼굴을 잊을 수는 없었다. ${hero}은 떠나기 전 사실을 기록하고 사람들의 이름을 한 번 더 확인했다.`,
    steady:`문제의 가장 위험한 부분은 막았다. ${ep.twist}. 하지만 ${ep.reversal}. 다만 그 사실은 끝까지 모두에게 알려지지 않았다.\n\n${actor}${krParticle36(actor,'은','는')} 남은 일을 스스로 처리하겠다고 약속했다. ${hero}은 ${ep.stake}의 일부를 지킨 뒤, 다음 배가 오기 전까지 필요한 경계와 사람 이름을 적어두었다.`,
    costly:`${hero}은 ${ep.twist}. 그 소동은 막아 냈지만 그 과정에서 약속된 물자와 시간을 소모했다. ${ep.reversal}.\n\n${actor}${krParticle36(actor,'은','는')} 겨우 사람들을 수습했다. ${ep.stake}${krParticle36(ep.stake,'을','를')} 완전히 지킬 수는 없었지만 적어도 잘못된 소문만큼은 바로잡았다. 남은 비용은 선단과 주민이 나누어 짊어졌다.`,
    setback:`대치를 풀기 전에 ${ep.twist}. ${actor}${krParticle36(actor,'은','는')} 흩어진 사람들을 따라 달려갔지만 이미 늦었다. ${ep.reversal}.\n\n${ep.stake}${krParticle36(ep.stake,'은','는')} 위험에 남았고, ${hero}은 더 큰 피해를 막기 위해 철수를 선택했다. 막을 수 있었던 오해가 다음 항구까지 전해질 것이라는 사실만은 분명했다.`
  };
  const title={strong:'약속의 값',steady:'남은 책임',costly:'지불한 대가',setback:'끊어진 실마리'}[grade];
  c.notes.push(`${ep.title} · ${modeName} · ${title}`);
  if(grade==='strong'||grade==='steady'){
    addWorldFact(`${ep.place}에서 ${ep.title} 사건이 해결되어 ${ep.stake}에 관한 소문이 바뀌었다.`,`od36:${ep.key}:${absMonth()}`);
  } else if(grade==='setback'){
    addWorldFact(`${ep.place}의 ${ep.stake} 문제가 아직 남아 있다.`,`od36:unfinished:${ep.key}:${absMonth()}`);
  }
  od36Record(ep,grade,c.od36Mode||'normal');
  return openStoryScene(place,title,endings[grade],[{label:'결과를 기록하고 다음 달로',next:'END',outcome:`${ep.title} · ${grade==='setback'?'실패 · ':''}${title}`}]);
 }
 return _showStoryNode36(node);
}


// ===== v3.7 roundtable: fullscreen chapter scenes, legible cutscenes, reliable MAIN research, earned branches =====
const V37_CINEMATICS = {"scene_contract": "data:image/webp;base64,", "scene_explore": "data:image/webp;base64,", "scene_investigate": "data:image/webp;base64,", "scene_rest": "data:image/webp;base64,"};
const _openModalV37Base=openModal;
openModal=function(markup){
  _openModalV37Base(markup);
  const isResult=/id=["']nextMonth["']/.test(String(markup||''));
  $('overlay')?.classList.toggle('storyFullscreen',isResult);
};
const _closeModalV37Base=closeModal;
closeModal=function(){_closeModalV37Base();$('overlay')?.classList.remove('storyFullscreen');};
function v37UnlockOptions(choices){
  const ctx=state.storyCtx,mode=state.policy;
  if(!ctx||!Array.isArray(choices)||choices.length<2||!['contract','explore','investigate','rest','sail'].includes(mode))return [];
  const node=String(ctx.currentNode||'');
  if(!['start','v25_research_follow','od36_evidence','od36_twist','routine_turn','routine_choice','rest_friend_start','rest_walk_start'].includes(node))return [];
  const usable=choices.filter(c=>c.next&&c.next!=='END'&&!c.combat);
  if(!usable.length)return [];
  const raw=rawOwnerStats(),relations=Object.values(state.contacts||{}).filter(n=>n?.alive!==false&&Number(n.affinity||0)>=30),
    rep=Number(state.ownerProgress?.reputation||0),deeds=Object.values(state.owner?.deeds||{}).reduce((n,a)=>n+(Array.isArray(a)?a.length:0),0),
    history=Number((state.mainStory?.act1ChapterResults||[]).length);
  const safe=(raw.survival||0),social=(raw.social||0),martial=(raw.martial||0),out=[];
  const add=(label,base,narrative,kind)=>{if(!base)return;out.push({label,unlockV37:true,next:base.next,effect:x=>{
    if(base.effect)base.effect(x);
    x.v37Advantage=Number(x.v37Advantage||0)+1;
    x.v37SpecialPath=kind;
    x.v37SceneNote=narrative;
    x.notes=x.notes||[];x.notes.push(`조건부 해결: ${label.replace(/^\[[^\]]+\]\s*/, '')}`);
    if(kind==='relation') x.v37RelationUsed=relations[0]?.name||'현지 인맥';
  }});};
  const first=usable[0],second=usable[1]||usable[0];
  if((mode==='explore'||mode==='investigate'||mode==='sail')&&safe>=7){
    add(`[생존 ${Math.round(safe)}] 지형과 현장의 흔적을 교차 검증한다`,first,
      `${state.owner.name}은 오래된 상처와 현장을 견뎌 온 경험으로 다른 이가 지나친 위험을 먼저 알아차렸다. 그 덕분에 숨겨진 흔적 하나를 더 확보했다.`,'survival');
  }else if(mode==='contract'&&martial>=7){
    add(`[무예 ${Math.round(martial)}] 무력 충돌 지점을 먼저 제압한다`,first,
      `${state.owner.name}은 싸움의 유불리를 먼저 계산해 상대가 기습할 수 있는 길목을 막았다. 상대는 예상한 위협이 통하지 않는다는 것을 깨달았다.`,'martial');
  }
  if(social>=6 && out.length<2){
    add(`[처세 ${Math.round(social)}] 진술의 모순을 이용해 협력자를 확보한다`,second,
      `앞뒤가 맞지 않는 말 한마디를 짚자 사람들의 표정이 바뀌었다. ${state.owner.name}은 상대의 입장을 무너뜨리는 대신, 진실을 말해도 안전한 조건부터 제시했다.`,'social');
  }
  if(relations.length && out.length<2){
    add(`[인맥 · ${relations[0].name}] 익숙한 증언과 연락망을 동원한다`,second,
      `${relations[0].name}이 남긴 정보가 결정적 실마리가 되었다. 처음부터 쌓아 온 관계가 이 자리에서 쓸모를 드러냈다.`,'relation');
  }
  if((rep>=12 || deeds>=2 || history>=2) && out.length<2){
    add(`[업적 · ${rep>=12?'명성':history>=2?'항해 기록':'생존의 기록'}] 과거 성과를 증명한다`,first,
      `예전의 선택을 기억하는 사람이 앞으로 나섰다. 헛된 허세가 아니라 이미 남긴 성과가 증언을 뒷받침했다.`,'legacy');
  }
  return out;
}
const _showStoryNodeV37Base=showStoryNode;
showStoryNode=function(node){if(state.storyCtx)state.storyCtx.currentNode=node;return _showStoryNodeV37Base(node);};
const _openStorySceneV37Base=openStoryScene;
openStoryScene=function(kicker,title,text,choices){
  const ctx=state.storyCtx||{},unlock=v37UnlockOptions(choices),pass=Array.isArray(choices)?[...choices,...unlock]:choices;
  if(ctx.v37SceneNote){text=`${ctx.v37SceneNote}\n\n${text}`;ctx.v37SceneNote='';}
  _openStorySceneV37Base(kicker,title,text,pass);
  $('overlay')?.classList.add('storyFullscreen');
  const sc=$('modal')?.querySelector('.storyScene');if(!sc)return;
  const node=String(ctx.currentNode||''),policy=state.policy;
  const showArt=(node==='start'||node==='chapter_intro'||node==='od36_twist'||node==='v25_research_follow');
  if(showArt){
    const which=policy==='sail'?'scene_contract':policy==='explore'?'scene_explore':policy==='investigate'?'scene_investigate':policy==='rest'?'scene_rest':'scene_contract';
    const image=document.createElement('figure');image.className='storyCinematic';
    image.innerHTML=`<img loading="eager" alt="${policy==='explore'?'오디세이 연안과 바위 절벽':policy==='investigate'?'트로이 전장의 기록과 방패 조각':policy==='rest'?'오디세이 연안 풍경':'트로이 항만의 사람들과 귀향길'}" src="${V37_CINEMATICS[which]}"><figcaption>${ownerText(kicker)} · 장면 삽화</figcaption>`;
    const header=sc.querySelector('.storyTitle');if(header)header.after(image);
  }
  if(unlock.length){
    sc.querySelectorAll('.storyChoice').forEach((b,i)=>{if(i>=choices.length)b.classList.add('unlockChoice');});
    const row=document.createElement('div');row.className='sceneEvidence';row.innerHTML=`<strong>추가 선택지 ${unlock.length}개 해금</strong> · 소유자의 능력치, 인맥 또는 업적이 새로운 해결 방식을 열었습니다.`;
    sc.querySelector('.storyChoices')?.before(row);
  }
};
// MAIN mandatory investigations: an attempted, completed two-step investigation always reveals
// the required navigation clue; low skill determines cost/quality, never months of soft-lock.
showAct1ResearchNodeV25=function(node){
  const ch=Number(String(state.subChoice||'').match(/ch(\d+)/)?.[1]||0),c=ACT1_CHAPTERS_V25[ch-1],r=ACT1_RESEARCH_TEXT_V25[ch];
  if(!c||!r)return finishStory('해당 조사 대상을 확인할 수 없었다.');
  const ctx=state.storyCtx||{};
  if(node==='start')return openStoryScene(`MAIN 조사 · CH.${ch}`,c.researchTitle,
    `${r.intro}\n\n필수 조사: 어떤 경로를 선택해도 충분히 확인하면 다음 MAIN으로 진입합니다. 추가 선택지는 조사 품질과 다음 전투 준비를 바꿉니다.`,[
      {label:r.a,effect:x=>{x.v25ResearchPath='a';x.lastApproach=ACT1_RESEARCH_APPROACH_V27[ch]?.a||'social';x.skipIntegratedResolution=true;},next:'v25_research_follow'},
      {label:r.b,effect:x=>{x.v25ResearchPath='b';x.lastApproach=ACT1_RESEARCH_APPROACH_V27[ch]?.b||'survival';x.skipIntegratedResolution=true;},next:'v25_research_follow'}
    ]);
  if(node==='v25_research_follow'){
    const path=ctx.v25ResearchPath||'a',body=path==='a'?r.a2:r.b2,orig=evaluateAct1ResearchV27(ch,path);
    let grade=orig.grade==='setback'?'costly':orig.grade;
    if(Number(ctx.v37Advantage||0)>0)grade=grade==='costly'?'steady':'strong';
    const consequence=grade==='strong'?'함께 확인한 증거가 다음 대치에서 상대의 허점을 먼저 보여준다.':grade==='steady'?'필수 단서가 확인되었다. 다음 메인 사건에 진입할 수 있다.':'답은 찾았으나 되돌아오는 길에 시간을 허비했다. 다음 사건에 대한 준비가 조금 부족하다.';
    return openStoryScene(`MAIN 조사 · CH.${ch}`,'흩어진 단서가 하나로 이어지다',
      `${body}\n\n${consequence}\n\n확정 단서: ${r.fact}`, [
      {label:'증거를 연대기에 확정하고 MAIN 사건을 연다',effect:x=>{
        if(!act1ResearchDoneV25(ch))completeAct1ResearchV25(ch,path);
        state.mainStory.act1Research[ch].quality=grade;
        state.mainStory.flags[`act1_ch${ch}_research_quality`]=grade;
        x.v27Resolution={grade:grade==='strong'?'strong':'steady'};
        x.notes.push(`MAIN 조사 확정 · CH.${ch} · ${grade}`);
        if(grade==='costly'){state.mind=clamp(state.mind-2,0,state.maxMind);x.notes.push('추적 피로 · 정신 -2');}
        saveGame();
      },next:'END',outcome:`제1장 CH.${ch} 필수 조사 완료 · ${r.fact}`}
    ]);
  }
};

ensureV24State();
recalcWeapon();
syncOwnerVitalCaps(false);

// ===== v3.8 ROUND TABLE: presentation-only main hub, five unlockable Odyssey cutscenes =====
const WC38_FILM=[
  {chapter:1,name:'전쟁이 끝난 항구',loc:'트로이 · 출항',subtitle:'떠나야 할 곳과 돌아가야 할 곳',narration:'트로이의 불길이 잦아든 뒤에도 항구에는 끝나지 않은 소문이 남아 있었다.\n\n그의 곁에서 검은 말없이 바다를 바라보았다. 파도는 땅 위의 승패를 모른다. 오직 떠나는 자의 발자국만 지워 버릴 뿐이었다.',art:'data:image/webp;base64,'},
  {chapter:3,name:'폐허가 부르는 이름',loc:'이스마로스 · 연안',subtitle:'전리품보다 오래 남는 것은 사람의 기억',narration:'이스마로스의 무너진 담장 사이로 소금기 어린 바람이 흘렀다.\n\n사람들은 하나의 전쟁을 서로 다른 이름으로 불렀다. 검은 그들이 남긴 상처와 약속을 새로운 전승으로 간직하기 시작했다.',art:'data:image/webp;base64,'},
  {chapter:5,name:'돌아오지 않는 섬',loc:'로토스 · 잊힘의 해변',subtitle:'달콤한 망각이 가장 위험한 유혹이 된다',narration:'푸른 물과 꽃의 향기는 먼 곳의 고향마저 희미하게 만들었다.\n\n하루만 쉬어 가겠다는 약속이 일주일이 되고, 일주일은 계절을 삼켰다. 검만이 떠나기 전의 이름들을 기억했다.',art:'data:image/webp;base64,'},
  {chapter:6,name:'거인의 그림자',loc:'폴리페모스 · 동굴',subtitle:'아무도 눈을 마주치지 못한 밤',narration:'깊은 동굴 속에서 돌이 밀리는 소리가 울렸다. 출구는 막혔고, 그림자는 한 사람의 키로 가늠할 수 없을 만큼 컸다.\n\n거인의 숨소리가 가까워질수록 사람들은 무기보다 서로를 먼저 바라보았다.',art:'data:image/webp;base64,'},
  {chapter:8,name:'그리고 다시 바다로',loc:'제1장 · 다음 항로',subtitle:'검이 남긴 기억은 새로운 소유자를 기다린다',narration:'햇빛이 수평선에 닿았을 때, 뒤에 남겨 둔 이름들이 떠올랐다.\n\n누가 살아남고 누가 사라져도 바다는 다음 항로를 열어 둔다. 이야기의 중심에는 언제나 한 자루의 검이 있었다.',art:'data:image/webp;base64,'}
];
let wc38SceneIndex=0;
function wc38UnlockedCount(){const ch=Math.max(1,Number(state.mainStory?.chapter||1));return Math.max(1,WC38_FILM.filter(x=>x.chapter<=ch).length);}
function wc38CurrentIndex(){return wc38UnlockedCount()-1;}
function wc38UpdateHub(){
 const ix=wc38CurrentIndex(),sc=WC38_FILM[ix];
 const im=$('wc38HeroImage');
 if(im && im.dataset.sceneIndex!==String(ix)){im.src=sc.art;im.dataset.sceneIndex=String(ix);}
 if($('wc38ChapterPill')) $('wc38ChapterPill').textContent=`제1장 · ${sc.loc}`;
 if($('wc38HeroTitle')) $('wc38HeroTitle').textContent=sc.name;
 if($('wc38HeroSubtitle')) $('wc38HeroSubtitle').textContent=sc.subtitle;
 if($('wc38HeroCount')) $('wc38HeroCount').textContent=`SCENE ${String(ix+1).padStart(2,'0')} / 05`;
}
function wc38SetScene(index){
 const max=wc38UnlockedCount();wc38SceneIndex=Math.max(0,Math.min(max-1,index));const scene=WC38_FILM[wc38SceneIndex];
 const im=$('wc38CineImage');im.style.animation='none';im.offsetWidth;im.src=scene.art;im.style.animation='';
 im.alt=scene.loc+'의 항해 컷신';$('wc38CineTitle').textContent=scene.name;
 $('wc38CineCounter').textContent=`제1장 · ${scene.loc} · ${String(wc38SceneIndex+1).padStart(2,'0')} / 05`;
 $('wc38CineNarration').textContent=scene.narration;
 $('wc38CinePrev').disabled=wc38SceneIndex===0;$('wc38CineNext').disabled=wc38SceneIndex>=max-1;
 $('wc38CineHint').textContent=`현재까지 ${max}개 장면 해금 · 진행하지 않은 장면은 숨김`;
}
function wc38OpenCutscene(first=false){wc38SetScene(first?0:wc38CurrentIndex());const o=$('wc38Cinematic');o.classList.add('on');o.setAttribute('aria-hidden','false');}
function wc38CloseCutscene(){const o=$('wc38Cinematic');o.classList.remove('on');o.setAttribute('aria-hidden','true');}
function wc38Install(){
 // Action selection belongs directly beneath the cinematic hub: never hide gameplay below equipment menus.
 const hubRoot=document.querySelector('.main'),hubInfo=hubRoot?.querySelector('.hubTop'),action=hubRoot?.querySelector('.actionHub');
 // v3.9 keeps action hub below owner/service hub.
 $('wc38PlayCutscene')?.addEventListener('click',()=>wc38OpenCutscene());
 $('wc38GalleryBtn')?.addEventListener('click',()=>wc38OpenCutscene(true));
 $('wc38CineClose')?.addEventListener('click',wc38CloseCutscene);
 $('wc38CinePrev').addEventListener('click',()=>wc38SetScene(wc38SceneIndex-1));
 $('wc38CineNext').addEventListener('click',()=>wc38SetScene(wc38SceneIndex+1));
 $('wc38Cinematic').addEventListener('click',e=>{if(e.target===$('wc38Cinematic'))wc38CloseCutscene();});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('wc38Cinematic').classList.contains('on'))wc38CloseCutscene();});
 const arts={contract:'data:image/webp;base64,',explore:'data:image/webp;base64,',investigate:'data:image/webp;base64,',rest:'data:image/webp;base64,'};
 document.querySelectorAll('[data-action-policy]').forEach(b=>{let key=b.dataset.actionPolicy;b.style.setProperty('--wc38-art',`url("${arts[key]||arts.contract}")`);});
 const _renderWC38=render;
 render=function(){const r=_renderWC38();wc38UpdateHub();return r;};
 wc38UpdateHub();
}
wc38Install();

/* wc40-polish-script */
function serviceSceneArt40(kind){return ({market:'data:image/webp;base64,',smith:'data:image/webp;base64,',temple:'data:image/webp;base64,',visit:'data:image/webp;base64,',gear:'data:image/webp;base64,'})[kind]||'data:image/webp;base64,';}
function serviceShell40(title,desc,kind,leftHtml,rightHtml='',kicker='ODYSSEY · WEAPON CHRONICLE'){const art=serviceSceneArt40(kind);return modalHead(title,desc)+`<div class="serviceShell40"><div class="serviceHero40"><div class="serviceHeroScene40" style="background-image:url('${art}')"><div class="serviceKicker40">${kicker}</div><h3>${title}</h3><p>${desc}</p></div><div class="serviceBody40">${leftHtml}</div></div>${rightHtml?`<div class="serviceRight40">${rightHtml}</div>`:''}</div>`;}
function choiceCardVisual40(title,desc,tag,art,attrs=''){return `<button class="choiceCardVisual40" type="button" style="--card-art:url('${art}')" ${attrs}><b>${title}</b><span>${desc}</span>${tag?`<small>${tag}</small>`:''}</button>`;}
function ownerGearCardHtml40(id,extraBtn=''){const it=OWNER_GEAR_CATALOG[id];if(!it)return '';const eq=state.ownerEquipment[it.slot]===id;return `<div class="gearChoiceCard40 rarity-${it.rarity}" style="--card-art:url('${gearArtUrl39(id)}')"><div class="gearArtFrame" style="--gear-art:url('${gearArtUrl39(id)}')"><div class="gearArtLabel">${OWNER_GEAR_SLOTS[it.slot]}</div></div><b>${it.name}</b><span>${it.desc}</span><div class="effectLine">${gearEffectText(id)}</div><div class="tag">${OWNER_GEAR_SLOTS[it.slot]}</div><div class="gearFooter"><span class="cost">${it.price||0}G</span>${extraBtn||`<button class="buyBtn" data-equip-gear="${id}" ${eq?'disabled':''}>${eq?'장착중':'장착'}</button>`}</div></div>`;}
function ownerGearPanel40(){ensureV24State();const g=ownerGearBonuses();return `<div class="equipPanel40"><div class="dualTitle"><div><b>${state.owner.name} 장비</b><span>소유자 귀속 장비 · 독립 가방 ${v35BagSummary('armor')}</span></div><span class="inlinePill">${state.gold}G</span></div><div class="ownerGearBoard40">${Object.entries(OWNER_GEAR_SLOTS).map(([slot,label])=>{const id=state.ownerEquipment[slot],it=id&&OWNER_GEAR_CATALOG[id];return `<button class="ownerGearSlot ${it?'rarity-'+it.rarity:''}" data-owner-slot="${slot}"><b>${label}</b><span>${it?it.name:'비어 있음'}</span></button>`}).join('')}</div><div class="gearSummary40"><div>방어<b>${g.defense>=0?'+':''}${g.defense}</b></div><div>회피<b>${g.evade>=0?'+':''}${g.evade}</b></div><div>막기<b>${g.block>=0?'+':''}${g.block}%</b></div><div>저항<b>${g.resist>=0?'+':''}${g.resist}%</b></div></div>${state.foodBuff?`<div class="foodBuffLine">현재 식사 효과 · ${state.foodBuff.name}</div>`:''}</div>`;}

