function openVisitResonance(){const left=`<div class="visualCardList40">${choiceCardVisual40(`${state.owner.name}과 공명`,`현재 소유자의 생각과 감정을 직접 확인한다. 공명을 통해 숨은 의중과 걱정을 들을 수 있다.`,`공명`,`data:image/webp;base64,`,`id="openOwnerRes"`)}${choiceCardVisual40(`인맥 방문`,`알고 지내는 인물을 찾아가 친밀도와 소문, 희귀 루트를 확인한다.`,`방문`,`data:image/webp;base64,`,`id="openContacts"`)}</div><div class="templeBadgeRow40"><span class="serviceMiniPill">현재 공명 ${Math.round(state.weapon.resonance)}/${state.weapon.maxResonance}</span><span class="serviceMiniPill">인맥 ${Object.keys(state.contacts||{}).length}명</span></div>`;const right=`<div class="serviceCard40"><div class="dualTitle"><div><b>공명 효과</b><span>소유자의 의도와 정서를 파악한다</span></div></div><div class="modalDesc">공명은 단순 정보 열람이 아니라 다음 행동의 방향성과 숨은 선택지를 읽는 장치다. 방문은 처세·관계·희귀 사건과 연결된다.</div></div>`;openModal(serviceShell40('방문 / 공명',`${state.owner.name}과 공명하거나 지금까지 알게 된 인물을 찾아간다.`,'visit',left,right,'VISIT · RESONANCE'));bindClose();$('openOwnerRes').onclick=openOwnerResonance;$('openContacts').onclick=openContacts;}
function openTemple(){if(state.templeUsed)return;const a=ensureAilmentsV34();const ailments=[a.injury?'부상 (생존 -2)':'',a.poison?'중독 (매달 HP -4)':''].filter(Boolean);const choices=[{id:'hp',name:'치료실 · 상처 치료',desc:`HP +30 (현재 ${state.hp}/${state.maxHp})`,cost:12,art:'data:image/webp;base64,',gain:'HP 회복 중심',ok:()=>state.gold>=12&&state.hp<state.maxHp,apply:()=>{const old=state.hp;state.hp=Math.min(state.maxHp,state.hp+30);addLog(`신전 치료실에서 HP +${state.hp-old}`);}},{id:'mind',name:'상담실 · 정신 회복',desc:`정신 +25 (현재 ${state.mind}/100)`,cost:12,art:'data:image/webp;base64,',gain:'정신 회복 중심',ok:()=>state.gold>=12&&state.mind<100,apply:()=>{const old=state.mind;state.mind=Math.min(100,state.mind+25);addLog(`상담실에서 정신 +${state.mind-old}`);}},{id:'cleanse',name:'치료·해독 · 디버프 제거',desc:ailments.length?'현재 상태이상: '+ailments.join(' / '):'치료할 지속 상태이상이 없음',cost:16,art:'data:image/webp;base64,',gain:'지속 상태이상 정리',ok:()=>state.gold>=16&&ailments.length>0,apply:()=>{a.injury=false;a.poison=false;addLog('신전에서 부상과 중독을 치료했다.');}},{id:'combined',name:'응급 집중치료',desc:'HP +15 · 정신 +12 (둘 다 부족해야 이용)',cost:18,art:'data:image/webp;base64,',gain:'균형 회복',ok:()=>state.gold>=18&&state.hp<state.maxHp&&state.mind<100,apply:()=>{state.hp=Math.min(state.maxHp,state.hp+15);state.mind=Math.min(100,state.mind+12);addLog('신전 응급 치료로 HP +15 · 정신 +12 (상한 적용)');}}];const left=`<div class="templeActionGrid40">${choices.map(c=>`<button class="templeAction40" data-temple40="${c.id}" style="--card-art:url('${c.art}')" ${!c.ok()?'disabled':''}><b>${c.name}</b><span>${c.desc}</span><div class="gainLine">${c.gain}</div><span class="cost">${c.cost}G</span></button>`).join('')}</div><div class="templeBadgeRow40"><span class="serviceMiniPill">이번 달 1회 이용</span><span class="serviceMiniPill">GOLD ${state.gold}G</span><span class="serviceMiniPill">상태이상 ${ailments.length?ailments.join(' / '):'없음'}</span></div>`;const right=`<div class="serviceCard40"><div class="dualTitle"><div><b>현재 상태</b><span>회복 전에 확인</span></div></div><div class="modalDesc">HP ${state.hp}/${state.maxHp}<br>정신 ${state.mind}/100<br>${ailments.length?ailments.join('<br>'):'지속 상태이상 없음'}</div></div><div class="serviceCard40"><div class="dualTitle"><div><b>신전 규칙</b><span>추상 옵션 제외</span></div></div><div class="modalDesc">상처 치료, 정신 회복, 디버프 제거, 응급 집중치료만 제공한다. 이번 달에는 한 번만 이용할 수 있다.</div></div>`;openModal(serviceShell40('신전 · 치료실',`이번 달 1회 이용 · GOLD ${state.gold}G · 현재 HP ${state.hp}/${state.maxHp} · 정신 ${state.mind}/100`,'temple',left,right,'TEMPLE · RECOVERY'));bindClose();document.querySelectorAll('[data-temple40]').forEach(b=>b.onclick=()=>{const c=choices.find(x=>x.id===b.dataset.temple40);if(!c||state.templeUsed||!c.ok())return;state.gold-=c.cost;c.apply();state.templeUsed=true;addLog('이번 달 신전 이용 완료');closeModal();render();saveGame();});}
function openOwnerEquipment(){ensureV24State();const left=ownerGearPanel40()+`<div class="sectionMini">보유 장비</div><div class="gearInventoryGrid40">${Object.entries(state.ownerGearOwned).filter(([id,n])=>n>0&&OWNER_GEAR_CATALOG[id]).map(([id,n])=>ownerGearCardHtml40(id,`<button class="buyBtn" data-equip-gear="${id}" ${state.ownerEquipment[OWNER_GEAR_CATALOG[id].slot]===id?'disabled':''}>${state.ownerEquipment[OWNER_GEAR_CATALOG[id].slot]===id?'장착중':'장착'}</button>`)).join('')||'<div class="invEmpty">보유한 소유자 장비가 없다.</div>'}</div>`;const cons=['bandage','medkit','antidote','tonic','rations'].filter(id=>(state.prep[id]||0)>0).map(id=>`<div class="sideItem"><div class="meta"><b>${HEALER_GOODS[id]?.name||GENERAL_GOODS[id]?.name||id}</b><span>보유 중</span></div><div class="qty"><span>×${state.prep[id]}</span>${id==='tonic'?`<button class="sellBtnMini" data-use-tonic>사용</button>`:''}</div></div>`).join('')||'<div class="invEmpty">보유 소모품 없음</div>';const right=`<div class="serviceCard40"><div class="dualTitle"><div><b>회복 소모품</b><span>장비 메뉴에서도 사용 가능</span></div></div><div class="sideList">${cons}</div></div>`;openModal(serviceShell40(`${state.owner.name} 장비`,`소유자 장비는 인간에게 귀속된다. 검의 파츠와 달리 소유자가 사라지면 함께 사라질 수 있다.`,'gear',left,right,'OWNER EQUIPMENT'));bindClose();document.querySelectorAll('[data-owner-slot]').forEach(b=>b.onclick=()=>openOwnerSlot(b.dataset.ownerSlot));document.querySelectorAll('[data-equip-gear]').forEach(b=>b.onclick=()=>{equipOwnerGear(b.dataset.equipGear);openOwnerEquipment();});document.querySelector('[data-use-tonic]')?.addEventListener('click',()=>{if((state.prep.tonic||0)<1)return;state.prep.tonic--;state.mind=clamp(state.mind+16,0,state.maxMind);addLog('진정 물약으로 정신을 추슬렀다.');saveGame();openOwnerEquipment();render();});}
function openOwnerSlot(slot){const ids=Object.entries(state.ownerGearOwned).filter(([id,n])=>n>0&&OWNER_GEAR_CATALOG[id]?.slot===slot).map(([id])=>id);const cur=state.ownerEquipment[slot];const cards=ids.map(id=>ownerGearCardHtml40(id,`<button class="buyBtn" data-owner-equip2="${id}" ${cur===id?'disabled':''}>${cur===id?'장착중':'장착'}</button>`)).join('')||'<div class="invEmpty">해당 부위 장비가 없다.</div>';const left=`<div class="serviceCard40"><div class="dualTitle"><div><b>${OWNER_GEAR_SLOTS[slot]} 장착</b><span>장비의 장점과 단점은 소유자의 전투 파생치에 직접 적용된다.</span></div></div><div class="gearInventoryGrid40">${cards}</div></div>`;const right=`<div class="serviceCard40">${ownerGearPanel40()}<div style="margin-top:8px"><button class="choice" data-owner-unequip="${slot}" ${cur&&hasOwnerCapacity(1,'armor')?'':'disabled'}><b>장비 해제</b><span>현재 장비를 벗는다.</span></button></div></div>`;openModal(serviceShell40(`${OWNER_GEAR_SLOTS[slot]} 장착`,`장비 카드는 A안 기준으로 우선 적용한다.`,'gear',left,right,'GEAR SLOT'));bindClose();document.querySelector('[data-owner-unequip]')?.addEventListener('click',()=>{unequipOwnerSlot(slot);openOwnerSlot(slot)});document.querySelectorAll('[data-owner-equip2]').forEach(b=>b.onclick=()=>{equipOwnerGear(b.dataset.ownerEquip2);openOwnerSlot(slot);});}
function marketOwnerPane(tab){const title=tab==='armor'?'장비 장착 / 판매':tab==='healer'?'회복약 판매':tab==='general'?'잡화 판매':'현재 식사 효과';let trade='';if(tab==='armor'){trade=`<div class="gearInventoryGrid40">`+(Object.entries(state.ownerGearOwned).filter(([id,n])=>n>0&&OWNER_GEAR_CATALOG[id]).map(([id,n])=>{const eq=Object.values(state.ownerEquipment).includes(id);return ownerGearCardHtml40(id,`<div style="display:flex;gap:6px"><button class="buyBtn" data-equip-gear="${id}" ${eq?'disabled':''}>${eq?'장착중':'장착'}</button><button class="sellBtnMini" data-sell-owner-gear="${id}" ${eq?'disabled':''}>판매</button></div>`);}).join('')||'<div class="invEmpty">보유 방어구 없음</div>')+`</div>`;}else if(tab==='healer'){trade=['bandage','medkit','antidote','tonic'].filter(id=>(state.prep[id]||0)>0).map(id=>`<div class="sideItem"><div class="meta"><b>${HEALER_GOODS[id].name}</b><span>보유 소모품</span></div><div class="qty"><span>×${state.prep[id]}</span><button class="sellBtnMini" data-sell-market-item="${id}">판매</button></div></div>`).join('')||'<div class="invEmpty">판매할 회복 소모품 없음</div>';}else if(tab==='general'){trade=([...(state.prep.rations>0?[`<div class="sideItem"><div class="meta"><b>${GENERAL_GOODS.rations.name}</b><span>보유 식량</span></div><div class="qty"><span>×${state.prep.rations}</span><button class="sellBtnMini" data-sell-market-item="rations">판매</button></div></div>`]:[]),...Object.entries(GENERAL_GOODS).filter(([id,it])=>it.kind==='material'&&(state.weapon.materials[id]||0)>0).map(([id,it])=>`<div class="sideItem"><div class="meta"><b>${it.name}</b><span>제작 재료</span></div><div class="qty"><span>×${state.weapon.materials[id]}</span><button class="sellBtnMini" data-sell-material="${id}">판매</button></div></div>`)]).join('')||'<div class="invEmpty">판매할 잡화 없음</div>';}else trade=state.foodBuff?`<div class="foodBuffLine">현재 식사 효과 · ${state.foodBuff.name}</div>`:'<div class="invEmpty">현재 식사 효과 없음</div>';return `<div class="serviceCard40">${ownerGearPanel40()}<div class="sectionMini">${title}</div><div class="sideList">${trade}</div></div>`;}
function openMarket(tab='healer'){ensureV24State();if(!state.marketV24||!Array.isArray(state.marketV24.armor))resetMarketOnlyV24();let cards='';if(tab==='healer'){cards=Object.entries(HEALER_GOODS).map(([id,it])=>{const stock=state.marketStock[id]||0,can=stock>0&&state.gold>=it.price&&hasOwnerCapacity(1,'consumable',id);return `<div class="shopCard"><div class="ico">${id==='bandage'?'🩹':id==='medkit'?'🧰':id==='antidote'?'🧪':'◈'}</div><b>${it.name}</b><p>${it.desc}</p><div class="stock">재고 ${stock} · ${it.price}G</div><button class="buyBtn" data-buy-heal="${id}" ${can?'':'disabled'}>구매</button></div>`}).join('');}else if(tab==='armor'){cards=(state.marketV24.armor||[]).map(row=>{const it=OWNER_GEAR_CATALOG[row.id],can=!row.sold&&state.gold>=it.price&&hasOwnerCapacity(1,'armor',row.id);return ownerGearCardHtml40(row.id,`<button class="buyBtn" data-buy-armor="${row.id}" ${can?'':'disabled'}>${row.sold?'완료':'구매'}</button>`)}).join('');}else if(tab==='general'){cards=Object.entries(GENERAL_GOODS).map(([id,it])=>{const stock=state.marketV24.general?.[id]||0,can=stock>0&&state.gold>=it.price&&hasOwnerCapacity(1,id==='rations'?'consumable':'material',id);return `<div class="shopCard"><div class="ico">${id==='rations'?'🍖':'◆'}</div><b>${it.name}</b><p>${it.desc||'대장간 제작과 여행에 쓰는 물자'}</p><div class="stock">재고 ${stock} · ${it.price}G</div><button class="buyBtn" data-buy-general="${id}" ${can?'':'disabled'}>구매</button></div>`}).join('');}else{cards=Object.entries(FOOD_CATALOG).map(([id,it])=>{const available=Number(state.marketV24.food?.[id]||0);const can=available>0&&state.gold>=it.price;return `<div class="shopCard"><div class="ico">🍲</div><b>${it.name}</b><p>${it.desc}</p><div class="stock">재고 ${available} · ${it.price}G</div><button class="buyBtn" data-buy-food="${id}" ${can?'':'disabled'}>식사</button></div>`}).join('');}const left=marketTabsV24(tab)+`<div class="marketCardGrid">${cards||'<div class="invEmpty">재고 없음</div>'}</div><div class="templeBadgeRow40"><span class="serviceMiniPill">${tab==='armor'?v35BagSummary('armor'):tab==='healer'||tab==='food'?v35BagSummary('consumable'):v35BagSummary('material')}</span><span class="serviceMiniPill">GOLD ${state.gold}G</span><button class="selectionChangeBtn" id="refreshMarketBtn">재고 새로고침 ${state.marketRefreshFree?'무료':'8G'}</button></div>`;const right=marketOwnerPane(tab);openModal(serviceShell40('시장','검 부품은 시장에서 거래하지 않는다. 사람의 몸과 생활에 필요한 물건만 취급한다.','market',left,right,'MARKET · TOWN'));bindClose();document.querySelectorAll('[data-v24market]').forEach(b=>b.onclick=()=>openMarket(b.dataset.v24market));$('refreshMarketBtn')?.addEventListener('click',()=>refreshMarket(tab));document.querySelectorAll('[data-equip-gear]').forEach(b=>b.onclick=()=>{equipOwnerGear(b.dataset.equipGear);openMarket(tab);});document.querySelectorAll('[data-sell-owner-gear]').forEach(b=>b.onclick=()=>{sellOwnerGear(b.dataset.sellOwnerGear);openMarket(tab);render();});document.querySelectorAll('[data-sell-market-item]').forEach(b=>b.onclick=()=>{sellMarketConsumableV24(b.dataset.sellMarketItem);openMarket(tab);render();});document.querySelectorAll('[data-sell-material]').forEach(b=>b.onclick=()=>{sellMaterialV24(b.dataset.sellMaterial);openMarket(tab);render();});document.querySelectorAll('[data-buy-heal]').forEach(b=>b.onclick=()=>{const id=b.dataset.buyHeal,it=HEALER_GOODS[id];if((state.marketStock[id]||0)<1||state.gold<it.price||!hasOwnerCapacity(1,'consumable',id))return;state.gold-=it.price;state.marketStock[id]--;state.prep[id]=(state.prep[id]||0)+1;addLog(`${it.name}을 구입했다.`);saveGame();openMarket(tab);render();});document.querySelectorAll('[data-buy-armor]').forEach(b=>b.onclick=()=>{const id=b.dataset.buyArmor,row=(state.marketV24.armor||[]).find(x=>x.id===id&&!x.sold),it=OWNER_GEAR_CATALOG[id];if(!row||state.gold<it.price||!hasOwnerCapacity(1,'armor',id))return;state.gold-=it.price;row.sold=true;state.ownerGearOwned[id]=(state.ownerGearOwned[id]||0)+1;addLog(`${it.name}을 구입했다.`);saveGame();openMarket(tab);render();});document.querySelectorAll('[data-buy-general]').forEach(b=>b.onclick=()=>{const id=b.dataset.buyGeneral,it=GENERAL_GOODS[id];if((state.marketV24.general?.[id]||0)<1||state.gold<it.price)return;const bagType=id==='rations'?'consumable':'material';if(!hasOwnerCapacity(1,bagType,id))return;state.gold-=it.price;state.marketV24.general[id]--;if(id==='rations')state.prep.rations=(state.prep.rations||0)+1;else state.weapon.materials[id]=(state.weapon.materials[id]||0)+1;addLog(`${it.name}을 구입했다.`);saveGame();openMarket(tab);render();});document.querySelectorAll('[data-buy-food]').forEach(b=>b.onclick=()=>{const id=b.dataset.buyFood,it=FOOD_CATALOG[id];if(!it||Number(state.marketV24.food?.[id]||0)<1||state.gold<it.price)return;state.gold-=it.price;state.marketV24.food[id]--;state.foodBuff={id,name:it.name,...it.buff};if(it.buff.mindNow)state.mind=clamp(state.mind+it.buff.mindNow,0,state.maxMind);if(it.buff.rations)state.prep.rations=(state.prep.rations||0)+it.buff.rations;addLog(`${it.name}을 먹었다. 다음 위험한 행동에 몸이 반응할 것이다.`);saveGame();openMarket(tab);render();});}
function smithWorkbenchShell(title,desc,leftHtml,selectedSlot=null,filterable=false){const right=`<div class="serviceCard40"><div class="dualTitle"><div><b>검 파츠 보관함</b><span>${filterable?'우측 파츠를 눌러 왼쪽 목록을 거른다':'능력치 표 대신 실제 장착품과 재료만 표시'}</span></div></div>${equipmentVisualHtml()}${simpleSmithInventoryHtml(selectedSlot,filterable)}</div>`;return serviceShell40(title,desc,'smith',leftHtml,right,'SMITH WORK');}
function openSmith(){ensureV24State();const left=`<div class="smithMainActions40"><button class="smithActionCard40" id="smithBuy" style="--card-art:url('data:image/webp;base64,')"><b>구매</b><span>이번 달 들어온 검 파츠를 산다.</span><div class="gainLine">신규 파츠 확보</div></button><button class="smithActionCard40" id="smithSell" style="--card-art:url('data:image/webp;base64,')"><b>판매</b><span>보관 중인 예비 파츠를 판다.</span><div class="gainLine">골드 확보</div></button><button class="smithActionCard40" id="smithCraft" style="--card-art:url('data:image/webp;base64,')"><b>제작</b><span>알고 있는 제작법과 재료로 파츠를 만든다.</span><div class="gainLine">재료 → 파츠</div></button><button class="smithActionCard40" id="smithEnhance" style="--card-art:url('data:image/webp;base64,')" ${state.enhanceUsed?'disabled':''}><b>강화</b><span>${state.enhanceUsed?'이번 달 완료':'가공·열처리·균형·공명좌 작업'}</span><div class="gainLine">무기 성능 상승</div></button><button class="smithActionCard40" id="smithEngrave" style="--card-art:url('data:image/webp;base64,')"><b>각인</b><span>검이 기억한 활성 기억을 새긴다.</span><div class="gainLine">기억 세팅</div></button><button class="smithActionCard40" id="smithRepair" style="--card-art:url('data:image/webp;base64,')"><b>수리</b><span>손상된 검의 내구를 복구한다.</span><div class="gainLine">내구 회복</div></button></div>`;const right=`<div class="serviceCard40"><div class="dualTitle"><div><b>검 파츠 보관함</b><span>현재 장착 파츠와 예비 파츠</span></div></div>${equipmentVisualHtml()}${simpleSmithInventoryHtml()}</div>`;openModal(serviceShell40('대장간','검에 관련된 거래와 작업은 이곳에서만 한다. 소유자의 방어구와 생활용품은 시장의 영역이다.','smith',left,right,'SMITHY · LEGEND CORE'));bindClose();$('smithBuy').onclick=()=>openSmithBuy();$('smithSell').onclick=()=>openSmithSell();$('smithCraft').onclick=()=>openSmithCraft();$('smithEnhance').onclick=()=>openSmithEnhance();$('smithEngrave').onclick=()=>openSmithEngrave();$('smithRepair').onclick=()=>openSmithRepair();}
function openContacts(){ensureV26Progression();const entries=Object.entries(state.contacts).map(([id,n])=>choiceCardVisual40(n.name,`${n.status}<br>친밀도 ${Math.round(Number(n.affinity)||0)}`,'인맥 방문',id==='mira'?'data:image/webp;base64,':'data:image/webp;base64,',`data-contact-open="${id}"`)).join('');const left=`<div class="visitStage40"><div class="visitPortrait40">⌂</div><div class="bubbleLarge40">누구를 찾아갈까? 관계망은 처세와 희귀 루트에 반영된다.</div></div><div class="visualCardList40">${entries}</div>`;const right=`<div class="serviceCard40"><div class="dualTitle"><div><b>관계망</b><span>소유자 사망 시 현재 활성 관계망은 초기화된다</span></div></div><div class="modalDesc">방문은 친밀도를 높이고, 일부 사건의 추가 선택지를 여는 데 사용된다.</div></div>`;openModal(serviceShell40('인맥 방문','현재 소유자의 관계망이다. 친밀한 인연은 처세에 반영되며, 소유자가 죽으면 활성 관계망은 새로 시작한다.','visit',left,right,'VISIT · CONTACTS'));bindClose();document.querySelectorAll('[data-contact-open]').forEach(b=>b.onclick=()=>startVisit(b.dataset.contactOpen));}
function startVisit(id){ensureV26Progression();const n=state.contacts[id];if(!n)return;const topics=(state.visitScripts[id]||[]).slice(0,3);const choices=topics.map(x=>choiceCardVisual40(x.q,'대화를 이어간다','질문',id==='mira'?'data:image/webp;base64,':'data:image/webp;base64,',`data-v24visit="${x.id}"`)).join('');const left=`<div class="visitStage40"><div class="visitPortrait40">${id==='mira'?'△':'◇'}</div><div class="bubbleLarge40" id="visitBubble">무슨 일이지?</div></div><div class="visualCardList40">${choices}</div>`;const right=`<div class="serviceCard40"><div class="dualTitle"><div><b>${n.name}</b><span>현재 친밀도 ${Math.round(Number(n.affinity)||0)}</span></div></div><div class="modalDesc">관계는 처세의 관계망 보정에 반영된다.</div></div>`;openModal(serviceShell40(`${n.name} 방문`,`현재 친밀도 ${Math.round(Number(n.affinity)||0)} · 관계는 처세의 관계망 보정에 반영된다.`,'visit',left,right,'VISIT EVENT'));bindClose();document.querySelectorAll('[data-v24visit]').forEach(b=>b.onclick=()=>{const x=topics.find(t=>t.id===b.dataset.v24visit);if(!x)return;$('visitBubble').textContent=x.a;state.visitIntel=x.intel;n.affinity=clamp((Number(n.affinity)||0)+4,0,100);recordDeed('social',`${state.year}-${state.month}:visit:${id}:${x.id}`);addLog(`${n.name}과 이야기를 나눴다. 친밀도 +4`);saveGame();render();});}


// v4.0.1: restore v2.8 NPC conversation logic while keeping v4.0 visual cards.
// Do not recreate an independent affinity system: one +1 per month and 80 daily cap are canonical.
startVisit = function(id){
  ensureV30State();ensureV26Progression();
  const n=state.contacts?.[id];
  if(!n || n.alive===false || n.present===false){openContacts();return;}
  const topics=visitTopicsV28(id,n),a=clamp(Math.round(Number(n.affinity)||0),0,100);
  const cards=topics.map(t=>choiceCardVisual40(t.q,'대화를 이어간다','대화',id==='mira'?'data:image/webp;base64,':'data:image/webp;base64,',`data-v28-visit="${t.id}"`)).join('');
  const left=`<div class="visitStage40"><div class="visitPortrait40">${contactAvatarV28(n)}</div><div class="bubbleLarge40" id="visitBubble">“왔군. 들어와. 오늘은 무슨 얘기를 하려고?”</div></div><div class="visitRelationLine"><span>관계 <b>${relationStageV28(a)}</b></span><span>친밀도 <b id="visitAffinity">${a}</b></span></div><div class="visualCardList40">${cards}</div><div class="resonanceHint">일상 대화의 친밀도는 월 1회 +1, 최대 80. 이후 성장은 별도 사건으로 가능하다.</div>`;
  const right=`<div class="serviceCard40"><div class="dualTitle"><div><b>${n.name}</b><span>${contactPlaceV28(id,n)}</span></div></div><div class="modalDesc">대화 주제를 반복하면 다른 반응이 나올 수 있지만, 친밀도 보상은 월 1회만 적용된다.</div></div>`;
  openModal(serviceShell40(`${n.name} 방문`,`${contactPlaceV28(id,n)} · ${relationStageV28(a)}`,'visit',left,right,'VISIT EVENT'));
  bindClose();
  document.querySelectorAll('[data-v28-visit]').forEach(b=>b.onclick=()=>{
    const topic=topics.find(t=>t.id===b.dataset.v28Visit);if(!topic)return;
    const key=`${id}:${topic.id}`,count=Number(state.contactDialogueCounters[key]||0);
    state.contactDialogueCounters[key]=count+1;
    const reply=topic.replies[count%topic.replies.length];
    $('visitBubble').textContent=reply;
    state.visitIntel=`${n.name}: ${reply.replace(/[“”]/g,'')}`;
    const gain=grantRegularAffinityV28(id);
    recordDeed('social',`${v28MonthKey()}:visit:${id}`);
    if(gain)addLog(`${n.name}과 시간을 보내며 친밀도 +${gain}`);
    else addLog(`${n.name}과 이야기를 나눴다.`);
    if($('visitAffinity'))$('visitAffinity').textContent=Math.round(Number(n.affinity)||0);
    saveGame();render();
  });
};

/* v4.1: coherent mobile weapon assembly art and full-screen equipment UI */
const SWORD_ASSETS41={"blade":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"guard":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"grip":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"pommel":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]};
const ODYSSEY_OWNER_ART='data:image/webp;base64,';
function wc41PartIndex(part,id){const keys=Object.keys(PART_CATALOG[part]||{});return Math.max(0,keys.indexOf(id));}
function wc41Variant(part,id){return wc41PartIndex(part,id)%4;}
function wc41PartTint(part,id){const i=wc41PartIndex(part,id);const hue=(Math.floor(i/4)*21)%84;const sat=1+(Math.floor(i/4)%3)*.07;return `hue-rotate(${hue}deg) saturate(${sat}) drop-shadow(0 3px 5px #0007)`;}
function weaponArt41(overrides={},cls='wc41-artLarge'){
 const cur=state.weapon.parts||{};
 const img=(type)=>{const id=overrides[type]||cur[type];const arr=SWORD_ASSETS41[type];return `<img alt="" draggable="false" src="${arr[wc41Variant(type,id)]}" style="filter:${wc41PartTint(type,id)}"/>`;};
 return `<div class="wc41-art ${cls}" role="img" aria-label="장착 파츠로 조립된 현재 검">${img('blade')}${img('grip')}${img('guard')}${img('pommel')}</div>`;
}
function weaponSvgHtml39(){return weaponArt41({},'wc41-artSmall');}
function renderWeaponVisual39(targetId='weaponVisualWrap'){const el=$(targetId);if(el)el.innerHTML=weaponArt41({},'wc41-artSmall');}
function equipmentVisualHtml(){const w=state.weapon;const slots=Object.keys(PART_LABELS);return `<div class="wc41-smithPreview">${weaponArt41({},'wc41-smithSword')}<div class="wc41-smithPreviewMeta"><b>${partItem('blade').name}</b><span>내구 ${Math.round(w.dur)}/${Math.round(w.maxDur)} · 공명 ${Math.round(w.resonance)}/${Math.round(w.maxResonance)}</span><div class="wc41-smithSlotList">${slots.map(k=>`<div><b>${PART_LABELS[k]}</b><span>${partItem(k).name}</span></div>`).join('')}</div></div></div>`;}
function wc41WeaponFactHtml(){const w=state.weapon;return `<div class="wc41-weaponFacts"><div>길이 / 중량<b>${Math.round(w.length)}cm / ${w.weight.toFixed(2)}kg</b></div><div>내구도<b>${Math.round(w.dur)} / ${Math.round(w.maxDur)}</b></div><div>공명<b>${Math.round(w.resonance)} / ${Math.round(w.maxResonance)}</b></div><div>위력 / 정밀<b>${Math.round(w.power)} / ${Math.round(w.precision)}</b></div><div>견고 / 조작성<b>${Math.round(w.toughness)} / ${Math.round(w.handling)}</b></div></div>`;}
function openWeaponDetail(){ensureV24State();recalcWeapon();const slots=Object.keys(PART_LABELS),p=weaponProfile();const list=slots.map(slot=>{const it=partItem(slot),n=Object.entries(state.weapon.spareParts).filter(([id,cnt])=>cnt>0&&findPartSlot(id)===slot).reduce((a,[_id,cnt])=>a+cnt,0);return `<button class="wc41-part" data-weapon-slot="${slot}"><b>${PART_LABELS[slot]}</b><span class="wc41-partName">${it.name}</span><small>교체 가능한 예비 부품 ${n}개</small></button>`;}).join('');const body=`<div class="wc41-weaponModal"><div class="wc41-weaponArtBox">${weaponArt41()}<div><h3>${partItem('blade').name}</h3><div class="wc41-modalNote">${p.name} · ${p.desc}</div>${wc41WeaponFactHtml()}</div></div><div class="wc41-sectionLabel">부품 교체 · 8개 슬롯</div><div class="wc41-modalNote">부품을 선택하면 교체 가능한 부품이 나타난다. 교체 시 검 그림과 능력치가 함께 변경된다.</div><div class="wc41-partGrid">${list}</div><details><summary class="wc41-sectionLabel">검의 계보 보기</summary>${weaponLineageHtml()}</details></div>`;openModal(modalHead('무기 관리','현재 검의 실제 조립 상태 · 부품 교체는 즉시 반영된다.')+body);bindClose();document.querySelectorAll('[data-weapon-slot]').forEach(b=>b.onclick=()=>openWeaponEquipSlot(b.dataset.weaponSlot));}
function openWeaponEquipSlot(slot){ensureV24State();const cur=state.weapon.parts[slot],ids=Object.entries(state.weapon.spareParts).filter(([id,n])=>n>0&&findPartSlot(id)===slot);const rows=ids.map(([id,n])=>{const it=PART_CATALOG[slot]?.[id];return `<button class="wc41-partOption" data-weapon-equip="${id}"><b>${it.name}</b><span>${it.material} · 보유 ${n}개</span><small>선택하면 즉시 장착 · 기존 부품은 예비품으로 이동</small></button>`;}).join('')||'<div class="wc41-modalNote">이 슬롯의 예비 부품이 없습니다. 대장간에서 구입하거나 제작할 수 있습니다.</div>';const left=ids.length?weaponArt41({[slot]:ids[0][0]},'wc41-compareArt'):weaponArt41({},'wc41-compareArt');const body=`<div class="wc41-weaponModal"><div class="wc41-sectionLabel">${PART_LABELS[slot]} 교체</div><div class="wc41-modalNote">현재 장착: ${PART_CATALOG[slot]?.[cur]?.name||cur}</div>${left}<div class="wc41-sectionLabel">예비 파츠 ${ids.reduce((a,x)=>a+x[1],0)}개</div><div class="wc41-partOptions">${rows}</div><button class="wc41-part" id="wc41GoBack">← 현재 검 보기</button></div>`;openModal(modalHead(PART_LABELS[slot]+' 선택','교체 전후의 실제 검 외형을 확인할 수 있습니다.')+body);bindClose();$('wc41GoBack').onclick=openWeaponDetail;document.querySelectorAll('[data-weapon-equip]').forEach(b=>{b.onmouseenter=()=>{const art=document.querySelector('.wc41-compareArt');if(art)art.outerHTML=weaponArt41({[slot]:b.dataset.weaponEquip},'wc41-compareArt');};b.onclick=()=>{const id=b.dataset.weaponEquip;if(!spareCount(id))return;addSpare(id,-1);addSpare(cur,1);state.weapon.parts[slot]=id;recalcWeapon();addLog(`${PART_LABELS[slot]}을 ${PART_CATALOG[slot][id].name}(으)로 교체했다.`);saveGame();render();openWeaponDetail();};});}
const _renderWc41=render;
render=function(){const out=_renderWc41();if(state.owner.portrait==='odyssey'){$('heroImg').src=ODYSSEY_OWNER_ART;$('heroImg').style.display='block';}const used=typeof v35BagUsed==='function'?['consumable','material','armor','part'].reduce((a,t)=>a+v35BagUsed(t),0):0;const cap=typeof v35BagCap==='function'?['consumable','material','armor','part'].reduce((a,t)=>a+v35BagCap(t),0):0;$('inventoryBtn').title=`인벤토리 ${used}/${cap}`;renderWeaponVisual39();return out;};


/* v4.2 compact commerce and dedicated sword art */
const PART_ASSETS42={"blade":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"guard":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"grip":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"pommel":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"scabbard":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]};
// All functions are reassigned inside the original gameplay closure: save data and rules are retained.
serviceShell40 = function(title,desc,kind,leftHtml,rightHtml='',kicker=''){
  // The original 160+ pixel repeated painting and side-by-side owner board consumed most of the phone.
  // A single dialog heading is enough; detailed ownership stays accessible on demand.
  const optional = rightHtml?`<details class="wc42-disclosure"><summary>${kind==='smith'?'현재 검 · 장착 파츠 · 보유 재료':kind==='market'?'소유 장비 · 보관함 · 판매':kind==='temple'?'상태 및 이용 안내':'추가 정보 보기'}</summary>${rightHtml}</details>`:'';
  return modalHead(title,desc)+`<section class="serviceShell40 wc42-compact" data-service="${kind}"><div class="serviceHero40"><div class="serviceBody40">${leftHtml}</div></div>${optional}</section>`;
};
// New art is drawn as independent equipment components, never extracted from event scenes.
weaponArt41 = function(overrides={},cls='wc41-artLarge'){
  const parts=state.weapon.parts||{};
  const order=['scabbard','blade','guard','grip','pommel'];
  const layer=type=>{
    const id=overrides[type]||parts[type]||'';
    const v=wc41Variant(type,id);
    return `<img class="wc42-layer wc42-${type}" alt="" draggable="false" src="${PART_ASSETS42[type][v]}" data-part="${type}" data-partid="${id}"/>`;
  };
  return `<div class="wc41-art ${cls} wc42-weapon-art" role="img" aria-label="칼날, 가드, 손잡이, 폼멜, 검집을 조립한 검">${order.map(layer).join('')}</div>`;
};
weaponSvgHtml39 = function(){return weaponArt41({},'wc41-artSmall');};
renderWeaponVisual39 = function(targetId='weaponVisualWrap'){
  const el=$(targetId);if(el)el.innerHTML=weaponArt41({},'wc41-artSmall');
};
openContacts = function(){
  ensureV26Progression();
  const entries=Object.entries(state.contacts||{});
  const roster=entries.map(([id,n])=>{
    const affinity=Math.round(Number(n.affinity)||0);
    return `<button type="button" class="wc42-person" data-contact-open="${id}"><span class="wc42-avatar">${contactAvatarV28(n)}</span><span><b>${n.name}</b><small>${contactPlaceV28(id,n)} · ${relationStageV28(affinity)}</small></span><span class="wc42-affinity">${affinity} / 100 <span aria-hidden="true">›</span></span></button>`;
  }).join('')||'<p>현재 방문 가능한 인물이 없습니다.</p>';
  openModal(modalHead('방문','방문할 인물을 고르세요. 관계와 친밀도를 확인할 수 있습니다.')+`<div class="wc42-visitRoster">${roster}</div>`);
  bindClose();document.querySelectorAll('[data-contact-open]').forEach(b=>b.onclick=()=>startVisit(b.dataset.contactOpen));
};
startVisit = function(id){
  ensureV26Progression();const npc=state.contacts?.[id];if(!npc)return;
  const topics=visitTopicsV28(id,npc),cur=Math.round(Number(npc.affinity)||0);
  const choices=topics.map(t=>`<button type="button" class="wc42-topic" data-v42-talk="${t.id}">${t.q}</button>`).join('');
  openModal(modalHead(`${npc.name} 방문`,`${contactPlaceV28(id,npc)} · ${relationStageV28(cur)}`)+
    `<div class="wc42-visitTop"><div class="wc42-avatar">${contactAvatarV28(npc)}</div><div><b>${npc.name}</b><small style="display:block;color:#b9aa93;font-size:10px">친밀도 <span id="wc42-affinity">${cur}</span> / 100 · 월 1회 +1</small></div></div>`+
    `<div class="wc42-speech" id="wc42-quote">“왔군. 들어와. 오늘은 무슨 얘기를 하려고?”</div>`+
    `<div class="wc42-topicList">${choices}</div><button type="button" class="selectionChangeBtn" id="wc42-return" style="margin-top:10px">← 다른 인물 방문</button>`);
  bindClose();$('wc42-return').onclick=openContacts;
  document.querySelectorAll('[data-v42-talk]').forEach(b=>b.onclick=()=>{
    const topic=topics.find(t=>t.id===b.dataset.v42Talk);if(!topic)return;
    const k=`${id}:${topic.id}`,ct=state.contactDialogueCounters[k]||0;
    state.contactDialogueCounters[k]=ct+1;
    const line=topic.replies[ct%topic.replies.length];
    $('wc42-quote').textContent=line;
    state.visitIntel=`${npc.name}: ${line.replace(/[“”]/g,'')}`;
    const gained=grantRegularAffinityV28(id); // original monthly +1 only, capped at 80
    recordDeed('social',`${v28MonthKey()}:visit:${id}`);
    addLog(gained?`${npc.name}과 시간을 보내며 친밀도 +${gained}`:`${npc.name}과 이야기를 더 나눴다.`);
    $('wc42-affinity').textContent=Math.round(Number(npc.affinity)||0);
    saveGame();
  });
};
// Keep all original transaction checks/handlers; add a clear tap target to rendered entries.
const wc42OriginalSmithBuy=openSmithBuy;
const wc42OriginalSmithSell=openSmithSell;
const wc42OriginalSmithCraft=openSmithCraft;
function wc42DecorateTrade(selector,label){
  document.querySelectorAll(selector).forEach(button=>{
    button.classList.add('wc42-trade-row');
    const tag=document.createElement('span');tag.className='wc42-trade-tag';
    tag.textContent=button.disabled?'조건 부족':label;button.append(tag);
  });
}
openSmithBuy=function(slot=null){wc42OriginalSmithBuy(slot);wc42DecorateTrade('[data-smith-buy]','구매');};
openSmithSell=function(slot=null){wc42OriginalSmithSell(slot);wc42DecorateTrade('[data-smith-sell]','판매');};
openSmithCraft=function(slot=null){wc42OriginalSmithCraft(slot);wc42DecorateTrade('[data-smith-craft]','제작');};

/* v4.3 selective return to two-pane equipment trading and focused owner resonance */
const WC43_GEAR = {
  helmet:'data:image/webp;base64,',armor:'data:image/webp;base64,',gloves:'data:image/webp;base64,',boots:'data:image/webp;base64,'
};
const WC43_PART_ICONS={"blade":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"guard":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"grip":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"pommel":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"],"scabbard":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]};
let wc43ArmorFilter = null;
function wc43GearThumb(slot,cls='wc43-itemImg'){
  return `<img class="${cls}" loading="lazy" alt="${OWNER_GEAR_SLOTS[slot]||slot}" src="${WC43_GEAR[slot]}">`;
}
function wc43PartThumb(slot,id,cls='wc43-itemImg'){
  const type=({tang:'blade',wrap:'grip',seat:'guard'})[slot]||slot;
  const assets=WC43_PART_ICONS[type];
  if(!assets)return `<span class="wc43-thumbEmpty">◇</span>`;
  return `<img class="${cls}" loading="lazy" alt="${PART_LABELS[slot]}" src="${assets[wc41Variant(type,id||state.weapon.parts[slot]||'')]}"/>`;
}
function wc43StatsForArmor(id){
  return gearEffectText(id).replace(/\s*·\s*/g,' <em class="wc43-dot">·</em> ');
}
function wc43ArmorSlots(){
  return Object.entries(OWNER_GEAR_SLOTS).map(([slot,label])=>{
    const id=state.ownerEquipment[slot],it=OWNER_GEAR_CATALOG[id];
    return `<button type="button" class="wc43-slot ${wc43ArmorFilter===slot?'selected':''} ${it?'equipped':''}" data-v43-armor-slot="${slot}">
       ${wc43GearThumb(slot)}<b>${label}</b><small>${it?it.name:'비어 있음'}</small>
    </button>`;
  }).join('');
}
function wc43MarketArmor(){
  ensureV24State();
  if(!state.marketV24?.armor?.length)resetMarketStock();
  const list=(state.marketV24.armor||[]).filter(row=>!wc43ArmorFilter||OWNER_GEAR_CATALOG[row.id]?.slot===wc43ArmorFilter);
  const rows=list.map(row=>{
    const it=OWNER_GEAR_CATALOG[row.id];if(!it)return '';
    const can=!row.sold&&state.gold>=it.price&&hasOwnerCapacity(1,'armor',row.id);
    return `<div class="wc43-shopItem rarity-${it.rarity}">
      ${wc43GearThumb(it.slot)}<div class="wc43-shopInfo"><b>${it.name}</b><small>${OWNER_GEAR_SLOTS[it.slot]}</small><div class="wc43-gearEffects">${wc43StatsForArmor(row.id)}</div></div>
      <div class="wc43-priceCol"><strong>${row.sold?'완료':it.price+'G'}</strong><button type="button" data-buy-armor="${row.id}" ${can?'':'disabled'}>구매</button></div>
    </div>`;
  }).join('')||'<div class="wc43-empty">이 부위에 입고된 상품이 없습니다. 전체 보기를 선택하세요.</div>';
  const owned=Object.entries(state.ownerGearOwned||{}).filter(([id,n])=>n>0&&OWNER_GEAR_CATALOG[id]&&(!wc43ArmorFilter||OWNER_GEAR_CATALOG[id].slot===wc43ArmorFilter));
  const ownedRows=owned.map(([id,n])=>{
    const it=OWNER_GEAR_CATALOG[id],eq=Object.values(state.ownerEquipment).includes(id);
    return `<div class="wc43-ownedLine">${wc43GearThumb(it.slot,'wc43-ownedImg')}<span><b>${it.name}</b><small>×${n}</small></span><div class="wc43-ownedBtns"><button type="button" data-equip-gear="${id}" ${eq?'disabled':''}>${eq?'장착':'장착'}</button><button type="button" data-sell-owner-gear="${id}" ${eq?'disabled':''}>판매</button></div></div>`;
  }).join('')||'<div class="wc43-miniEmpty">해당 부위 보유품 없음</div>';
  const cost=state.marketRefreshFree?0:8;
  openModal(modalHead('시장 · 방어구',`GOLD ${state.gold}G · ${v35BagSummary('armor')}`)+marketTabsV24('armor')+
    `<div class="wc43-tradeLayout wc43-market"><div class="wc43-leftPane">
      <div class="wc43-paneHead"><b>${wc43ArmorFilter?OWNER_GEAR_SLOTS[wc43ArmorFilter]:'전체 방어구'} 상품</b><span>상점 재고</span></div><div class="wc43-items">${rows}</div>
    </div><div class="wc43-rightPane"><div class="wc43-paneHead"><b>소유자 장비</b><span>부위 선택</span></div>
      <button type="button" class="wc43-all ${wc43ArmorFilter?'':'selected'}" id="wc43-armor-all">전체 보기</button><div class="wc43-slotGrid">${wc43ArmorSlots()}</div>
      <div class="wc43-compactHeading">보유 · 장착 / 판매</div><div class="wc43-ownedList">${ownedRows}</div>
    </div></div><div class="wc43-bar"><span>${state.gold}G · 방어구 독립 보관</span><button id="wc43-refresh" ${cost&&state.gold<cost?'disabled':''}>재고 교체 ${cost?cost+'G':'무료'}</button></div>`);
  bindClose();
  document.querySelectorAll('[data-v24market]').forEach(b=>b.onclick=()=>openMarket(b.dataset.v24market));
  $('wc43-armor-all').onclick=()=>{wc43ArmorFilter=null;wc43MarketArmor();};
  document.querySelectorAll('[data-v43-armor-slot]').forEach(b=>b.onclick=()=>{wc43ArmorFilter=b.dataset.v43ArmorSlot;wc43MarketArmor();});
  $('wc43-refresh').onclick=()=>refreshMarket('armor');
  document.querySelectorAll('[data-buy-armor]').forEach(b=>b.onclick=()=>{
    const id=b.dataset.buyArmor,it=OWNER_GEAR_CATALOG[id],row=state.marketV24.armor.find(x=>x.id===id&&!x.sold);
    if(!row||!it||state.gold<it.price||!hasOwnerCapacity(1,'armor',id))return;
    state.gold-=it.price;row.sold=true;state.ownerGearOwned[id]=(state.ownerGearOwned[id]||0)+1;
    addLog(`${it.name}을 구입했다.`);saveGame();wc43MarketArmor();render();
  });
  document.querySelectorAll('[data-equip-gear]').forEach(b=>b.onclick=()=>{equipOwnerGear(b.dataset.equipGear);wc43MarketArmor();});
  document.querySelectorAll('[data-sell-owner-gear]').forEach(b=>b.onclick=()=>{sellOwnerGear(b.dataset.sellOwnerGear);wc43MarketArmor();render();});
}
const wc43OriginalMarket=openMarket;
openMarket=function(tab='healer'){
  if(tab==='armor'){wc43MarketArmor();return;}
  wc43ArmorFilter=null;wc43OriginalMarket(tab);
};
const wc43OriginalSmithShell=smithWorkbenchShell;
