 addWorldFact(`제${c.act}장 CH.${c.local} ${c.title} — ${c.outro}`,`odyssey_v47_${c.no}`);
 if(result==='won'||result==='resolved'){
   state.weapon.resonance=clamp(state.weapon.resonance+Math.min(4,c.act),0,state.weapon.maxResonance);
   if(c.no%3===0)state.gold+=Math.max(3,Math.floor(c.act*2));
 }else{state.mind=clamp(state.mind-2,0,100);}
